    \caption{Depiction of the experimental simulation in the NVIDIA \texttt{Isaac Sim} environment. The \textcolor{blue}{blue} line depicts the separation of the terrains with different \texttt{GD} values.}
    \label{fig:simulation}
\end{figure}
\begin{figure}[h]
    \centering
    \includegraphics[scale = 0.5,width = 90mm]{images/Vert_Disp_Truth.png}
