    \includegraphics[scale=0.5, width=90mm]{images/multiple_GD_exp_results.png}
    \caption{Variation in \texttt{GD} values over the terrain as measured by the BCR for Test Case A. The \textcolor{black}{black} line corresponds to the change in roughness of the terrain shown in Figure \ref{fig:simulation}.}
    \label{fig:GD_plots}
\end{figure}
\begin{figure}[h]
