	\hspace*{-2mm}	 	
    \vspace{-1mm}
	\includegraphics[width = \columnwidth]{R-4G.pdf} 	
    \caption{$90\,\%$ combined confidence bands using random ordering, \eqref{set-permutation}.}
\label{fig:random-ordering}
\end{figure}
