        & \multicolumn{4}{c}{Voter} \\
        Rounds & 1 & 2 & 3 & 4 & 5 & 6 \\
        \midrule
        1 & $\underline{a}$ & $\underline{a}$ & $\underline{a}$ & $b$ & $b$ & $b$ \\
        2 & $\underline{a}$ & $\underline{a}$ & $\underline{a}$ & $b$ & $b$ & $b$ \\
        3 & $\underline{a}$ & $\underline{a}$ & $\underline{a}$ & $b$ & $c$ & $d$ \\
