	\title{Runge--Kutta generalized Convolution Quadrature for sectorial problems}
	\author{J. Guo \thanks{ Department of Mathematics, University of Macau, Macao SAR, China. Email: {\tt jingguo@um.edu.mo}} \and M. Lopez-Fernandez\thanks{Department of Mathematical Analysis, Statistics and O.R., and Applied Mathematics.
			Fa\-cul\-ty of Sciences. University of Malaga.
			Bulevar Louis Pasteur, 31
			29010  Malaga,  Spain. Email: {\tt maria.lopezf@uma.es}}}
	\maketitle
	\begin{abstract}
		We study the application of the generalized convolution quadrature (gCQ) based on Runge--Kutta methods to approximate the solution of an important class of sectorial problems. The gCQ  generalizes Lubich's original convolution quadrature (CQ) to variable steps. High-order versions of the gCQ  have been developed in the last decade, relying on certain Runge--Kutta methods. The Runge--Kutta based gCQ  has been studied so far in a rather general setting, which includes applications to boundary integral formulations of wave problems. The available stability and convergence results for these new methods are suboptimal compared to those known for the uniform-step CQ, both in terms of convergence order and regularity requirements of the data. Here we focus on a special class of sectorial problems and prove that in these important applications it is possible to achieve the same order of convergence as for the original CQ, under the same regularity hypotheses on the data, and for very general time meshes. In the particular case of data with some known algebraic type of singularity, we also show how to choose an optimally graded time mesh to achieve convergence with maximal order, overcoming the well-known order reduction of the original CQ in these situations. 
		An important advantage of the gCQ  method is that it allows for a fast and memory-efficient implementation. We describe how the fast and oblivious Runge--Kutta based gCQ  can be implemented and illustrate our theoretical results with several numerical experiments. The codes implementing the examples in this article are available in \cite{codesGuoLo25}.
	\end{abstract}

	{\bf Keywords:} generalized convolution quadrature, sectorial problems, variable steps, graded meshes, fractional differential equations, equations with memory.

	{\bf AMS subject classifications:} 65R20, 65L06, 65M15,26A33,35R11.



	\section{Introduction}

	In this work, we consider the high-order numerical approximation of Volterra-type convolution operators of the abstract form
	\begin{equation}\label{conv}
		u(t) = \int_0^tk(t-s) f(s)\, ds, \quad t > 0,
	\end{equation}
	on general non-uniform temporal meshes
	\begin{equation}\label{mesh}
		\Delta := \{0 = t_0 < t_1 < \cdots < t_N = T\},
	\end{equation}
	with step sizes defined as 
	\[\tau_n := t_n - t_{n-1},\quad n = 1, \ldots, N.\]
	The maximum and minimum step sizes are denoted by
	\begin{equation}\label{tau_maxmin}  
		\tau_{\max} := \max_{1 \leq j \leq N} \tau_j, \quad \tau_{\min} := \min_{1 \leq j \leq N} \tau_j.  
	\end{equation} 
	The  numerical discretization of \eqref{conv} has been extensively studied due to its  appearance in a wide range of models, including fractional differential equations \cite{BanLo19,JingRebecca_fi,Lu88II,Podlubny,McSloTho2006}, viscoelasticity \cite{Gorenflo2020} and time-domain boundary integral equations \cite{BanLuMe,Lu94,LuScha2002}. 	The convolution kernel \( k(t) \) can take various forms depending on the problem setting. Typical examples include scalar-valued kernels like \( k(t) = t^{\alpha} \) with \( \alpha > -1 \), which arise in fractional integral operators \cite{BanLo19,SamkoKilbasMarichev,Lu86}; operator-valued kernels such as \( k(t) = e^{\mathcal{A}t} \), representing semigroups generated by linear operators \cite{LoLuPaScha,CuLuPa}; and Green's functions in boundary integral equations \cite{BanLo20,SautSch}, including distributional kernels such as the Dirac delta that appears in wave propagation problems \cite[Chapter 2]{BanSay22}.

	Let $K(z)$ denote the Laplace transform of  $k(t)$. We assume that $K$ acts as a bounded linear operator between normed vector spaces $\mathcal{X}$ and $\mathcal{Y}$, with norm
	\[
	\|K(z)\| := \sup_{\substack{u\in\mathcal{X}, \|u\|_{\mathcal{X}}=1}} \|K(z)u\|_{\mathcal{Y}}.
	\]
	The Laplace transform \( K(\cdot) \), which is referred to as the \emph{transfer operator} in many applications, plays a fundamental role in  Convolution Quadrature (CQ) methods, introduced in  Lubich's pioneering work \cite{Lu88I,Lu88II}. %, this operator is evaluated at the generating functions of either linear multistep methods or Runge--Kutta methods \cite{LuOs,BanLu}, which facilitates the discretization of \eqref{conv} via contour integrals in the Laplace domain.  
	In this work, we focus on a special class of sectorial problems, characterized by the following conditions on $K$:
	\begin{assumption}\label{assumptionK}
		The transfer operator $K$ satisfies:
		\begin{enumerate}  
			\item $K$ is holomorphic in the sector $|\arg(z)|<\pi$.
			\item There exist constants $M>0$ and $\alpha \in (0,1)$ such that
			\begin{equation}\label{Kz}
				\|K(z)\|_{\mathcal{X}\to\mathcal{Y}} \leq M |z|^{-\alpha}, \qquad |\arg(z)|<\pi.
			\end{equation}
			\item $K$ is continuous in the closed upper half-plane $\Im z \ge 0$, except possibly at $z=0$, and similarly on the lower edge of the branch cut.
		\end{enumerate}  
	\end{assumption}

	When unambiguous, norm subscripts are omitted. 
	The conditions on \( K(z) \) cover a large and important range of examples, such as \( K(z) = z^{-\alpha} \), which corresponds to fractional integrals \cite{BanLo19,JingRebecca_fi,Lu86,Podlubny}; \( K(z) = (z^\alpha + r)^{-1} \) with \( r > 0 \), which is the Laplace transform of kernels usually used in damped wave models, see for instance \cite{BaBanPtas24}; also \( K(z) = (z^{\alpha} I + \mathcal{A})^{-1} \),  where \( \mathcal{A} \) is a symmetric positive definite operator or matrix \cite{GuoLo,JinLiZh,LiMa}.

	Under Assumption~\ref{assumptionK}, the convolution kernel $k$ admits a real integral representation, cf. \cite{BanLo19, GuoLo}:	
	\begin{equation}\label{Gx}  
		k(t) = \int_0^\infty e^{-xt} G(x)\, dx, \quad 
		G(x) := \frac{K(x e^{-i\pi}) - K(x e^{i\pi})}{2\pi i},
	\end{equation}
	with the operator $G$ satisfying the bound
	\begin{equation}\label{Gx_bnd}  
		\|G(x)\| \leq \frac{M}{\pi} x^{-\alpha}, \quad x > 0, \quad 0 < \alpha < 1.  
	\end{equation}  
	For the particular example of the fractional integral, with \( k(t) = t^{\alpha - 1}/\Gamma(\alpha) \), the corresponding function \( G(x) \) is given by
	\begin{equation}\label{Gx_fracint}
		G(x) = \frac{\sin(\pi \alpha)}{\pi} x^{-\alpha}.
	\end{equation}
	For $K(z) = (z^{\alpha} I + \mathcal{A})^{-1}$, explicit formulas for $G$ are derived in \cite[Section 4]{GuoLo}. Other examples are considered in detail in Section~\ref{sec:num_test}.

	The representation in \eqref{Gx} has been successfully employed  in \cite{BanLo19}  for the efficient nu\-me\-ri\-cal solution of subdiffusion equations on uniform temporal grids, allowing for a special fast and oblivious quadrature which significantly improves the
	computational efficiency, the memory requirements and the coding.  In \cite{BanMak2022}, the Euler based gCQ weights for the fractional derivative are derived using \eqref{Gx_fracint}, and {\em a posteriori} error estimates for the application of this method to the subdiffusion equation are established. The study in \cite{GuoLo} is also based on \eqref{Gx}, where under Assumption~\ref{assumptionK}, optimal {\em a priori} error bounds are proven for the Euler based gCQ  method, together with a generalization of the fast and oblivious algorithm in \cite{BanLo19} to the case of general nonuniform meshes. So far all available studies based on \eqref{Gx} for the gCQ  are limited to the first order version of it. High order versions of the gCQ  based on Runge--Kutta methods have been proposed and analyzed in \cite{LoSau16} for more general problems than the ones considered in the present manuscript, for which high order but non optimal error estimates are proven, under very strong regularity assumptions on the data $f$.

	Original CQ methods, defined on uniform time meshes, require quite some regularity of the input data \( f(t) \) in order to achieve their maximal order. In particular, the extension of $f$ to $t<0$ by $0$ is typically required to be several times differentiable, which leads to the request that a certain number of the moments of $f$ at $t=0$ vanish \cite{LuOs,BanLu11}. In many practical applications this is not the case and a well known order reduction takes place \cite{Lu88I}, even if correction terms can be added to improve the performance at times away from 0, see for instance \cite{BanMak2022,CuLuPa,JinLiZh,Lu2004}. Moreover, singularities of the data $f$ at other time points can not be properly resolved by the original CQ formulas.  This limitations have motivated the development and analysis of the so-called generalized Convolution Quadrature (gCQ) methods \cite{BanFer23,LoSau13,LoSau15apnum,LoSau16, GuoLo}. In particular, under Assumption~\ref{assumptionK}, a sharp error analysis is performed  in \cite{GuoLo}, for data $f$ satisfying the minimal regularity requirement 
	\begin{equation}\label{dataform}
		f(t) = t^\beta g(t), \quad \beta > -1,
	\end{equation}
	where \( g \) is smooth. In this work, the study in \cite{GuoLo} is generalized to high-order gCQ  based on Runge--Kutta methods. We actually improve further the regularity requirements on the data $f$ in \cite{GuoLo} by using distributional derivatives rather than the mean value theorem in the estimation of the local error reminders, see Remark~\ref{remark:improvegCQ1}. In this way, for problems satisfying Assumption~\ref{assumptionK}, we manage to achieve full order of convergence for the Runge--Kutta gCQ under the very same assumptions as the original Lubich's CQ with uniform step size, see \cite{LuOs}. 

	In what follows we consider \( s \)-stage Runge--Kutta schemes with coefficient matrix \( \Av \), weights \( \bv \), and abscissas \( \cv \), satisfying the following conditions.
	\begin{assumption}\label{ass_RK}
		The Runge--Kutta method is A-stable, that is,
		\begin{equation}\label{Rz_Astab}
			|R(z)| \le 1 \quad \text{for } \Re z \le 0,
		\end{equation}
		with classical order $p \ge 1$, stage order $q \le p$, and is stiffly accurate, meaning
		\begin{equation}\label{stiff_RK}
			\bv=\Av^\top\ev_s, \quad \text{with } \ev_s=(0,\cdots,0,1)^\top\in \bR^s.
		\end{equation}
	\end{assumption}

	Notice that \eqref{Gx}  yields the alternative formulation of \eqref{conv}:
	\begin{equation*}\label{conv_real}
		u(t) = \int_0^\infty G(x) y(x,t)\, dx, 
	\end{equation*}
	where $y(x,t)$ satisfies
	\begin{equation}\label{ode}  
		\partial_t y(x,t) = -x y(x,t) + f(t), \quad y(x,0) = 0.
	\end{equation}  
	%and can be expressed as $y(x,t) = \int_0^t e^{-x(t-s)} f(s)\, ds$.    
	The gCQ  approximation \( u_n \) to $u(t)$ at $t_n$, for \( 1 \leq n \leq N \), is obtained by applying the $s$-stage Runge--Kutta   method to approximate $y(x,t_n)$, this is 
	\begin{equation*}
		u_n = \int_0^\infty G(x) y_n(x)\, dx, 
	\end{equation*}
	with $y_n(x) \approx y(x,t_n)$. This definition of $u_n$ is equivalent to the definition in \cite{LoSau16} for general problems \eqref{conv}, where a complex contour integral representation is needed for both $u(t)$ and its numerical approximation. In the general setting, the following convergence result was established in \cite{LoSau16}:
	\begin{theorem}[Theorem 16 in \cite{LoSau16}]\label{th:convergence_regular}  
		Assume that	the Runge--Kutta method satisfies Assumption~\ref{ass_RK}, $f \in C^{p+2}([0,T])$ and $f^{(\ell)}(0) = 0$ for all $0 \leq \ell \leq q$.  Then, it holds
		\begin{equation}\nonumber
			\left\| u(t_n) - u_n \right\|_\mathcal{Y} \le C e^{\sigma T} \tau_{\max}^{q} \left\| f \right\|_{C^{p+2}([0,T],\mathcal{X})}, \quad n\ge 1.
		\end{equation}
	\end{theorem}  
	Here we analyze the error of the Runge--Kutta based gCQ  method applied to \eqref{conv}, with $f(t)$ like in \eqref{dataform}. More precisely, we assume that $f$ admits the fractional power expansion
	\begin{equation}\label{gen_f}
		f(t)= \sum_{\ell=0}^{m} \frac{f^{(\ell+\beta)}(0)}{\Gamma(\ell+\beta+1)} t^{\ell+\beta} + \frac{1}{\Gamma(m+\beta+1)} \left( t^{m+\beta} \ast f^{(m+\beta+1)}\right)(t),
	\end{equation}
	with the Riemann--Liouville derivative of order $\mu > 0$ defined as
	\[
	f^{(\mu)}(t) = \frac{d^\nu}{dt^\nu} \left(\int_0^t\frac{(t - s)^{\nu - \mu - 1}}{\Gamma(\nu - \mu)} f(s)\, ds\right),
	\]
	with $\nu := \lceil \mu \rceil$. The following Theorem is the main result of this paper and establishes the convergence error bounds of the Runge--Kutta based gCQ  for problems satisfying Assumption~\ref{assumptionK}. 
	\begin{theorem}\label{thm:conv_gCQrkGenM}
		For \( f(t) \) admitting the expansion \eqref{gen_f} with \(\beta > -1\) and \( m = \lceil p - \beta -1\rceil \), under Assumptions~\ref{assumptionK} and \ref{ass_RK}, the following error estimates hold true.
		\begin{enumerate}[label=(\roman*)]
			\item \label{itm:thm_genmesh} If  \( f^{(\ell+\beta)}(0) = 0 \) for all \( \ell = 0, 1, \dots, \lceil p - \alpha - \beta - 1 \rceil \), then on the general mesh \eqref{mesh}, the error satisfies
			% \[
			% \left\Vert u(t_n) - u_n \right\Vert_{\mathcal{Y}} \le C M \left| \log (\tau_{\min}) \right| \tau_{\max}^{\min\{p,q+1+\alpha\}},\quad n\ge 1.			\]
			\begin{align*}
				\left\Vert u(t_n) - u_n \right\Vert_{\mathcal{Y}} 
				&\le C M \left| \log (\tau_{\min}) \right| \tau_{\max}^{\min\{p,q+1+\alpha\}} 
				\left\| f^{(m+\beta+1)} \right\|_{C^0([0,t_n], \mathcal{X})},\quad n\ge 1.
			\end{align*}
			In particular, for the general mesh \eqref{mesh}, the full convergence order \( \min\{p, q + 1 + \alpha\} \) is achieved when \( f \in C^{p}([0,T]; \mathcal{X}) \) and satisfies the vanishing moment conditions \( f^{(\ell)}(0) = 0 \) for all \( \ell = 0, 1, \dots, p-1 \), which corresponds to the case \( \beta = 0 \).
			\item \label{itm:thm_quasimesh} If the mesh \eqref{mesh} is quasi-uniform, i.e.,  
			\begin{equation}\label{quasimesh}
				c_{\Delta} := \frac{1}{2} \max_{2 \le i \le N} \left( \frac{\tau_i}{\tau_{i-1}} + \frac{\tau_{i-1}}{\tau_i} \right)
			\end{equation}  
			is a bounded constant, and  
			\begin{equation*}
				f^{(\ell + \beta)}(0) = 0 \quad \text{for all } \ell = 0, 1, \dots, \min\left\{\lceil p - \alpha - \beta - 1 \rceil, \lceil q - \beta \rceil\right\},
			\end{equation*}  
			then for all \( n \ge 1 \), the error satisfies
			% \[
			% \left\Vert u(t_n) - u_n \right\Vert_{\mathcal{Y}} \le CM c_\Delta^{\max\{0,\, p- q-\alpha\}}  \left| \log (\tau_{\min}) \right| \tau_{\max}^{\min\{p,q+1+\alpha\}},\quad n\ge 1.	
			% \]
			\begin{align*}
				\left\Vert u(t_n) - u_n \right\Vert_{\mathcal{Y}} 
				&\le  CM c_\Delta^{\max\{0,\, p- q-\alpha\}}   \left| \log (\tau_{\min}) \right| \tau_{\max}^{\min\{p,q+1+\alpha\}} 
				\left\| f^{(m+\beta+1)} \right\|_{C^0([0,t_n], \mathcal{X})}.
			\end{align*}
		\end{enumerate}
		Here, \( C \) is a positive constant independent of the mesh.  
	\end{theorem}
	For graded meshes, which are quasi-uniform, the error can be estimated more precisely, without assuming any vanishing moments of the data $f$ at the origin.
	\begin{theorem}\label{thm:conv_gCQrkGrad}
		Suppose $f(t)$ admits an expansion of the form \eqref{gen_f} with \( \beta > -1 \) and \( m = \lceil p - \beta -1\rceil \). Under Assumptions~\ref{assumptionK} and~\ref{ass_RK}, the error of the Runge--Kutta based gCQ  method for \eqref{conv} on the graded mesh
		\begin{equation}\label{gmesh}
			t_n= (n\tau)^{\gamma}, \qquad \tau=\frac{T^{1/\gamma}}{N},\quad n=1,\dots,N,\quad \gamma\ge 1,
		\end{equation}
		satisfies
		\begin{align*}
			\nonumber
			\left\Vert u(t_n) - u_n \right\Vert_{\mathcal{Y}} &\le CM \sum_{\ell = 0}^{m} \log(N) \, N^{-\min\{ \gamma(\alpha + \ell + \beta),\, p,\, q + 1 + \alpha \}} \, \Vert f^{(\ell + \beta)}(0)\Vert_{\mathcal{X}} \\
			&\quad + CM \log(N) \, N^{-\min\{p,\, q + 1 + \alpha \}} \, \left\Vert f^{(m + 1 + \beta)} \right\Vert_{C^0([0, t_n], \mathcal{X})},
		\end{align*}
		where $C$ denotes a  positive constant independent of the mesh. 

		%	If $f^{(l+\beta)}(t) \ne 0$, $0\le l\le \lceil p - \beta -1\rceil $ it holds that
		%	\begin{equation}\label{err_nonsmooth}
			%		|u(t_n) - u_n| \leq C \log(N) \left\{
			%		\begin{array}{ll}
				%			N^{-\gamma(\alpha + \beta+l)}, & \quad \gamma(\alpha + \beta+l) < \min\{p, q + 1 + \alpha\}, \\[.5em]
				%			N^{-\min\{p, q + 1+\beta+l \}}, & \quad \gamma(\alpha + \beta+l) \ge \min\{p, q + 1 + \alpha\}.
				%		\end{array}
			%		\right.
			%	\end{equation}
		%	for any $1 \le n \le N$. 
	\end{theorem}

