	The paper is organized as follows.  
	Section~\ref{sec:rkgCQ} presents the framework of the Runge--Kutta  based gCQ  scheme.  
	Section~\ref{sec:stability} establishes the stability analysis, while Section~\ref{sec:err} derives error estimates for general and quasi-uniform meshes, along with a gra\-ding stra\-tegy for graded meshes.  
	Implementation details, including a fast algorithm for computing convolution integrals and its application to subdiffusion equations, are discussed in Section~\ref{sec:algfi}.  
	The numerical experiments in Section~\ref{sec:num_test} evaluate the performance of the proposed algorithm for convolution integrals, subdiffusion equations, and nonlinear wave equations with damping terms of the form \eqref{conv}.  
	In all cases, the Runge--Kutta based gCQ  scheme achieves significantly reduced maximum absolute errors compared to the uniform step size approximation provided by original Lubich's CQ, cf.~\cite{JinLiZh} for the subdiffusion equation and \cite{BaBanPtas24} for the damped Westervelt equation.  
	In particular, for the nonlinear Westervelt equation considered in~\cite{BanFer}, employing the two-stage Radau--IIA gCQ  method on a suitable graded mesh increases the convergence order from $1+\alpha$ to $3$. Also, the achieved errors are perfectly consistent with our theoretical results and much better than predicted by the available theory up to date in \cite{LoSau16}.






	\section{Runge--Kutta  based generalized convolution quadrature}\label{sec:rkgCQ}
	In this section, the formulation of Runge--Kutta based gCQ  on the real axis is developed. The $s$-stage Runge--Kutta method, applied to \eqref{ode} on the time mesh \eqref{mesh}, defines the stage vectors $\Yv_n(x)$ and solutions $y_n(x)$ via
	\begin{subequations}\label{RK_ode_vec}
		\begin{align}
			\Yv_{n}(x) &= y_{n-1}(x)\bone + \tau_n \Av \left(-x\Yv_{n}(x)+\fv_n\right), && n \geq 1, \\
			y_{n}(x) &= y_{n-1}(x) + \tau_n \bv^\top \left(-x\Yv_{n}(x)+\fv_n\right), && n \geq 1,
		\end{align}
	\end{subequations}
	where $\Yv_n = (Y_{ni})_{i=1}^s$, $\bone = (1)_{i=1}^s$, $\fv_n = (f(t_{n-1}+c_i\tau_n))_{i=1}^s$. Rewriting \eqref{RK_ode_vec} as recurrences for $\Yv_n$ and $y_n$ yields
	\begin{equation*}
		\Yv_{n}(x) = \Rv(-\tau_n x) \ev_s^\top \Yv_{n-1}(x) + \tau_n \Av (\Iv + \tau_n x \Av)^{-1} \fv_n, \quad n \geq 1,
	\end{equation*}
	and
	\begin{equation}\label{RK_sol1}
		y_{n}(x) = R(-\tau_n x) y_{n-1}(x) + \tau_n \bv^\top (\Iv + \tau_n x \Av)^{-1} \fv_n, \quad n \geq 1.
	\end{equation}
	Here, 
	\begin{equation}\label{RzVec}
		\Rv(z) = (\Iv - z \Av)^{-1} \bone,
	\end{equation}
	and the stability function is
	\begin{equation}\label{Rz}
		R(z) = \ev_s^\top \Rv(z) = 1 + z \bv^\top (\Iv - z \Av)^{-1} \bone.
	\end{equation}
	Solving the recursion relations yields
	\begin{equation}\label{Yvn_sol}
		\Yv_{n}(x) = \sum_{j=1}^n \left( \prod_{l=j+1}^{n} \Rv(-\tau_l x) \ev_s^\top \right) \tau_j \Av (\Iv + \tau_j x \Av)^{-1} \fv_j, \quad n \geq 1,
	\end{equation}
	\begin{equation}\label{RK_sol}
		y_{n}(x) = \sum_{j=1}^n \left( \prod_{l=j+1}^{n} R(-\tau_l x) \right) \tau_j \bv^\top (\Iv + \tau_j x \Av)^{-1} \fv_j, \quad n \geq 1,
	\end{equation}
	where 
	\[
	\prod_{l=j+1}^{n} \Rv(-\tau_l x) \ev_s^\top = \Rv(-\tau_n x) \ev_s^\top \cdots \Rv(-\tau_{j+1} x) \ev_s^\top,
	\]
	with initial conditions $\Yv_0(x) = \mathbf{0}$ and $y_0(x) = 0$. The  Runge--Kutta based gCQ  approximation to \eqref{conv} is then defined as follows:
	\begin{definition}
		For $n\ge 1$, the Runge--Kutta based gCQ  approximation to \eqref{conv} on the time mesh \eqref{mesh} is defined by
		\begin{equation}\label{gCQ}
			u_n = \int_{0}^{\infty}G(x) y_n(x) \, dx,
		\end{equation}
		with $y_n(x)$ given in \eqref{RK_sol}.
	\end{definition}


	Let $\Uv(t_n):= \left(u(t_{n-1}+c_i\tau_n)\right)_{i=1}^s$. The Runge--Kutta based gCQ  approximation to $\Uv(t_n)$ is given by
	\begin{equation}\label{Un_stage}
		\Uv_n := \int_{0}^\infty G(x) \Yv_n(x)\,dx,\quad 1\le n\le N,
	\end{equation}
	where $\Yv_n(x)$ is given in \eqref{Yvn_sol}. Define the gCQ   weights
	\begin{equation}\label{gCQ_w}
		\Wv_{n,j}:= \tau_j  \int_{0}^\infty G(x) \left(\prod_{l=j+1}^{n} \left(\Rv(-\tau_l x)\ev_s^\top\right)\right) \left  (\Av(\Iv+\tau_jx\Av)^{-1} \right) \,dx,
	\end{equation}
	then the gCQ  scheme for the internal stages can be expressed as
	\begin{equation}\label{u_nweights}
		\Uv_n=\sum\limits_{j=1}^n \Wv_{n,j} \fv_j,\quad 1\le n\le N,
	\end{equation}
	where $u_n$ is the last component of $\Uv_n$. The weights \eqref{gCQ_w} also admit an alternative representation as contour integrals \cite{LoSau16}:
	\begin{equation}\label{gCQ_wContour}
		\Wv_{n,j}= \frac{\tau_j }{2\pi i} \int_{\Gamma} K(z) \left(\prod_{l=j+1}^{n} \left(\Rv(\tau_l z)\ev_s^\top\right)\right) \left  (\Av(\Iv-\tau_jz\Av)^{-1} \right) \,dz.
	\end{equation}



	\section{Stability}\label{sec:stability}
	The Runge--Kutta method satisfying Assumption~\ref{ass_RK} has the following properties:
	\begin{enumerate}
		\item By \eqref{Rz_Astab}, the eigenvalues of $\Av^{-1}$ lie in the region $\Re z > 0$, implying that $\Av$ is invertible and its eigenvalues are also in $\Re z > 0$.
		\item From \cite[Theorem 4.12]{HairWan10}, the matrix $\Av$ has $s$ distinct eigenvalues. Hence, $\Av$ is diagonalizable, i.e., there exists an invertible matrix $\Pv=(p_{ij})_{i,j=1}^s$ consisting of all eigenvectors of $\Av$ such that
		\begin{equation}\label{A_eigdecp}
			\Av=\Pv^{-1}\Lambda \Pv,
		\end{equation}
		where
		\begin{equation}\label{lambda}
			\Lambda=\mathrm{diag}([\lambda_1,\cdots,\lambda_s]),\quad \lambda_{\min}=\min_{1\le i\le s} \Re{\lambda_i},
		\end{equation}
		and $\Av\Pv(:,i)=\lambda_i\Pv(:,i)$ for $1\le i\le s$.
		\item The function $R(z)$ satisfies
		\begin{align}\label{Rz_prop}
			R(\infty)=0, \qquad R(0)=R'(0)=1.
		\end{align}
	\end{enumerate}

	\begin{lemma}\cite{LoLuPaScha,Maria_thesis}\label{lem:Rz_bnd}
		Assume that the $s$-stage Runge--Kutta method satisfies Assumption \ref{ass_RK},  then there exists a constant $\hat{b}>0$ such that
		\begin{equation}\label{Rz_bnd}
			\left\vert R( - x) \right\vert\le
			\frac{1}{1+\hat{b}x},\quad \text{for all} \quad x > 0.
		\end{equation}
	\end{lemma}

	\begin{lemma}\label{lem:gCQ w_bnd}
		Under  Assumptions~\ref{assumptionK} and \ref{ass_RK}, the gCQ  weights given in \eqref{gCQ_w} satisfy
		\begin{align}
			\Vert \Wv_{n,j}\Vert\le CM\tau_j (t_n-t_{j-1})^{\alpha-1},\quad n\ge j\ge 1.
		\end{align}
	\end{lemma}
	\begin{proof}
		Applying the bound \eqref{Gx_bnd} to \eqref{gCQ_w} yields
		\begin{align*}
			&\Vert \Wv_{n,j}\Vert\le   \frac{M\tau_j }{\pi}  \int_{0}^\infty x^{-\alpha} \left\Vert \Av(\Iv+\tau_jx\Av)^{-1}\right\Vert\left\Vert \Rv(-\tau_n x)\ev_s^\top \right\Vert \left\vert\prod_{l=j+1}^{n-1} R(-\tau_l x)\right\vert\,dx,
		\end{align*}
		where $\Rv(\cdot)$ and $R(\cdot)$ are the stability functions defined in \eqref{RzVec} and \eqref{Rz}, respectively. For any \( x > 0 \), we apply the eigenvalue decomposition \eqref{A_eigdecp} to estimate
		\begin{equation*}
			\Vert \Av^{-1}(\Iv+\tau_jx\Av)^{-1}\Vert\le	\Vert \Av^{-1}\Vert \Vert(\Iv+\tau_jx\Av)^{-1}\Vert
			\le \frac{\max\limits_{1\le i \le s}\left \{\vert \lambda_i^{-1}\vert\right\}}{1+\min\limits_{1\le i \le s}\{\Re \lambda_i\}\tau_jx},
		\end{equation*}
		and
		\begin{align*}
			\left\Vert  \Rv(-\tau_n x)\ev_s^\top\right\Vert&=\left\Vert  (\Iv+\tau_n \Av x)^{-1}\bone \ev_s^\top\right\Vert\le\left\Vert  (\Iv+\tau_n \Av x)^{-1}\right\Vert \Vert\bone \ev_s^\top\Vert 	\le 	\frac{\sqrt{s}}{1+\min\limits_{1\le i \le s}\{\Re \lambda_i\}\tau_n x}.
		\end{align*}
		Hence, it follows that
		\begin{equation*}
			\left\Vert \Av(\Iv+\tau_jx\Av)^{-1}\right\Vert	\left\Vert \Rv(-\tau_n x)\ev_s^\top \right\Vert\le 	
			\frac{\sqrt{s}\max\limits_{1\le i \le s}\left \{\vert \lambda_i^{-1}\vert\right\}}{1+\min\limits_{1\le i \le s}\{\Re \lambda_i\}(\tau_n+\tau_j)x},\quad  n\ge j,\quad j\ge 1.
		\end{equation*}
		In addition, Lemma~\ref{lem:Rz_bnd} provides the product estimate
		\begin{equation*}\label{Rz_prodbnd}
			\left\vert\prod_{l=j+1}^{n-1} R(-\tau_l x)\right\vert\le\frac{1}{1+\hat{b}(t_{n-1}-t_j)},\quad n\ge j,\quad j\ge 1.
		\end{equation*}
		Let
		\[\hat{v}=\min\left\{\hat{b},\min\limits_{1\le i \le s}\{\Re \lambda_i\}\right\}.\]
		By combining these estimates and employing the Beta function identity \eqref{int_Betafun}, we establish
		\begin{align*}
			\Vert \Wv_{n,j}\Vert&\le \frac{M\tau_j}{\pi} \left(\int_{0}^\infty  x^{-\alpha} \frac{\sqrt{s}\max\limits_{1\le i \le s}\left \{\vert \lambda_i^{-1}\vert\right\}}{1+\hat{v}(t_n-t_{j-1})x}\,dx\right)\\[.5em]
			&= \frac{M\tau_j}{\pi}\sqrt{s} B(\alpha,1-\alpha)\max\limits_{1\le i \le s}\left \{\vert \lambda_i^{-1}\vert\right\} \left(\hat{v}(t_n-t_{j-1})\right)^{\alpha-1}.
		\end{align*}
		The proof is thus complete.
	\end{proof}
	The stability of scheme \eqref{gCQ} follows directly from the preceding weight estimates, as formalized in the following theorem.
	\begin{theorem}\label{thm:stab}
		Under Assumptions~\ref{assumptionK} and \ref{ass_RK}, the Runge--Kutta based gCQ scheme \eqref{gCQ} satisfies
		\begin{align*}
			\|u_n\|_{\mathcal{Y}} \le CM \sum_{j=1}^n \tau_j \left(t_n - t_{j-1}\right)^{\alpha-1} \left\| f_j \right\|_{C^0\left ([t_{j-1},t_j];\mathcal{X}\right)}.
		\end{align*}
	\end{theorem}

	\section{Proof of Theorems~\ref{thm:conv_gCQrkGenM} and \ref{thm:conv_gCQrkGrad}}\label{sec:err} %Convergence analysis}
Following Lubich's operational framework \cite{Lu88I},  we adopt the following notation for the error analysis:
\begin{align*}  
	&K(\partial_t)f := k * f, \quad \text{ the continuous convolution defined in \eqref{conv}}, \\  
	&	K(\partial_t^\Delta)f,\quad  \text{the Runge--Kutta based gCQ  approximation of \eqref{conv} on the time mesh  } \Delta .  
\end{align*}   
\subsection{Error representation on the real axis}
Let $\Yv(x, t_n):=(y(x,t_{n-1}+c_i\tau_n))_{i=1}^s$. Substituting the exact solution into the Runge--Kutta scheme \eqref{RK_ode_vec} gives
\begin{subequations}\label{RK_ode_defec}
	\begin{align}
		\label{Y_tn}
		\Yv(x, t_n) &= y(x, t_{n-1})\bone + \tau_n \Av \left(-x\Yv(x, t_{n})+\fv_n\right) + \Dv_n(x), &&\text{for } n \ge 1, \\
		\label{y_tn}
		y(x, t_n) &= y(x, t_{n-1}) + \tau_n \bv^\top \left(-x\Yv(x, t_{n})+\fv_n\right) + d_n(x), &&\text{for } n \ge 1,
	\end{align}
\end{subequations}
where \(\Dv_n = (d_{ni})_{i=1}^s\) and \(d_n\) denote the defects.  
Under Assumption~\ref{ass_RK}, these defects admit the representations \cite[proof of Theorem 3.3]{LuOs}:
\begin{align}
	\label{dni}
	d_{ni}(x) &= \sum\limits_{\ell=q+1}^p \delta_{i}^{(\ell)} \tau_n^\ell \frac{\partial^{\ell}y}{\partial t^{\ell}}(x,t_{n}) + \tau_n^p \int_{t_{n-1}}^{t_n} \kappa_i\left(\frac{t-t_{n-1}}{\tau_n}\right) \frac{\partial^{p+1}y}{\partial t^{p+1}}\,dt, \\
	\label{dn}
	d_n(x) &= \tau_n^p \int_{t_{n-1}}^{t_n} \kappa\left(\frac{t-t_{n-1}}{\tau_n}\right) \frac{\partial^{p+1}y}{\partial t^{p+1}}\,dt,
\end{align}
where $\kappa_i$ and $\kappa$ are bounded Peano kernels, and
\begin{equation}\label{delt_ell}
	\delta_{i}^{(\ell)} = \left(\frac{c_i^\ell}{\ell} - \sum\limits_{j=1}^s a_{ij}c_j^{\ell-1}\right)/(\ell-1)!.
\end{equation}
Denote $\Ev_n(x):=\Yv(x, t_n) - \Yv_n(x)$ and $e_n(x):=y(x, t_n) - y_n(x)$. 
% Since $d_{ns}(x) = d_n(x)$, we find that
% \begin{equation}
	% 	\sum\limits_{j=1}^s a_{sj}c_j^{\ell-1} - \frac{c_s^\ell}{\ell} = \sum\limits_{j=1}^s b_j c_j^{\ell-1} - \frac{c_s^\ell}{\ell} = 0, \quad q+1 \le \ell \le p.
	% \end{equation}
Subtracting \eqref{RK_ode_vec} from \eqref{RK_ode_defec} gives
\begin{equation}
	\label{RK_err}
	\begin{alignedat}{2}
		\Ev_n(x) &= e_{n-1}(x)\bone - \tau_n x \Av \Ev_n(x) + \Dv_n(x), &&\quad \text{for } n \ge 1, \\
		e_n(x) &= e_{n-1}(x) - \tau_n x \bv^\top \Ev_n(x) + d_n(x), &&\quad \text{for } n \ge 1.
	\end{alignedat}
\end{equation}
Solving the recursion \eqref{RK_err}, we obtain
\begin{equation}\label{en}
	e_n(x) = \sum\limits_{j=1}^n \left(d_j(x)-\tau_j x \bv^\top(\Iv+\tau_j x \Av)^{-1} \Dv_j(x) \right) \prod_{l=j+1}^{n} R(-\tau_l x),
\end{equation}
with $e_0(x) = 0$ and $R(z)$ defined in \eqref{Rz}. Then, the error representation of the  Runge--Kutta  based gCQ  scheme \eqref{gCQ} can be expressed as
\begin{equation}
	\label{gCQ_error_decomposition}
	u(t_n) - u_n = \int_{0}^{\infty} G(x) e_n(x) \, dx :=\mathcal{E}_n^1 + \mathcal{E}_n^2,
\end{equation}
where
\begin{align}
	\label{Err_1}
	\mathcal{E}_n^1 &= \int_0^{\infty} G(x) \left(   d_1(x)-\tau_1 x \bv^\top(\Iv + \tau_1 x \Av)^{-1} \Dv_1(x) \right) \left(\prod_{j=2}^{n} R(-\tau_j x)\right)\,dx,\\[.5em]
	\label{Err_2}
	\mathcal{E}_n^2 &= \sum_{j=2}^{n} \int_0^{\infty} G(x)\left( d_j(x)-\tau_j x \bv^\top(\Iv + \tau_j x \Av)^{-1} \Dv_j(x)\right) \left(\prod_{l=j+1}^{n} R(-\tau_l x)\right)\,dx.
\end{align}

%\begin{remark}
%	Note that the gCQ -RK error can be viewed as the Runge--Kutta discretization error for the ODE \eqref{ode}, multiplied by the kernel \( G(x) \) and integrated over \((0,\infty)\). Therefore, the subsequent analysis also applies to giving error bounds for variable-step Runge--Kutta methods applied to \eqref{ode}, and furthermore, to variable-step Runge--Kutta schemes for the parabolic equation \eqref{parabolic}.
%\end{remark}





\subsection{Convergence analysis for   power-type integrands }
To establish error estimates for general integrands~\( f \) satisfying~\eqref{gen_f}, we begin by analyzing the  case \( f(t) = t^\beta \mathbf{v} \) with \( \beta > -1 \). The error analysis proceeds by examining each component of the error decomposition~\eqref{gCQ_error_decomposition} on the general mesh~\eqref{mesh}.

\subsubsection{Error estimate for the first time interval}

\begin{lemma}\label{lem:dn}
	Let \(\beta > -1\) and \(x > 0\). Under Assumption~\ref{ass_RK}, the defects in \eqref{Y_tn} with \(f(t) = t^\beta \mathbf{v}\) and \(n=1\) satisfy
	\begin{equation}\label{d1i_bnd}
		\max_{1 \le i \le s} \left\| d_{1i}(x) \right\|_{\mathcal{X}} \leq C \Gamma(\beta+1) \tau_1^{\beta+1} 
		\begin{cases}
			\displaystyle \frac{1}{1 + x c_1 \tau_1}, & \text{if } c_1 > 0, \\[1em]
			\displaystyle \frac{1}{1 + x c_2 \tau_1}, & \text{if } c_1 = 0, \quad \beta > 0,
		\end{cases}
	\end{equation}
	where \( c_i \) denotes the \(i\)th component of the vector \(\mathbf{c}\) in the Butcher tableau, with \(0 \le c_1 \le c_2 \le \cdots \le c_s = 1\).

	% To ensure the boundedness of \( y_t(x, c_1 \tau_1) \) in the case \( y_t(x, 0) \ne 0 \), the Runge--Kutta method in Assumption~\ref{ass_RK} must satisfy \( c_1 > 0 \).


	%    The defects in \eqref{dn} admit the bound
	% \begin{equation}\label{dn_bnd}
		% 	\left\| d_n(x) \right\|_{\mathcal{X}} \leq C \Gamma(\beta+1) \tau_n^{p+1} \xi_n^{\beta - p} \frac{1}{1 + x \xi_n},
		% \end{equation}
	% for some \(\xi_n \in (t_{n-1}, t_n)\), \(n \geq 2\).
\end{lemma}
\begin{proof}
	By \eqref{Y_tn}, we have
	\begin{align}
		\nonumber
		\| d_{1i} \|_{\mathcal{X}} = \left\| y(x, c_i \tau_1) - \tau_1 \sum_{j=1}^s a_{ij} y_t(x, c_j \tau_1) \right\|_{\mathcal{X}}.
	\end{align}
	Note that when \( c_1 = 0 \), the condition \(\beta > 0\) is required to ensure boundedness of \( y_t(x, 0) \). 
	Applying \eqref{ydiff_bnd}, the estimate \eqref{d1i_bnd} follows. 
	% Similarly, the bound \eqref{dn_bnd} is obtained by directly applying Lemma \ref{lem:identities} to \eqref{dn}. The details are omitted here for brevity.
\end{proof}


\begin{lemma}\label{lem:Matstab_estimate}
	Under Assumption~\ref{ass_RK}, for \(\tau > 0\), \(x > 0\), and \(\delta^{(\ell)}\) defined in \eqref{delt_ell} with \(q + 1 \leq \ell \leq p\), it holds
	\begin{equation}\label{stab_combined}
		\left| \tau x\bv^\top(\Iv + \tau x\Av)^{-1} \delta^{(\ell)}\right| \leq 
		\begin{cases}
			C(\tau x)^{p-\ell+1}, & 0 < x < (\tau\|\Av\|)^{-1}, \\
			C, & x \geq (\tau\|\Av\|)^{-1},
		\end{cases}
	\end{equation}
	where \(C > 0\) is a constant independent of \(\tau\) and \(x\), and \(\|\mathbf{A}\|\) denotes the induced matrix norm.
\end{lemma}
\begin{proof}
	We first establish a uniform bound valid for all $x > 0$, then refine it for small $x$. From the stiff accuracy condition \eqref{stiff_RK} and the eigendecomposition \eqref{A_eigdecp}, we have
	\begin{align}
		\label{mat_bnd}
		\left\|\tau x\bv^\top(\Iv + \tau x\Av)^{-1}\right\| 
		= \left\|\ev_s^\top - \ev_s^\top(\Iv + \tau x\Av)^{-1}\right\| \leq 1 + \frac{1}{1 + \tau x\lambda_{\min}} \leq 2,
	\end{align}
	where $\lambda_{\min}$ is given in \eqref{lambda}. Thus, for \emph{any} $x > 0$ 
	\[
	\left| \tau x\bv^\top(\Iv + \tau x\Av)^{-1} \delta^{(\ell)}\right| 
	\leq 2 \left\Vert \delta^{(\ell)}\right\Vert \leq C.
	\]
	When \(0 < x < (\tau\|\Av\|)^{-1}\), the Neumann series expansion gives
	\begin{equation*}
		(\Iv + \tau x\Av)^{-1} = \sum_{m=0}^\infty (-\tau x\Av)^m.
	\end{equation*}
	Together with the order conditions
	\begin{equation*}
		\bv^\top\Av^{m+1}\cv^{\ell-1} = \frac{1}{\ell}\bv^\top\Av^m\cv^\ell \quad \text{for } m+1+\ell \leq p,
	\end{equation*}
	and the definition of \(\delta^{(\ell)}\) in \eqref{delt_ell}, it follows for each \(q+1 \leq \ell \leq p\) that
	\begin{equation*}
		\left| \tau x\bv^\top(\Iv + \tau x\Av)^{-1} \delta^{(\ell)}\right|
		= \left| \tau x\bv^\top \sum_{m=p-\ell}^\infty (-\tau x\Av)^m \delta^{(\ell)}\right|
		\leq C(\tau x)^{p-\ell+1}.
	\end{equation*}
	This completes the proof.
\end{proof}
We now establish the error bound for    $\mathcal{E}_n^1 $ in \eqref{Err_1}.
\begin{lemma}\label{lem:Err_1}
	Given  \(f(t) = t^\beta \vv\) with \(\beta > -1\), under Assumptions~\ref{assumptionK} and \ref{ass_RK}, the approximation error \(\mathcal{E}_n^1\) in \eqref{Err_1} on the mesh \eqref{mesh} satisfies
	\begin{equation}\label{T1_bnd}
		\left\Vert \mathcal{E}_n^1 \right\Vert_{\mathcal{Y}} \leq C M \tau_1^{\alpha + \beta},
	\end{equation}
	where the positive constant \(C\) is independent of the mesh.
\end{lemma}

\begin{proof}
	Using \eqref{Gx} and the  bound \eqref{Rz_Astab}, it follows that
	\begin{align*}
		\left\Vert \mathcal{E}_n^1 \right\Vert_{\mathcal{Y}} 
		&\leq C M \int_{0}^\infty x^{-\alpha} \left( \| d_1(x) \|_{\mathcal{X}} + \left\| \tau_1 x \bv^\top(\Iv + \tau_1 x \Av)^{-1} \Dv_1(x) \right\|_{\mathcal{X}} \right) \, dx.
	\end{align*}
	The  bound in \eqref{mat_bnd} simplifies this to
	\begin{align*}
		\left\Vert \mathcal{E}_n^1 \right\Vert_{\mathcal{Y}} 
		&\leq C M \int_{0}^\infty x^{-\alpha} 	\max_{1 \le i \le s} \left\| d_{1i}(x) \right\|_{\mathcal{X}} \, dx.
	\end{align*}
	Applying Lemma~\ref{lem:dn} with the integral identity \eqref{int_Betafun}, we derive
	\begin{align*}
		\left\Vert \mathcal{E}_n^1 \right\Vert_{\mathcal{Y}} 
		&\leq C M \tau_1^{\beta+1} \int_0^\infty x^{-\alpha} \frac{1}{1 + \widetilde{c} t_1 x} \, dx 
		= C M B(\alpha, 1 - \alpha) \widetilde{c}^{\alpha - 1} \tau_1^{\alpha + \beta},
	\end{align*}
	where
	\begin{equation}\label{ctild}
		\widetilde{c} = 
		\begin{cases}
			c_1, & \text{if } c_1 \neq 0 \text{ and } \beta > -1, \\
			c_2, & \text{if } c_1 = 0 \text{ and } \beta > 0.
		\end{cases}
	\end{equation}
\end{proof}
\subsubsection{Error estimates from the second time interval}
This subsection focuses on establishing an error bound for the accumulated error \( \mathcal{E}_n^2 \) defined in \eqref{Err_2}, for $n\ge 2$. The analysis begins with the following lemma.
\begin{lemma}\label{lem:integral_bound}
	For the defects \(d_j(x)\) in \eqref{RK_ode_defec} with \(f(t) = t^\beta \vv\), where \(\beta > -1\), the following bound holds on the general mesh \eqref{mesh}:
	%	\begin{equation}
		%		\left\|\sum_{j = 2}^n \int_0^\infty G(x) d_j(x) \, dx \right\|_{\mathcal{Y}} \leq CM 	\sum_{j = 2}^n \tau_j^{p+1} \xi_j^{\alpha + \beta - p - 1},
		%	\end{equation}
	\begin{equation}\label{intdj_bnd}
		\sum_{j=2}^n \int_0^\infty x^{-\alpha}		\left\| d_j(x)  \right\|_{\mathcal{X}}\, dx \leq C
		\begin{cases}
			\tau_{\max}^p	t_n^{\alpha+\beta-p}, & \text{if } \beta > p - \alpha, \\[5pt]
			|\log(t_n/t_1)| \tau_{\max}^p, & \text{if } \beta = p - \alpha, \\[5pt]
			\sum\limits_{j=2}^n \tau_j^{p+1} \xi_j^{\alpha + \beta - p - 1}, & \text{if } \beta < p - \alpha,
		\end{cases}
	\end{equation}
	where    $\xi_j\in(t_{j-1},t_j)$ and  $C$ is a positive constant independent of the mesh.
\end{lemma}

\begin{proof}
	%	By applying the bound \eqref{Gx_bnd}, we have
	%	\begin{equation*}
		%		\left\|\sum_{j=2}^n \int_0^\infty G(x) d_j(x) \, dx \right\|_{\mathcal{Y}} \leq M \int_0^\infty x^{-\alpha} \sum_{j=2}^n \left\| d_j(x) \right\|_{\mathcal{X}} \, dx.
		%	\end{equation*}
	Using  \eqref{dn}, we have
	\begin{equation*}
		\sum_{j=2}^n \int_0^\infty x^{-\alpha}		\left\| d_j(x)  \right\|_{\mathcal{X}}\, dx \leq C \int_0^\infty x^{-\alpha}  \left( \sum_{j=2}^n \tau_j^p\int_{t_{j-1}}^{t_j} \left\| \frac{\partial^{p+1} y}{\partial t^{p+1}} \right\|_{\mathcal{X}} \, dt \right)\, dx.
	\end{equation*}
	From \eqref{ydiff_bnd}, it follows that
	\begin{equation}\label{intdj_allj}
		\sum_{j=2}^n \tau_j^p \int_{t_{j-1}}^{t_j} \left\| \frac{\partial^{p+1} y(t)}{\partial t^{p+1}} \right\|_{\mathcal{X}} \, dt
		\le C \Gamma(\beta + 1) \sum_{j=2}^n \tau_j^p \int_{t_{j-1}}^{t_j} \frac{t^{\beta - p}}{1 + x t} \, dt, \quad \text{for } x > 0.
	\end{equation}
	Hence,
	\begin{equation*}
		\int_0^\infty  x^{-\alpha}  	\left\|d_j(x) \right\|_{\mathcal{X}} \, dx\leq C\Gamma(\beta+1) \sum\limits_{j=2}^n \tau_j^p \int_{t_{j-1}}^{t_j} t^{\beta - p} \left( \int_0^\infty \frac{x^{-\alpha}}{1 + x t} \, dx \right) dt.
	\end{equation*}
	By applying the definition of the Beta function given in \eqref{int_Betafun}, we derive
	\begin{equation*}
		\int_0^\infty  x^{-\alpha}  	\left\|d_j(x) \right\|_{\mathcal{X}} \, dx \leq C\Gamma(\beta+1)B(\alpha,1-\alpha) \sum\limits_{j=2}^n \tau_j^p \int_{t_{j-1}}^{t_j} t^{\alpha+\beta - p-1} \, dt.
	\end{equation*}
	The final bound \eqref{intdj_bnd} is obtained through direct integration, thereby completing the proof.
\end{proof}

\begin{lemma}\label{lem:Pj_bnd}
	Suppose the \(s\)-stage Runge--Kutta method satisfies Assumption~\ref{ass_RK}. Define
	\begin{equation}
		\label{Pj}
		P_j := \sum_{\ell = q+1}^{p} \int_0^\infty x^{-\alpha} \left\| \tau_j x \bv^\top (\Iv + \tau_j x \Av)^{-1} \delta^{(\ell)} \tau_j^\ell \frac{\partial^\ell y}{\partial t^\ell}(x, t_j) \right\|_{\mathcal{X}} \prod_{l=j+1}^n \left| R(-\tau_l x) \right| \, dx,
	\end{equation}
	for \(2 \leq j \leq n\), where \(y(x,t)\) is the solution to \eqref{ode} with \(f(t) = t^\beta \vv\), \(\beta > -1\). Then, on the general time mesh \eqref{mesh},   it holds
	\begin{equation}
		\label{Pj_bnd}
		\sum_{j=2}^n P_j \le C |\log(\tau_n)|
		\begin{dcases}
			\tau_{\max}^{\min\{p,q+1+\alpha\}} t_n^{\alpha+\beta-\min\{p,q+1+\alpha\}}, & \text{if } \beta \ge p-\alpha, \\[.5em]
			\max_{2 \leq j \leq n} \left\{ \tau_j^{q+1+\alpha} t_j^{\beta - q - 1} + \tau_j^p t_j^{\alpha + \beta - p} \right\}, & \text{if } \beta < p-\alpha,
		\end{dcases}
	\end{equation}
	%		\begin{equation}
		%			\label{Pj_bnd}
		%			\sum\limits_{j=2}^n	P_j \le C |\log(\tau_n)|
		%			\begin{cases}
			%				\max\limits_{2 \leq j \leq n} 	\left\{ \tau_j^p t_j^{\alpha + \beta - p}\right\}, &\quad p\le  q+1+\alpha, \\[0.6em]
			%				\max\limits_{2\le j \le n}	\left\{\tau_j^{q+1+\alpha} t_j^{\beta - q - 1} \right\}, &\quad p\ge q+1+\alpha.
			%			\end{cases}
		%		\end{equation}
	where $C$ is a positive constant independent of the mesh.
\end{lemma}
\begin{proof}
	By Lemma~\ref{lem:Rz_bnd} and the estimate in \eqref{ydiff_bnd}, we have
	\begin{align*}
		P_j &\le C \sum_{\ell = q+1}^p \tau_j^\ell t_j^{\beta - \ell + 1} \int_0^\infty x^{-\alpha} \left| \tau_j x \bv^\top (\Iv + \tau_j x \Av)^{-1} \delta^{(\ell)} \right| \frac{1}{(1 + t_j x)(1 + \hat{b}(t_n - t_j)x)}\, dx.
	\end{align*}
	For the case \(j=n  \), Lemma~\ref{lem:Matstab_estimate} yields
	\begin{align*}
		P_n \le& C \sum_{\ell = q+1}^{p-1}  \left(\tau_n^{p+1}t_n^{\beta - \ell + 1}\int_0^{1 / (\tau_n \Vert \Av \Vert)} \frac{x^{-\alpha+p-\ell+1}}{1 + t_n x}\, dx+ \tau_n^\ell t_n^{\beta - \ell + 1}\int_{1 / (\tau_n \Vert \Av \Vert)}^\infty \frac{x^{-\alpha}}{1 + t_n x}\, dx\right) \\[.5em]
		&+C\tau_n^p t_n^{\beta-p+1}\int_0^\infty\frac{x^{-\alpha}}{1 + t_n x}\, dx,
	\end{align*}
	which gives
	\begin{equation}\label{Pn_esti}
		P_n \le C  \sum_{\ell = q+1}^{p-1} \tau_n^{\alpha + \ell} t_n^{\beta - \ell}+C\tau_n^p t_n^{\alpha+\beta-p}.		\end{equation}
	Using 
	\begin{equation} \label{ineq:stepsize}
		\tau_j / t_j < 1 \quad \text{for all } j \ge 2,
	\end{equation}
	we further deduce that
	\[
	P_n \le C \left(\tau_n^{q+1+\alpha} t_n^{\beta - q - 1} + \tau_n^p t_n^{\alpha + \beta - p}\right).
	\]
	Now consider the case \( 2 \le j \le n - 1\). In this case, we have
	\[P_j \le C \sum_{\ell = q+1}^p \tau_j^\ell(\hat{b}(t_n - t_j))^{-1}  t_j^{\beta - \ell +1} \int_0^\infty x^{-\alpha-1} \left| \tau_j x \bv^\top (\Iv + \tau_j x \Av)^{-1} \delta^{(\ell)} \right| \frac{1}{1 + t_j x}\, dx.\]
	Applying Lemma~\ref{lem:Matstab_estimate}  gives
	\begin{align} \label{Tn3_m1p1}
		P_j \le
		C \sum_{\ell = q+1}^p \left( |I^{(\ell)}_{\mathrm{near}}| + \tau_j^{\alpha + \ell + 1} (\hat{b}(t_n - t_j))^{-1} t_j^{\beta - \ell} \right),
	\end{align}
	where
	\[
	I^{(\ell)}_{\mathrm{near}} := \tau_j^{p+1} (\hat{b}(t_n - t_j))^{-1} t_j^{\beta - \ell + 1} \int_0^{1 / (\tau_j \Vert \Av \Vert)} x^{-\alpha + p - \ell} \frac{1}{1 + t_j x}\, dx.
	\]
	Evaluating the integral explicitly yields
	\begin{align} \label{Inear_combined}
		|I^{(\ell)}_{\mathrm{near}}| \le
		\begin{cases}
			C \tau_j^{\alpha + \ell + 1} (\hat{b}(t_n - t_j))^{-1} t_j^{\beta - \ell}, & q+1 \le \ell \le p - 1, \\[.7em]
			B(\alpha, 1 - \alpha) \tau_j^{p + 1} (\hat{b}(t_n - t_j))^{-1} t_j^{\alpha + \beta - p}, & \ell = p.
		\end{cases}
	\end{align}
	Substituting \eqref{Inear_combined} into \eqref{Tn3_m1p1}, we obtain
	\begin{align}
		\label{Pj_esti}
		P_j &\le C \sum_{\ell = q+1}^{p-1} \tau_j^{\alpha + \ell + 1} (\hat{b}(t_n - t_j))^{-1} t_j^{\beta - \ell}
		+ C \tau_j^{p + 1} (\hat{b}(t_n - t_j))^{-1} t_j^{\alpha + \beta - p} \\[.5em]
		\nonumber
		&\le C (\hat{b}(t_n - t_j))^{-1} \left( \tau_j^{q+2 + \alpha} t_j^{\beta - q - 1} + \tau_j^{p+1} t_j^{\alpha + \beta - p} \right),
	\end{align}
	where \eqref{ineq:stepsize} is applied in the last step. Combining all cases yields
	\[
	\sum_{j=2}^n P_j \le C \left(1 + \sum_{j=2}^{n-1} \tau_j (\hat{b}(t_n - t_j))^{-1} \right) \max_{2 \le j \le n} \left\{ \tau_j^{q+1+\alpha} t_j^{\beta - q - 1} + \tau_j^p t_j^{\alpha + \beta - p} \right\}.
	\]
	Using the inequality
	\begin{equation}\label{log_bnd}
		1+ \sum_{j=2}^{n-1} \tau_j (\hat{b}(t_n - t_j))^{-1} \le 1+\hat{b}^{-1}+\hat{b}^{-1}  \int_0^{t_{n-1}} (t_n - s)^{-1} \, ds \le C |\log(\tau_n)|,
	\end{equation}
	we have
	\[
	\sum_{j=2}^n P_j \le C |\log(\tau_n)| \max_{2 \le j \le n} \left\{ \tau_j^{q+1+\alpha} t_j^{\beta - q - 1} + \tau_j^p t_j^{\alpha + \beta - p} \right\}.
	\]
	Furthermore, application of \eqref{ineq:stepsize} gives
	\begin{equation}\label{max_meshbnd}
		\tau_j^{q+1+\alpha}t_j^{\beta-q-1} + \tau_j^p t_j^{\alpha+\beta-p} <2 \tau_j^{\min\{p,q+1+\alpha\}} t_j^{\alpha+\beta-\min\{p,q+1+\alpha\}}, \quad \text{for all } 2\leq j\leq n.
	\end{equation}
	%		\begin{equation}\label{max_meshbnd}
		%			\tau_j^{q+1+\alpha} t_j^{\beta - q - 1} + \tau_j^p t_j^{\alpha + \beta - p} \le 2
		%			\begin{cases}
			%				\tau_j^p t_j^{\alpha + \beta - p}, & \text{if } p \le q+1+\alpha, \\[.5em]
			%				\tau_j^{q+1+\alpha} t_j^{\beta - q - 1} , & \text{if } p \ge q+1+\alpha.
			%			\end{cases}
		%		\end{equation}
	Thus we can get \eqref{Pj_bnd}, which completes the proof.
\end{proof}


\begin{lemma} \label{lem:Err_2}
	Let the right-hand side term in \eqref{ode} be \( f(t) = t^\beta \vv \) with \(\beta > -1\). Under Assumptions~\ref{assumptionK} and \ref{ass_RK}, for the error term \(\mathcal{E}_n^2\) defined in \eqref{Err_2} on the general time mesh \eqref{mesh}, it holds that
	\begin{equation}
		\label{Err_2_bnd}
		\begin{aligned}
			&\left\Vert \mathcal{E}_n^2 \right\Vert_{\mathcal{Y}} \le
			\\[.5em]
			&	C M \left\{
			\begin{aligned}
				&|\log(\tau_{\min})|\, \tau_{\max}^{\min\{p,q+1+\alpha\}}, 
				&&\text{if } \beta \ge p - \alpha, \\[6pt]
				&\sum\limits_{j=2}^n \tau_j^{p+1} \xi_j^{\alpha + \beta - p - 1} 
				+ |\log(\tau_n)| \max\limits_{2 \leq j \leq n} 
				\left\{ \tau_j^{q+1 + \alpha} t_j^{\beta - q - 1} 
				+ \tau_j^p t_j^{\alpha + \beta - p} \right\},
				&&\text{if } \beta < p - \alpha.
			\end{aligned}
			\right.
		\end{aligned}
	\end{equation}
	where \(\xi_j \in (t_{j-1}, t_j)\), the positive constant \( C \) is independent of the mesh \eqref{mesh}.
\end{lemma}
\begin{proof}
	From the definition of \( \mathcal{E}_n^2 \) in \eqref{Err_2}, together with \eqref{Gx} and \eqref{Rz_bnd}, it follows that
	\begin{align}
		\label{Err2_split}
		\left\| \mathcal{E}_n^2 \right\|_{\mathcal{Y}} &\le CM \sum_{j=2}^n \left( \int_0^\infty x^{-\alpha} \| d_j(x) \|_{\mathcal{X}} \left|\prod_{l=j+1}^{n} R(-\tau_l x)\right| \, dx + P_j \right)\\
		\nonumber
		&\le CM \sum_{j=2}^n \left( \int_0^\infty x^{-\alpha} \| d_j(x) \|_{\mathcal{X}} \, dx + P_j \right),
	\end{align}
	% \begin{equation}\label{Err2_split}
		% 	\left\| \mathcal{E}_n^2 \right\|_{\mathcal{Y}} \le CM \sum_{j=2}^n \left( \int_0^\infty x^{-\alpha} \| d_j(x) \|_{\mathcal{X}} \, dx + P_j \right),
		% \end{equation}
	where \( d_j \) is the defect in \eqref{dn}, $P_j$ is defined in \eqref{Pj}. Applying Lemmas~\ref{lem:integral_bound} and \ref{lem:Pj_bnd} to \eqref{Err2_split} yields the estimate \eqref{Err_2_bnd}, completing the proof.
\end{proof}




Combining Lemmas~\ref{lem:Err_1} and \ref{lem:Err_2}, the convergence results for $f(t)=t^{\beta}\vv$ is stated as below.
\begin{proposition}\label{prop:gCQ_conv}
	Assume that \( K(z) \) satisfies Assumption~\ref{assumptionK} and the Runge--Kutta method satisfies Assumption~\ref{ass_RK}. Given the general time mesh \eqref{mesh}, the error of the Runge--Kutta based gCQ  approximation \eqref{gCQ} applied to \eqref{conv} with \( f(t) = t^\beta \vv \) \(( \beta > -1 )\) satisfies
	\begin{equation}
		\label{err_tbeta}
		\begin{aligned}
			&\left \Vert u(t_n)-u_n\right\Vert_{\mathcal{Y}} \le 
			\\[.5em]
			&	 C M \left\{
			\begin{aligned}
				&|\log(\tau_{\min})|\, \tau_{\max}^{\min\{p,q+1+\alpha\}}, 
				&&\text{if } \beta \ge p - \alpha, \\[6pt]
				&\sum\limits_{j=2}^n \tau_j^{p+1} \xi_j^{\alpha + \beta - p - 1} 
				+ |\log(\tau_n)| \max\limits_{1 \leq j \leq n} 
				\left\{ \tau_j^{q+1 + \alpha} t_j^{\beta - q - 1} 
				+ \tau_j^p t_j^{\alpha + \beta - p} \right\},
				&&\text{if } \beta < p - \alpha,
			\end{aligned}
			\right.
		\end{aligned}
	\end{equation}
	where $n\ge 1$, \( \xi_j \in (t_{j-1}, t_j) \),  $C$ is a positive constant independent of the time mesh \eqref{mesh}.
\end{proposition}
Below we derive specific error estimates for two especial cases: the case of quasi-uniform meshes like in \eqref{quasimesh} and, among them, the case of graded meshes \eqref{gmesh}. For general quasi-uniform meshes we can relax the requirement about the number of vanishing moments at the origin, whereas for graded meshes we do not need to assume any of them, since we can always achieve full order of convergence by choosing properly the grading parameter.

\begin{corollary}\label{cor:conv_tbeta}
	Under the assumptions in Proposition~\ref{prop:gCQ_conv}, the following error estimates hold for \( f(t) = t^{\beta} \vv \).
	\begin{enumerate}[label=(\roman*)]
		\item  \label{itm:tbet_quasi} If the mesh is quasi-uniform as in \eqref{quasimesh}, we can relax the condition on $\beta$ in \eqref{err_tbeta} to  \( \beta \ge \min\{p-\alpha, q+1 \} \), and the error is bounded by
		\begin{equation}\label{fullrate_quasimesh}
			\left \Vert u(t_n) - u_n \right\Vert_{\mathcal{Y}} \le C M c_\Delta^{\max\{0,\, p-q- \alpha\}}  |\log(\tau_{\min})| \tau_{\max}^{\min\{p,q+1+\alpha \}} , \quad n \ge 1.
		\end{equation}

		\item  \label{itm:tbet_grad} For any $\beta >-1$, the error on the graded mesh \eqref{gmesh} can be estimated by
		\begin{equation*}
			\left \Vert u(t_n) - u_n \right\Vert_{\mathcal{Y}} \leq CM \log(N)
			\begin{cases}
				N^{-\gamma(\alpha + \beta)}, & \gamma(\alpha + \beta) < \min\{p, q + 1 + \alpha\}, \\[.5em]
				N^{-\min\{p, q + 1 + \alpha\}}, & \gamma(\alpha + \beta) \ge \min\{p, q + 1 + \alpha\},
			\end{cases}
		\end{equation*}
		where \( 1 \le n \le N \), \( C \) is independent of \( N \).
	\end{enumerate}
\end{corollary}
\begin{proof}
	When \( \beta \ge p - \alpha \), the results in Cases~\ref{itm:tbet_quasi} and \ref{itm:tbet_grad} follow directly from Proposition~\ref{prop:gCQ_conv}. 


	For Case~\ref{itm:tbet_quasi}, it remains to derive the error bound under the condition
	\begin{equation}\label{bet_cond}
		\beta \ge q+1 \quad \text{with} \quad q+1 = \min\{p - \alpha, q + 1\}.
	\end{equation}
	We begin by analyzing the summation in \eqref{err_tbeta}. The quasi-uniformity property of the mesh \eqref{quasimesh} implies the lower bound
	\[
	t_{j-1} = \sum_{\ell = 1}^{j-1} \tau_\ell > \sum_{\ell = 1}^{j-1} \frac{\tau_\ell}{2} + \frac{\tau_j}{4c_\Delta} \ge \frac{t_j}{4c_\Delta}.
	\]
	Applying this bound to the summation in \eqref{Err_2_bnd} yields
	\begin{align*}
		\sum_{j=2}^n \tau_j^{p+1} \xi_j^{\alpha + \beta - p - 1}
		&\le (4c_\Delta)^{\max\{0,\, p+1-\alpha-\beta\}} \sum_{j=2}^n \tau_j^{p+1} t_j^{\alpha + \beta - p - 1} \\
		&\le (4c_\Delta)^{\max\{0,\, p+1-\alpha-\beta\}} \left( \sum_{j=2}^n \tau_j t_j^{-1} \right) \max_{2 \le j \le n} \left\{ \tau_j^p t_j^{\alpha + \beta - p} \right\}.
	\end{align*}
	Using the integral estimate
	\[
	\sum_{j=2}^n \tau_j t_j^{-1} < 1 + \int_{t_1}^{t_n} t^{-1} \, dt = 1 + \log(t_n / t_1)
	\]
	along with \eqref{max_meshbnd} and \eqref{bet_cond}, we obtain
	\begin{equation}\label{sum_quasimeshbnd}
		\sum_{j=2}^n \tau_j^{p+1} \xi_j^{\alpha + \beta - p - 1} 
		\le C\, c_\Delta^{\max\{0,\, p-q - \alpha\}} |\log(\tau_1)|\, \tau_{\max}^{q + 1 + \alpha}\, t_n^{\beta - q - 1}.
	\end{equation}
	Substituting the bound above into \eqref{Err_2_bnd} and then applying \eqref{max_meshbnd} completes the proof of Case~\ref{itm:tbet_quasi}.




	For case~\ref{itm:tbet_grad}, the bound \eqref{err_tbeta} with \( \beta \le p - \alpha \) on the graded mesh \eqref{gmesh} satisfies
	\begin{align*}
		\left\| u(t_n) - u_n \right\|_{\mathcal{Y}} 
		&\leq C M \left( \sum_{j=2}^n \tau_j^{p+1} \xi_j^{\alpha+\beta - p - 1} + \log(N) \max_{1 \leq j \leq n} 
		\left\{ \tau_j^{q+1 + \alpha} t_j^{\beta- q - 1} + \tau_j^p t_j^{\alpha + \beta - p} \right\} \right).
	\end{align*}
	Applying \eqref{grad_sumprodbnd} gives
	\begin{align*}
		\sum_{j=2}^n \tau_j^{p+1} \xi_j^{\alpha+\beta - p - 1} 
		\leq C
		\begin{cases}
			N^{-\gamma(\alpha+\beta)}, & \gamma(\alpha+\beta) < p, \\[0.5em]
			N^{-p} \log(n), & \gamma(\alpha+\beta) = p, \\[0.5em]
			N^{-p} t_n^{\alpha+\beta - p/\gamma}, & \gamma(\alpha+\beta) > p.
		\end{cases}
	\end{align*}
	Next, using \eqref{grad_prodbnd}, we  can derive
	\begin{align*}
		\nonumber
		&\tau_j^{q+1 + \alpha} t_j^{\beta- q - 1} + \tau_j^p t_j^{\alpha + \beta - p} \\[.5em]
		&\le C 
		\begin{cases}
			N^{-\gamma(\alpha + \beta)}, & \text{if } \gamma(\alpha + \beta) < \min\{p,\, q+1+\alpha\}, \\[0.5em]
			N^{-\min\{p,\, q+1+\alpha\}} t_j^{\alpha + \beta - \min\{p,\, q+1+\alpha\}/\gamma}, & \text{if } \gamma(\alpha + \beta) \ge \min\{p,\, q+1+\alpha\}.
		\end{cases}
		%	\label{stage_grad}
	\end{align*}
	Combining these estimates proves \ref{itm:tbet_grad}.
\end{proof}


