\begin{lemma}

	\label{lem:int_dj_peano}
	Let \( y(x, t) \) be the solution to \eqref{ode} with right-hand side given by
	\begin{equation}\label{f_heavis}
		f(t) = H(t - \eta)(t - \eta)^{\beta} \mathbf{v}, \quad \eta \geq 0,
	\end{equation}
	where \( H(\cdot) \) is the Heaviside step function and \( \mathbf{v} \in \mathcal{X} \). Let \( d_j(x) \) denote the associated defect in \eqref{RK_ode_defec}. Under Assumptions~\ref{assumptionK} with \( \beta \geq p - 1 \geq 0 \), for \( 2 \leq j \leq n-1 \), it holds that
	\begin{equation*}
		\| d_j(x) \|_{\mathcal{X}} \left| \prod_{l=j+1}^{n} R(-\tau_l x) \right| \leq C\tau_j^{p}
		\begin{cases}
			t_j^{\beta-p+1}\displaystyle\int_{t_{j-1}}^{t_j} \frac{1} {(t - \eta)(1 + \hat{b}(t_n - t_j) x)} \, dt, & \eta \in [0, t_{j-1}),
			\\[0.7em]
			(1 + \hat{b}(t_n - t_j) x)^{-1},    & \eta \in [t_{j-1}, t_j], \\[0.5em]
			0, & \eta \in (t_j, \infty).
		\end{cases}
	\end{equation*}
	Moreover, for \( j = n \), we have
	\begin{equation*}
		\| d_n(x) \|_{\mathcal{X}}   \leq C     \tau_n^{p}
		\begin{cases}
			t_n^{\beta-p+1}\displaystyle\int_{t_{n-1}}^{t_n} \frac{1}{(t - \eta)(1 + (t - \eta) x)} \, dt, & \eta \in [0, t_{n-1}), \\[0.7em]
			\left\Vert H(t_{n-1}+\cv \tau_n - \eta)(1 + (t_{n-1}+\cv \tau_n - \eta) x)^{-1}\right\Vert_\infty,    & \eta \in [t_{n-1}, t_n], \\[0.5em]
			0, & \eta \in (t_n, \infty), 
		\end{cases}
	\end{equation*}
	where \(\cv = (c_i)_{i=1}^s\) represents the abscissae from the Butcher tableau,   $C$ and $\hat{b}$ are positive constants independent of the mesh. 
\end{lemma}
\begin{proof}
	From the representation in \eqref{RK_ode_defec}, the defect $d_j(x)$ can be expressed as
	\begin{equation*}\label{dj_peano}
		d_j(x) = 
		\begin{cases}    \tau_j^p \int_{t_{j-1}}^{t_j} \kappa\left(\dfrac{t - t_{j-1}}{\tau_j}\right)
			\dfrac{\partial^{p+1} y}{\partial t^{p+1}}(x,t) dt, 
			& \eta \in [0, t_{j-1}), \\[0.5em]
			y(x,t_j) - y(x,t_{j-1}) - \tau_j \mathbf{b}^\top \mathbf{Y}_t(x, t_j), 
			& \eta \in [t_{j-1}, t_j] , \\[0.5em]
			0, & \eta \in(t_j,\infty).
		\end{cases} 
	\end{equation*}
	Applying \eqref{Rz_bnd} and \eqref{ydiff_bndpeano}, we obtain for \( \eta \in [0, t_{j-1}) \):
	\begin{equation*}\label{dj_nearbnd}
		\|d_j(x)\|_{\mathcal{X}} \left|\prod_{l=j+1}^n R(-\tau_l x)\right|
		\leq C \tau_j^p\int_{t_{j-1}}^{t_j} \dfrac{(t - \eta)^{\beta-p}}{(1+(t-\eta)x)(1 + \hat{b}(t_n - t_j)x)} dt,   
	\end{equation*}
	and for \( \eta \in [t_{j-1}, t_j] \):
	\begin{equation*}\label{dj_midbnd}
		\|d_j(x)\|_{\mathcal{X}} \left|\prod_{l=j+1}^n R(-\tau_l x)\right|
		\leq C \tau_j^{\beta+1}\left\Vert  \dfrac{H(t_{n-1}+\cv \tau_n - \eta)}{(1+(t_{n-1}+\cv \tau_n - \eta)x))(1 + \hat{b}(t_n - t_j)x)}\right\Vert_\infty, 
	\end{equation*}
	where \(\cv = (c_i)_{i=1}^s\) denotes the vector of nodes in the Butcher tableau,   and \( \hat{b} > 0 \) is the constant from \eqref{Rz_bnd}. The final bounds then follow from   using $\beta\ge p-1$ and
	\[
	(t-\eta)^{\beta-p} \leq  t_j^{\beta-p+1}/(t-\eta), \quad \text{for }  \, t \in (t_{j-1}, t_j), \ \eta \in (0, t_{j-1}), \ 2 \leq j \leq n.
	\]
\end{proof}

\begin{lemma}\label{lem:E1Pj_peano}
	Let \( y(x, t) \) be the solution to \eqref{ode} with \( f \) given by \eqref{f_heavis}, where \( \beta \ge p-1 \ge 0 \) and \( 0 < \alpha < 1 \). Under Assumptions~\ref{assumptionK} and \ref{ass_RK}, the following estimates hold:
	\begin{equation*}
		\left\| \mathcal{E}_n^1 \right\|_{\mathcal{Y}} 
		\leq C M \tau_1 H(\tau_1 - \eta)(\tau_1 - \eta)^{\alpha + \beta - 1},
	\end{equation*}
	and
	\begin{equation*}
		\sum_{j=2}^n P_j 
		\leq C |\log(\tau_n)| \left( \tau_{\max}^{q+1+\alpha}
		+ \tau_{\max}^p \max_{2 \le j \le n} \left\{ H(t_j - \eta)(t_j - \eta)^{\alpha + \beta - p} \right\} \right),
	\end{equation*}
	where \( \mathcal{E}_n^1 \) denotes the approximation error defined in \eqref{Err_1}, and \( P_j \) is given by \eqref{Pj}.
\end{lemma}
\begin{proof}
	Applying the derivative bound \eqref{ydiff_bndpeano} to the defects $\Dv_1$ in \eqref{Y_tn} yields
	\[
	\max_{1 \le i \le s} \left\| d_{1i}(x) \right\|_{\mathcal{X}} \leq C\Gamma(\beta+1) \tau_1 H(t_1-\eta)(t_1-\eta)^{\beta}.
	\]
	Following the proof of Lemma~\ref{lem:Err_1}, we obtain the stated bound for \( \left\| \mathcal{E}_n^1 \right\|_{\mathcal{Y}} \).

	For \( P_j \) in \eqref{Pj},    adapting the proofs of \eqref{Pn_esti} and \eqref{Pj_esti} and applying \eqref{ydiff_bndpeano} yields
	\begin{align*}  
		P_n &\leq C H(t_n-\eta) \left( \sum_{\ell=q+1}^{p-1} \tau_n^{\alpha+\ell}(t_n-\eta)^{\beta-\ell} + \tau_n^p(t_n-\eta)^{\alpha+\beta-p} \right), \\[0.5em]
		P_j &\leq C H(t_j-\eta) \sum_{\ell=q+1}^{p-1} \tau_j^{\alpha+\ell+1}(\hat{b}(t_n-t_j))^{-1}(t_j-\eta)^{\beta-\ell} \\[0.5em]
		&\quad + C H(t_j-\eta)\tau_j^{p+1}(\hat{b}(t_n-t_j))^{-1}(t_j-\eta)^{\alpha+\beta-p}, \quad 2 \leq j \leq n-1.
	\end{align*}
	The final bound follows from these estimates by noting that \( \beta \geq p-1 \) and applying the logarithmic bound \eqref{log_bnd}.
\end{proof}




\begin{proposition}\label{propo:err_remainder}
	Let the data $f$ in \eqref{conv} be given by
	\begin{equation}\label{int_remainder}
		f(t) = \frac{1}{\Gamma(m+\beta+1)} \left(t^{m+\beta} \ast f^{(m+\beta+1)}\right)(t),
	\end{equation}
	where \(\beta > -1\) and \(m = \lceil p - \beta - 1\rceil\). Under Assumptions~\ref{assumptionK} and~\ref{ass_RK}, the error of the Runge-Kutta based gCQ  approximation \eqref{gCQ} on the general mesh \eqref{mesh} satisfies
	\begin{equation}
		\left\| u(t_n) - u_n \right\|_{\mathcal{Y}} \leq CM |\log(\tau_{\min})| \tau_{\max}^{\min\{p,q+1+\alpha\}} \left\| f^{(m+\beta+1)} \right\|_{C^0([0,t_n],\mathcal{X})}, \quad 1 \leq n \leq N,
	\end{equation}
	where \(C\) is a constant independent of the temporal discretization \eqref{mesh}.
\end{proposition}
\begin{proof}
	Denote \((t-\eta)_+^{m+\beta}:=H(t-\eta) (t-\eta)^{m+\beta}.\)
	Following the argument in \cite[Proposition~13]{GuoLo}, the continuous convolution and its Runge--Kutta based gCQ  approximation, when applied to \( f(t) \) in \eqref{int_remainder}, can be represented as
	\[
	\left[K(\partial_t)f\right](t_n) = \int_0^{t_n} \frac{f^{(m+\beta+1)}(\eta)}{\Gamma(m+\beta+1)} \left[ K(\partial_t) (\cdot - \eta)^{m+\beta}_+\right](t_n) \, d\eta,
	\]
	and
	\[
	\left[K(\partial_t^\Delta) f\right]_n = \int_0^{t_n} \frac{f^{(m+\beta+1)}(\eta)}{\Gamma(m+\beta+1)} \left[ K(\partial_t^\Delta) (\cdot - \eta)_+^{m+\beta} \right]_n\, d\eta.
	\]
	The approximation error then satisfies
	\begin{align*}
		&\left\| \left[K(\partial_t)f\right](t_n) - \left[K(\partial_t^\Delta) f\right]_n\right\|_{\mathcal{Y}} \\
		&= \left\| \int_{0}^{t_n} \frac{f^{(m+\beta+1)}(\eta)}{\Gamma(m+\beta+1)} \left( \left[K(\partial_t)(\cdot-\eta)_+^{m+\beta} \right] (t_n) - \left[ K(\partial_t^\Delta)(\cdot-\eta)_+^{m+\beta} \right]_n\right) d\eta \right\|_{\mathcal{Y}} \\
		&\leq \int_0^{t_n} \left\|\left[K(\partial_t)(\cdot-\eta)_+^{m+\beta} \right] (t_n) - \left[ K(\partial_t^\Delta)(\cdot-\eta)_+^{m+\beta} \right]_n \right\|_{\mathcal{Y}} d\eta \cdot \left\| f^{(m+\beta+1)} \right\|_{C^0([0,t_n],\mathcal{X})}.
	\end{align*}
	Let \( y(x,t) \) be the solution to \eqref{ode} with right hand side \( (t-\eta)_+^{m+\beta} \), and let \( e_n(x) \) denote the associated Runge-Kutta approximation error from \eqref{en}. Combining the error representation in \eqref{gCQ_error_decomposition} with the bound from \eqref{Err2_split}, we obtain 
	\begin{align}\nonumber
		\int_0^{t_n} &\left\|\left[K(\partial_t)(\cdot-\eta)_+^{m+\beta} \right] (t_n) - \left[ K(\partial_t^\Delta)(\cdot-\eta)_+^{m+\beta} \right]_n \right\|_{\mathcal{Y}}\, d\eta \\
		\label{djsum_nminus_split}
		&\leq \int_0^{t_n}\left[ \left\| \mathcal{E}_n^1 \right\|_{\mathcal{Y}}  + CM \sum_{j=2}^n \left( \int_0^\infty x^{-\alpha} \| d_j(x) \|_{\mathcal{X}}\left|\prod_{l=j+1}^{n} R(-\tau_l x)\right| dx + P_j \right)\right]\, d\eta.
	\end{align}
	%==================Integration Details============================================
	For \( 2 \le j \le n - 1 \), applying Lemma~\ref{lem:int_dj_peano} under the condition \( m + \beta \ge p - 1 \), we obtain
	\begin{align*}
		&\int_0^{t_n}\left( \int_0^\infty x^{-\alpha} \| d_j(x) \|_{\mathcal{X}} \left|\prod_{l=j+1}^{n} R(-\tau_l x)\right| \,dx \right) \, d\eta \\
		\nonumber
		&\le C  \tau_j^{p} \int_0^\infty \frac{x^{-\alpha}}{1 + \hat{b}(t_n - t_j)x} \, dx 
		\left(  \int_0^{t_{j-1}} \int_{t_{j-1}}^{t_j} \frac{1}{t - \eta} \, dt \, d\eta+\tau_j  \right)\\
		&\overset{\eqref{int_Betafun}}{=} C \tau_j^{p} (\hat{b}(t_n - t_j))^{\alpha - 1}
		\left( \int_0^{t_{j-1}} \int_{t_{j-1}}^{t_j} \frac{1}{t - \eta} \, dt \, d\eta+\tau_j  \right).
	\end{align*}
	For the integral term, we have
	\begin{align*}
		\int_0^{t_{j-1}} \int_{t_{j-1}}^{t_j} \frac{1}{t - \eta} \, dt \, d\eta & =
		t_j \log(t_j) - \tau_j \log(\tau_j) - t_{j-1} \log(t_{j-1})\\
		&\le \tau_j |\log(\tau_j)| + \tau_j (1+\log(t_j))\le C|\log(\tau_{\min})|\tau_j.
	\end{align*}
	Thus, we can bound the summation w.r.t. $j$ in \eqref{djsum_nminus_split} by
	\begin{align}\nonumber
		&\sum\limits_{j=2}^{n-1}\int_0^{t_n}\left( \int_0^\infty x^{-\alpha} \| d_j(x) \|_{\mathcal{X}} \left|\prod_{l=j+1}^{n} R(-\tau_l x)\right| \,dx \right) \, d\eta \\
		\label{djsum_nmius1_bnd}
		&\le C |\log(\tau_{\min})| \sum\limits_{j=2}^{n-1} \tau_j^{p+1} (\hat{b}(t_n - t_j))^{\alpha - 1}\le C |\log(\tau_{\min})| \tau_{\max}^p t_n^{\alpha}.
	\end{align}
	Now, for the term corresponding to \( j = n \), applying Lemma~\ref{lem:int_dj_peano} and \eqref{int_Betafun}, we get
	\begin{equation}\label{dj_n_bnd}
		\begin{split}
			\int_0^{t_n} \int_0^\infty& x^{-\alpha} \| d_n(x) \|_{\mathcal{X}} \, dx d\eta 
			\le \tau_n^p \int_0^{t_{n-1}} \int_{t_{n-1}}^{t_n} (t - \eta)^{\alpha - 2} \, dt \, d\eta \\[.5em]
			&+ C\tau_n^{p} \int_{t_{n-1}}^{t_n}  \left\|H(t_{n-1} + \cv \tau_n - \eta) (t_{n-1} + \cv \tau_n - \eta)^{\alpha - 1} \right\|_\infty \, d\eta \\[.5em]
			&\le C \tau_n^p \int_0^{t_{n-1}} \left[ (t_n - \eta)^{\alpha - 1} - (t_{n-1} - \eta)^{\alpha - 1} \right] d\eta + C \tau_n^{p+\alpha}\le C\tau_n^p.     
		\end{split}
	\end{equation}
	From \eqref{djsum_nmius1_bnd} and \eqref{dj_n_bnd}, we can get that
	\[
