By applying Proposition~\ref{prop:gCQ_conv} and Proposition~\ref{propo:err_remainder}, we can establish the following convergence results for general integrands \(f(t)\) of the form \eqref{gen_f}.

\begin{proposition}\label{prop:conv_gCQrk}
	Suppose that the transfer operator \(K(z)\) satisfies Assumption~\ref{assumptionK} and the Runge--Kutta method satisfies Assumption~\ref{ass_RK}. Let the integrand \(f(t)\) in  the convolution  \eqref{conv} take the form of  \eqref{gen_f} with \(\beta > - 1\) and \(m = \lceil p - \beta-1\rceil\). Denote 
	\begin{equation*}
		\mu:=\min\{p,q + 1+\alpha\} \text{ and } \nu:=\lceil p-\alpha-\beta - 1\rceil. 
	\end{equation*}
	Then, on the general mesh \eqref{mesh}, it holds
	\begin{align*}
		&\left\| u(t_n) - u_n \right\|_{\mathcal{Y}}\\[.5em]
		&\le C M 
		\sum_{\ell=0}^{\nu} \left(
		\sum_{j=2}^{n} \tau_j^{p+1} \xi_j^{\alpha + \beta + \ell - p - 1} 
		+ \left| \log (\tau_n) \right| \max_{1 \leq j \leq n} \left\{ \tau_j^\mu t_j^{\alpha+ \beta + \ell - \mu} \right\}
		\right) 
		\left\| f^{(\ell+\beta)}(0) \right\|_{\mathcal{X}}\\[.5em]
		&\hfill+CM\left| \log (\tau_{\min}) \right| \tau_{\max}^\mu  \left(	\sum_{\ell=\nu+1}^{m}\left\| f^{(\ell+\beta)}(0) \right\|_{\mathcal{X}} +\left\| f^{(m+\beta+1)} \right\|_{C^0([0,t_n], \mathcal{X})}\right),\quad n\ge 1.	
	\end{align*}
	Here, $\xi_j\in(t_{j-1},t_j)$ and the constant \( C \) is mesh-independent.
\end{proposition}
\begin{remark}
	Proposition~\ref{prop:conv_gCQrk} directly implies the convergence result for general meshes, as stated in Case~\ref{itm:thm_genmesh} of Theorem~\ref{thm:conv_gCQrkGenM}. For quasi-uniform meshes, the convergence result follows from Case~\ref{itm:tbet_quasi} of Corollary~\ref{cor:conv_tbeta}, which is summarized as \ref{itm:thm_quasimesh} in Theorem~\ref{thm:conv_gCQrkGenM}. In the case of graded meshes, the corresponding convergence result is obtained via Case~\ref{itm:tbet_grad} of Corollary~\ref{cor:conv_tbeta}, and is formally stated in Theorem~\ref{thm:conv_gCQrkGrad}.
\end{remark}
