\subsection{Algorithm for the linear subdiffusion equation}
This subsection presents the adaptation of the algorithm developed in Section~\ref{sec:algconv} to discretize the linear subdiffusion equation.
\begin{equation}\label{homo_fracdiffusion}
\begin{array}{rcl}
	\partial_t^\alpha v(t) +\mathcal{A}v(t) & = & f(t)-\mathcal{A}u_0,	\quad t\in (0,T].\\
	v(0)&=&0,
\end{array}
\end{equation}
where $0<\alpha<1$, $\mathcal{A}$ denotes an elliptic operator and $u_0$ is given. Define\[\Vv(t_n)=\left(v(t_{n-1}+c_i\tau_n)\right)_{i=1}^s,\quad \Vv_n=\left(V_{ni}\right)_{i=1}^s,\]
with $V_{ni}$ approximating $v(t_{n-1} + c_i \tau_n)$. To apply the fast gCQ  algorithm for the fractional derivative, we observe that, by definition,
\[
\partial_t^{\alpha} =  \partial_t^{\alpha-1} \partial_t,\quad 0<\alpha<1.
\]
Then, according to the discrete composition rule, it also holds that
\[
\left(\partial^{\Delta}_t \right)^{\alpha} =  \left(\partial^{\Delta}_t \right)^{\alpha-1} \partial^{\Delta}_t,
\]
where $\partial^{\Delta}_{t}$ denotes the approximation of the first order derivative provided by the gCQ  method, this is, \cite[(29)]{LoSau16}
\begin{equation}\label{gCQ_1stderv}
\left[\partial^{\Delta}_{t} \Vv\right]_n = (\tau_n \Av)^{-1}\left(\Vv_n-v_{n-1}\bone\right), \quad 1\le n\le N.
\end{equation}
Thus, we can write
\[
\sum_{j=1}^n \Wv_{n,j}  \left[\partial^{\Delta}_{t} \Vv \right]_{j}  + \mathcal{A}\Vv_n  =  \fv(t_n)-\mathcal{A}u_0\bone, \qquad n\ge 1,
\]
with \( \Wv_{n,j} \) are gCQ  weights \eqref{gCQ_w} for the fractional integral operator \( \partial_t^{\alpha-1} \), this is with
\[G(x)= \frac{\sin(\pi (1-\alpha))}{\pi} x^{\alpha-1}.\]
Subsequently, we have
\[
\Wv_{n,n}  \left[\partial^{\Delta}_{t} \Vv \right]_{n}  + \mathcal{A}\Vv_n  = \fv(t_n)-\mathcal{A}\Uv_0-\sum_{j=1}^{n-1} \Wv_{n,j}  \left[\partial^{\Delta}_{t} \Vv\right]_{j}, \qquad n\ge 1.
\]
Noting from \eqref{gCQ_wContour} that \(\Wv_{n,n} = (\tau_n \Av)^{1 - \alpha}\), and combining this with \eqref{gCQ_1stderv}, the numerical scheme can be reformulated as
\begin{equation}\label{scheme_subd}
\left(( \tau_n\Av)^{-\alpha}I + \mathcal{A} \right) \Vv_n=  \fv(t_n)-\mathcal{A}\Uv_0+ (\tau_n\Av)^{-\alpha} v_{n-1}\bone -\sum_{j=1}^{n-1} \Wv_{n,j}  \left[\partial^{\Delta}_{t} \Vv\right]_{j}, \quad n\ge 1.
\end{equation}
The efficient evaluation of the right-hand side summation term employs the algorithm from Section~\ref{sec:algconv} by splitting it into two parts
\begin{equation}
\sum_{j=1}^{n-1} \Wv_{n,j}  \left[\partial^{\Delta}_{t} \Vv \right]_{j}=\sum_{j=1}^{n-n_0} \Wv_{n,j}  \left[\partial^{\Delta}_{t} \Vv \right]_{j} + \sum_{j=\max(1,n-n_0+1)}^{n-1} \Wv_{n,j}  \left[\partial^{\Delta}_{t} \Vv \right]_{j}.
\end{equation}
The history part is approximated via
\[
\sum_{j=1}^{n-n_0} \Wv_{n,j} \left[\partial^{\Delta}_{t} \Vv \right]_{j} \approx \sum_{l=1}^{N_{Q}^{his}} \varpi_l  G(x_l)\left(\prod_{j=n-n_0+1}^{n} \left(\Rv(-\tau_j x_l)\ev_s^\top\right)\right) \Qv^{his}_{n-n_0}(x_l),
\]
where \( \Qv^{his}_{n-n_0} \) is defined as in \eqref{recursion_his}, with \( \fv_j \) taken to be \( \left[\partial^{\Delta}_{t} \Vv \right]_j \).  For the local part, the approximation is given by
\[\sum_{j=\max(1,n-n_0+1)}^{n-1} \Wv_{n,j} \left[\partial^{\Delta}_{t} \Vv \right]_{j} \approx \sum_{l=1}^{N_{Q}^{loc}} w_l z_l^{\alpha-1} \Rv(\tau_n z_l) \ev_s^\top \Qv^{loc}_{n-1}(z_l),
\]
where $\Qv^{loc}_{n-1}$  satisfies \eqref{recursion_loc}, with $\fv_{n-1}$ replaced by $ \left[\partial^{\Delta}_{t} \Vv \right]_{n-1}$.

\section{Numerical experiments}\label{sec:num_test}
In this section, we consider the application of Runge--Kutta based gCQ  to compute convolution integrals, solve fractional diffusion equations, and nonlinear wave equations with damping terms of convolution type, in order to test the algorithm in Section~\ref{sec:algconv} and verify the theoretical findings presented in Theorems~\ref{thm:conv_gCQrkGrad}. The solutions of the problems under consideration exhibit nonsmooth behavior near the origin and in some cases also at times away from the origin. In all cases, the approximation on uniform time meshes suffers from some sort of order reduction. To achieve full-order convergence, we have implemented the Runge--Kutta based gCQ scheme on graded meshes with a quadrature tolerance $\tol=10^{-14}$ for the fast and oblivious algorithm. When possible, the grading parameter is selected according to Theorem~\ref{thm:conv_gCQrkGrad} and, in the case of Example 5, which is not fully covered by our theory, heuristically. Notice that in this last example we deal with a nonlinear wave problem and error analysis techniques based uniquely on the preservation of the composition rule by the gCQ  method are not enough to justify the observed high order of convergence, cf. \cite{BaBanPtas24}. 
\subsection{Computation of convolution with different kernels}
\begin{example}\label{ex_fracint}
Consider the  Runge--Kutta  based gCQ approximation \eqref{gCQ_appInt} for  the fractional integral  
\begin{equation}\label{fracint}
	\partial_t^{-\alpha}f(t)=\int_0^t\frac{(t-s)^{\alpha-1}}{\Gamma(\alpha)} f(s)\, ds,
\end{equation}
with $	f(t)=t^\beta$ and 
the exact solution is then given by
\begin{equation}\label{fracint_exact}
	\partial_t^{-\alpha}t^\beta=\frac{\Gamma(\beta+1)}{\Gamma(\alpha+\beta+1)}t^{\alpha+\beta}.
\end{equation}
\end{example}
Set $T=1$.  The maximum absolute error in the numerical results is measured by
\begin{equation}\label{MaxAbsErr}
\max_{1\le n\le N}\left| \left[\partial_t^{-\alpha}f\right](t_n) - \left[\left( \partial^{\Delta}_t \right) ^{-\alpha}f \right]_n \right|.
\end{equation}
By applying the two-stage Radau IIA based gCQ  scheme and selecting different values for $\alpha$ and $\beta$, we illustrate the maximum absolute error on the graded mesh \eqref{gmesh} with $\gamma=3/(\alpha+\beta)$ in Figure~\ref{fig:fracint_orderOpt}. The results demonstrate third-order convergence, which aligns with the theoretical findings in Theorem~\ref{thm:conv_gCQrkGrad}.
