\subsection{Differential equations}\label{subsec:expFDE}

\begin{example}\label{ex_fracODE}
We consider the fractional ordinary diffusion equation
\begin{equation*}\label{sca_pro}
	D_t^\alpha u(t) + u(t) = f(t), \quad u(0) = 1, \quad 0 < t \leq 1,
\end{equation*}
with the exact solution
\begin{equation*}
	u(t) = 1 + t^{\beta_1} + H(t - \sigma)(t - \sigma)^{\beta_2}, \quad t \ge 0,
\end{equation*}
where \( \beta_1 > -1 \), \( \beta_2 > \alpha \), and \( H(\cdot) \) denotes the Heaviside function. The corresponding source term takes the form
\begin{equation*}
	f(t) = u(t) + \frac{\Gamma(\beta_1 + 1)}{\Gamma(\beta_1 - \alpha + 1)} t^{\beta_1 - \alpha} + \frac{\Gamma(\beta_2 + 1)}{\Gamma(\beta_2 - \alpha + 1)} H(t - \sigma)(t - \sigma)^{\beta_2 - \alpha},
\end{equation*}
exhibiting piecewise smooth behavior.
\end{example}
For this example, we employ a graded mesh with higher density near the singularities \( t = 0 \) and \( t = \sigma \), defined as
\begin{equation}\label{mesh2sig}
\begin{split}
	&N_1 = \lfloor N \sigma / T \rfloor, \quad 
	\lv(n) = n^{\gamma_1 - 1} (N_1 - n + 1)^{\gamma_2 - 1} N_1^{-\gamma_1 - \gamma_2 + 1}, \quad 1 \le n \le N_1,\\[.5em]
	&t(0) = 0, \quad 
	t(n) = t(n - 1) + \tau(n), \quad 
	\tau(n) = \frac{\sigma}{\| \lv \|_{l^1}} \lv(n), \quad 1 \le n \le N_1,\\[.5em]
	&t(k) = t(N_1) + (T - \sigma) \left( \frac{k - N_1}{N - N_1} \right)^{\gamma_2}, \quad 
	N_1 + 1 \le k \le N-1, \quad 
	t(N) = T.
\end{split}
\end{equation}
In Figure~\ref{fig:ODE_Mesh}, the structure of the mesh defined in~\eqref{mesh2sig} is illustrated, showing that the time step size near \( t = 0 \) and \( t = \sigma \) is of order \( O(N^{-\gamma_1}) \) and \( O(N^{-\gamma_2}) \), respectively, while the maximum step size is of order \( O(N^{-1}) \). The numerical solution, displayed in Figure~\ref{fig:ODE_Sol}, accurately captures the exact solution behavior, even at the discontinuity point \( t = \sigma \). Moreover, as confirmed in Figure~\ref{fig:ODE_heavi}, the optimal convergence order \( \min\{p,\, q + 1 + \alpha\} \) is asymptotically attained by choosing \( \gamma_1 = \min\{p,\, q + 1 + \alpha\} / \beta_1 \) and \( \gamma_2 = \min\{p,\, q + 1 + \alpha\} / \beta_2 \).
