\section{Identities}\label{sec:regularity}
This appendix collects essential mathematical results used in our analysis. We begin with the definition of the Mittag-Leffler function, followed by key identities and estimates for solutions to \eqref{ode}. The proofs of these results follow the techniques in \cite[Lemma 6]{GuoLo}.
\begin{definition}\label{def:ml}
[Mittag-Leffler function] For $\alpha>0$, $\beta\in\mathbb{R}$, the two parameter Mittag-Leffler function $E_{\alpha,\beta}(z)$ is defined by
$$E_{\alpha,\beta}(z)=\sum\limits_{\ell=0}^{\infty}\frac{z^\ell}{\Gamma(\alpha \ell+\beta)},\quad z\in\mathbb{C}.$$
\end{definition}
\begin{lemma}\label{lem:identities}
For  \( \beta > -1 \), \( m \in \mathbb{N} \), it holds
\begin{enumerate}
	\item For $0<\alpha<1$, $\zeta>0$, we have
	\begin{equation}\label{int_Betafun}
		\int_0^\infty x^{-\alpha} \frac{1}{1+\zeta x}\,dx = B(\alpha,1-\alpha)\, \zeta^{\alpha-1},
	\end{equation}
	where \( B \) is the Beta function.
	\item \cite[Theorem 1.6]{Podlubny} For \( \alpha < 2 \), \( \beta \in \mathbb{R} \), there exists a constant \( C > 0 \) such that
	\begin{equation*}\label{bound-absml-neg}
		|E_{\alpha,\beta}(-x)| \le \frac{C}{1+x}, \qquad x\ge 0.
	\end{equation*}
	\item 
	The solution to \eqref{ode} with \( f(t) = t^\beta\vv \) is
	\begin{align*}
		\label{y}
		y(x,t) &= \Gamma(\beta+1) \sum_{\ell=0}^{\infty} \frac{(-x)^{\ell}}{\ell!} \frac{\Gamma(\ell+1)}{\Gamma( \ell+\beta +2)}t^{\ell+\beta+1} \vv, \quad \forall\beta>-1.
	\end{align*}
	Especially, for $\beta\in\bN$, it can be rewritten as
	\begin{equation*}\label{y_int}
		y(x,t) =	\beta!(-x)^{-(\beta+1)}\left(
		\e^{-xt}-\sum_{\ell=0}^{\beta}  \frac{(-xt)^{\ell}}{\ell!}\right) \vv.
	\end{equation*}
	\item The derivatives of the solution to \eqref{ode} with \( f(t) = t^\beta\vv \) with $\beta>-1$ can be expressed explicitly. For \( \beta \notin \mathbb{N} \), the expression is given by
	\begin{eqnarray*}\label{ydiff_nonint}
		\frac{\partial^m y}{\partial t^m}(x, t) = \Gamma(\beta + 1)\, t^{\beta - m + 1} E_{1, \beta - m + 2}(-x t) \vv,
	\end{eqnarray*}
	while for \( \beta \in \mathbb{N} \), it takes the form
	\begin{equation*}\label{ydiff_intg}
		\frac{\partial^m y}{\partial t^m}(x, t) = 
		\begin{cases}
			\beta!\, t^{\beta - m + 1} E_{1, \beta - m + 2}(-x t) \vv, & \text{if } m \le \beta, \\[.5em]
			\beta!\, (-x)^{-\beta + m - 1} e^{-x t} \vv, & \text{if } m \ge \beta + 1.
		\end{cases}
	\end{equation*}
	In both cases, the derivatives satisfy 
	\begin{align}\label{ydiff_bnd}
		\left\Vert  \frac{\partial^m y}{\partial t^m}(x, t) \right\Vert_{\mathcal{X}}  \le \Gamma(\beta + 1)\, t^{\beta - m + 1} \frac{C}{1 + x t},
	\end{align}
	where the constant \( C \) depends on $\Vert \vv\Vert_{\mathcal{X}}$, \( \beta \) and \( m \). In particular, if \( \beta \in \mathbb{N} \) and \( m \ge \beta + 1 \), then \( C = (m - \beta)! \Vert \vv\Vert_{\mathcal{X}}\).
	\item The $m$-th derivative of the solution to \eqref{ode} with \( f(t) = H(t-\eta)(t-\eta)^\beta \vv \), where \( \beta \ge 0 \), \( m \le \beta + 2 \), and \( \eta \ge 0 \), can be expressed explicitly. For \( \beta \notin \mathbb{N} \), the expression is given by
	\begin{align*}
		\frac{\partial^m y}{\partial t^m}(x, t) &=\Gamma(\beta + 1) H(t-\eta) (t-\eta)^{\beta - m + 1} E_{1, \beta - m + 2}(-x (t-\eta))\vv\\[.5em]
		&\hfill+\Gamma(\beta + 1)\delta(t-\eta) (t-\eta)^{\beta - m + 2} E_{1, \beta - m + 3}(-x t) \vv,
	\end{align*}
	while for \( \beta \in \mathbb{N} \), it takes the form
	\begin{equation*}
		\frac{\partial^m y}{\partial t^m}(x, t) = 
		\begin{cases}
			\beta!\, H(t-\eta)(t-\eta)^{\beta - m + 1} E_{1, \beta - m + 2}(-x (t-\eta)) \vv, & \text{if } m \le \beta, \\[.5em]
			\beta!\, H(t-\eta) e^{-x (t-\eta)}\vv, & \text{if } m = \beta + 1\\[.5em]
			\beta!\, \left(-H(t-\eta)x e^{-x (t-\eta)}+\delta(t) e^{-x (t-\eta)} \right) \vv, & \text{if } m = \beta + 2.
		\end{cases}
	\end{equation*}
	In both cases, the derivatives satisfy 
	\begin{align}\label{ydiff_bndpeano}
		\left\Vert  \frac{\partial^m y}{\partial t^m}(x, t) \right\Vert_{\mathcal{X}}  \le C\Gamma(\beta+1) \frac{H(t-\eta) (t-\eta)^{\beta - m + 1}+\delta(t-\eta) (t-\eta)^{\beta - m + 2}}{1 + x t}.
	\end{align}

\end{enumerate}
\end{lemma}
\section{Estimates on the graded mesh}
Some estimates on the graded mesh defined in \eqref{gmesh} are provided below.
\begin{lemma}\label{lem:grad_par}
Let $m > 0$, and consider the time mesh defined in \eqref{gmesh} with step sizes \(\tau_j\). Then for any \(\sigma_j \in [t_{j-1}, t_j]\), \(2 \le j \le n\), the following estimates hold
\begin{align}
	\label{grad_prodbnd}
	\tau_j^{\nu_1+m} \sigma_j^{\nu_2- m} &\le C
	\begin{cases}
		T^{\nu_1+\nu_2} N^{-\gamma (\nu_1+\nu_2)}, & \gamma (\nu_1+\nu_2) < m, \\[0.5em]
		T^{m/\gamma} N^{-m}  t_j^{\nu_1+\nu_2 - m/\gamma}, & \gamma(\nu_1+\nu_2)\ge m,
	\end{cases}
\end{align}
and moreover,
\begin{align}
	\label{grad_sumprodbnd}
	\sum_{j=2}^n \tau_j^{m} \sigma_j^{\nu - m} &\le C
	\begin{cases}
		N^{-\gamma \nu}, & \gamma \nu < m -1, \\[0.5em]
		N^{-(m+1)} \log(n), & \gamma \nu = m - 1, \\[0.5em]
		N^{-(m+1)}  t_n^{\nu - (m+1)/\gamma}, & \gamma \nu > m - 1,
	\end{cases}
\end{align}
where \( C > 0 \) is a constant independent of the mesh.
\end{lemma}

\begin{proof}
From the graded mesh definition \eqref{gmesh}, it follows that
\[
\tau_j \leq \gamma j^{\gamma - 1} \tau^\gamma,
\]
and
\[
\sigma_j^{\nu_2 - m} \leq \max\{(j-1)^{\gamma(\nu_2 - m)}, j^{\gamma(\nu_2 - m)}\} \tau^{\gamma(\nu_2 - m)},
\]
Hence,
\[
\tau_j^{\nu_1+m} \sigma_j^{\nu_2 - m} \leq \gamma^{\nu_1 + m} j^{(\nu_1 + m)(\gamma - 1)} \max\{(j-1)^{\gamma(\nu_2 - m)}, j^{\gamma(\nu_2 - m)}\} \tau^{\gamma(\nu_1 + \nu_2)}.
\]
Using the inequality \( j/2 \leq j - 1 \leq j \) for \( j \geq 2 \), we obtain
\begin{equation*}
	\tau_j^{\nu_1+m} \sigma_j^{\nu_2- m}  \leq \max\{1, 2^{\gamma(m - \nu_2)}\} \gamma^{\nu_1+m}j^{\gamma (\nu_1+\nu_2) - m} \tau^{\gamma (\nu_1+\nu_2)} .
\end{equation*}
This leads to
\begin{align*}
	\tau_j^{\nu_1+m} \sigma_j^{\nu_2- m} 
	&\leq  \max\{1, 2^{\gamma(m - \nu_2)}\} \gamma^{\nu_1+m}
	\begin{cases}
		T^{ \nu_1+\nu_2} N^{-\gamma(\nu_1+\nu_2) }, & \gamma (\nu_1+\nu_2) < m, \\[0.5em]
		T^{m/\gamma} N^{-m}  t_j^{ (\nu_1+\nu_2)- m/\gamma}, & \gamma  (\nu_1+\nu_2) \geq m,
	\end{cases}
\end{align*}
and
\begin{align*}
	\sum_{j=2}^n \tau_j^m \sigma_j^{\nu - m} 
	&\leq  \max\{1, 2^{\gamma(m - \nu)}\} \gamma^m \tau^{\gamma \nu}  \sum_{j=2}^n j^{\gamma \nu - m} \\
	&\le \max\{1, 2^{\gamma(m - \nu)}\} \gamma^m T^\nu
	\begin{cases}
		N^{-\gamma \nu}, & \gamma \nu < m - 1, \\[0.5em]
		N^{-m + 1} \log (n), & \gamma \nu = m - 1, \\[0.5em]
		2^{\gamma\nu-m+1}	N^{-m + 1} t_n^{\nu - (m - 1)/\gamma}, & \gamma \nu > m - 1.
	\end{cases}
\end{align*}
The proof is completed.
\end{proof}
