\subsection{Step-by-step analysis}
The core idea of the algorithm comes
from Newton's iteration, which translates as
\begin{equation}\label{eq:Newton}
\frac\epsilon{2s}+s=\frac{t-s^2}{2s}+s=\sqrt{t}+\frac{(s-
\sqrt{t})^2}{2s},
\end{equation}
where the last term exhibits the quadratic convergence.
The beginning of the analysis is the same as in 
\cref{sec:analysis-algo2}, with absolute error bounds for~$t$ and~$s$,
leading to the system
\begin{equation}\label{eq:algo3-part1}
y=\alpha x,\quad \underline{rx=y(1+u\epsilon_r)},\quad
t=1+r^2+u\epsilon_t,\quad s=\sqrt{t}+u\epsilon_s,\end{equation}
with $|\epsilon_r|\le 1-2u$, $|\epsilon_s|$ and $|\epsilon_t|$ bounded
by~1. In view of the upcoming discussion on~$\alpha$, the analysis in
this section does not make use of the underlined equation.
The next step gives $\epsilon=t-s^2$ (no rounding error by \cref{lemma-boldodaumasSQRT}). 

\paragraph{Detailed analysis for $c$}
From 
\cref{eq:Newton}, it follows that
\[\left|\frac\epsilon{2s}\right|=\left|-u\epsilon_s+\frac{u^2\epsilon_s^2}
{2s}\right|\le u+\frac{u^2}{2}.\]
If $\left|{\epsilon}/{(2s)}\right| \leq u$ then the error committed by rounding
$\frac{\epsilon}{2s}$ to nearest is less than $u^2/2$.
If $\left|{\epsilon}/{(2s)}\right| > u$, then, since the floating-point number
immediately above $u$ is $u + 2u^2$, the upper bound above implies that
$\RN\left({\epsilon}/{(2s)}\right) = \pm u$, so that again the rounding error is
less than $u^2/2$.
Therefore, in all cases, $|c| \leq u$ and
\begin{equation}\label{eq:algo3-part3}
c=\frac\epsilon{2s}+\epsilon_c\frac{u^2}2,
\end{equation}
with $|\epsilon_c|\le1$\footnote{This type of analysis is not automated yet.
By default, our program uses the coarser bound $c=\epsilon
(1+u\epsilon_c)/(2s)$, with
$|\epsilon_c|\le 1-u$. It can be given this extra information
through the two-arguments \texttt{RN}. The difference only
affects the quadratic term in the
final bound.}.
The next steps give 
\begin{equation}\nu=xc(1+u\epsilon_\nu),\quad \rho=(\nu+xs)(1+u\epsilon_\rho),
\label{eq:algo3-part2}\end{equation}
with $|\epsilon_\nu|$ and
$|\epsilon_\rho|$ bounded by $1/(1+u)$ by \cref{rel-err-v}. 
The result of this analysis is the following formula.
\begin{lemma}\label{lemma:rel-err-3}
The relative error of Algorithm~\ref{Beebe-alg} is bounded by
\begin{align}
R&=\sqrt{1+\frac{r^2-\alpha^2}
{1+\alpha^2}}
\sqrt{1+\frac{u\epsilon_t}{1+r^2}}\label{eq:defR-algo3}\\ 
&\qquad\qquad\times
\left(1+\frac{u^2}{2\sqrt{t}}
((\epsilon_c+\epsilon_s^2/s)(1+u\epsilon_\nu)-2\epsilon_s\epsilon_\nu)
\right)
(1+u\epsilon_\rho)-1,\notag\\
&=\frac{r^2-\alpha^2+u\epsilon_t}
{2(1+\alpha^2)}+u\epsilon_\rho+O
(u^2),\quad u\rightarrow0.\notag
\end{align}
Moreover, in this formula, $|\epsilon_s|,|\epsilon_t|,|\epsilon_c|$ are bounded
by~1 and $|\epsilon_\nu|$ and $|\epsilon_\rho|$ by $1/(1+u)$. 
\end{lemma}
\begin{proof}
This is obtained from the previous equations by a sequence of
rewriting
operations
\begin{align}
\rho&=(\nu+xs)(1+u\epsilon_\rho),\notag \\
% &=x\left(c(1+u\epsilon_\nu)+s\right)(1+u\epsilon_\rho),\\
% &=x\left((\frac\epsilon{2s}+\frac{u^2}2\epsilon_c)(1+u\epsilon_\nu)+s\right)
% (1+u\epsilon_\rho),\\
&=x\left((-u\epsilon_s+\frac{u^2}2(\epsilon_c+\epsilon_s^2/s))
(1+u\epsilon_\nu)+\sqrt{t}+u\epsilon_s\right)
(1+u\epsilon_\rho),\notag \\
&=x\left(\sqrt{t}+\frac{u^2}2
((\epsilon_c+\epsilon_s^2/s)(1+u\epsilon_\nu)-2\epsilon_s\epsilon_\nu)
\right)
(1+u\epsilon_\rho),\label{eq:algo3-simple-rho} \\
% &=x\sqrt{t}\left(1+\frac{u^2}{2\sqrt{t}}
% ((\epsilon_c+\epsilon_s^2/s)(1+u\epsilon_\nu)-2\epsilon_s\epsilon_\nu)
% \right)
% (1+u\epsilon_\rho),\\
&=x\sqrt{1+r^2}\sqrt{1+\frac{u\epsilon_t}{1+r^2}}
\left(1+\frac{u^2}{2\sqrt{t}}
((\epsilon_c+\epsilon_s^2/s)(1+u\epsilon_\nu)-2\epsilon_s\epsilon_\nu)
\right)
(1+u\epsilon_\rho)\notag,
\end{align}
whence the relative error of \cref{eq:defR-algo3}.
\end{proof}
The rest of the proof of \cref{th-sharp-alg-beebe} can be found in
\cref{app-proof-beebe}.

