\section{Proof of Theorem \ref{th-sharp-alg-beebe}}
\label{app-proof-beebe}
\subsection{Linear term and interval splitting}
The Taylor expansion of~$R$ in \cref{lemma:rel-err-3} shows the importance of a good upper bound on
the error on~$r$. If one uses the
underlined
equation in \cref{eq:algo3-part1},
then $r^2=\alpha^2(1+u\epsilon_r)^2$;
the linear
term is
maximized when $\epsilon_\rho,\epsilon_t,\epsilon_r$ are all equal to~1, where
it becomes
\[\frac{2\alpha^2+1}{2(1+\alpha^2)}+1=2-\frac{1}{2(1+\alpha^2)}.
\]
This bound on the linear term is increasing with respect to~$\alpha$.
If $\alpha$
ranges from 0 to~1, then the maximum is reached at
$\alpha=1$, where the value
is~$7/4$. This is the
result of our first automatic analysis.
If $\alpha$ ranges from 0 to $1/2$ only, then the bound reached
at~$\alpha=1/2$ is $8/5$, the result of our second automatic analysis.

Finally, if $\alpha\ge 1/2$, then so is its rounded value~$r$ and one
can use the \emph{absolute} error bound
\begin{equation}\label{eq:algo3-abs-err-r}
r=\alpha+\frac{u\epsilon_r}2,\quad |\epsilon_r|\le 1.
\end{equation}
The linear term above becomes
\[\frac{\alpha+1}{2(1+\alpha^2)}+1,\]
which is decreasing with~$\alpha$ for $\alpha\ge1/2$. Thus the
maximum is reached at $\alpha=1/2$, where again $8/5$ is obtained.

Actually, using an absolute error bound is beneficial for $\alpha\le 1/2$ as
well.  This type of variation on
the analysis can also be requested of our implementation, by adding the keyword
\texttt{absolute} as second argument to \texttt{RN}:
\begin{Verbatim}
> Algo3_1:=[Input(x=0..2^16,alpha=0..1/2),y=RN(alpha*x,0),
> r=RN(y/x,absolute),t=RN(1+r^2),s=RN(sqrt(t)),
> epsilon=RN(t-s^2,0),c = RN(epsilon/2/s,absolute(_u^2/2)),
> nu = RN(x*c),rho=RN(nu+x*s)]: 
> BoundRoundingError(Algo3_1,steps="linear");
\end{Verbatim}
\[
{\color{blue}\left(\frac{5}{4}+\frac{\sqrt{5}}{8}\right) \textit{\_u}}
\]
(The optional argument \texttt{steps="linear"} specifies that only
the linear term of the error bound is computed.)

Indeed, for $\alpha\le 1/2$, the absolute error bound becomes
\[r=\alpha+\frac{u\epsilon_r}4,\quad |\epsilon_r|\le 1.\]
While this bound is not as good as the relative error bound for $\alpha<1/4$,
it allows one to bound the linear term of \cref{eq:defR-algo3} by
\[\frac{\alpha/2+1}{2(1+\alpha^2)}+1,\]
whose maximum~---~reached at $\alpha=\sqrt{5}-2\simeq0.236$~---~equals $(10+
\sqrt{5})/8\simeq 1.53$, which is smaller than $8/5$. Thus the maximal value of
the linear part is reached as $\alpha$ approaches $1/2$ from the right.

\subsection{Bounds on partial derivatives}
In view of the previous discussion, we replace the underlined bound in 
\cref{eq:algo3-part1} by
\begin{equation}\label{eq:algo3-r}
r=\alpha+u\epsilon_r,\quad|\epsilon_r|\le\begin{cases}
\frac14,\quad&\text{if $\alpha\le1/2$,}\\ 
\frac12,\quad&\text{if $\alpha>1/2$.}
\end{cases}\end{equation}

The analysis of the linear term shows that in a neighborhood of $u=0$, the
relative error $R$, seen as a function of $u$,
$\alpha$ and the $\epsilon_i$, is increasing with
$\epsilon_\rho,\epsilon_t,\epsilon_r$. We
first show that these properties hold for all $u\in[0,1/2]$ and that
the derivative wrt $\epsilon_c$ also has constant sign.
\begin{lemma}\label{lemma:algo3-derivatives} For $u\in[0,1/2]$, 
\[\frac{\partial R}{\partial\epsilon_\rho}\ge0,\quad 
\frac{\partial R}{\partial\epsilon_t}\ge0,\quad 
\frac{\partial R}{\partial\epsilon_r}\ge0,\quad\frac{\partial R}
{\partial\epsilon_c}\ge0.
\]
\end{lemma}
\begin{proof}
Simple inequalities that can be used in the analysis are
\begin{equation}\label{eq:algo3-simple-ineqs}
|\epsilon_i|\le 1\quad i\in\{r,s,c,\nu,\rho\},\quad 
r\in[0,1],\quad t\in[1,2],\quad s\in[1,2].
\end{equation}
For $u\in[0,1/2]$, we first consider the factors of $R+1$ in 
\cref{eq:defR-algo3}:
\begin{gather*}
\left|\frac{u^2}{2\sqrt{t}}
((\epsilon_c+\epsilon_s^2/s)(1+u\epsilon_\nu)-2\epsilon_s\epsilon_\nu)\right|
\le\frac{u^2}2(2(1+u)+2)=u^2(2+u)<1;\\
\left|\frac{r^2-\alpha^2}{1+\alpha^2}\right|=
\left|\frac{u\epsilon_r
(2\alpha+u\epsilon_r)}{1+\alpha^2}\right|\le \frac{u(2+u/2)}2<1.
\end{gather*}
This implies that all the factors of $R+1$ in \cref{eq:defR-algo3}
are positive. Also, it follows that the
derivative of~$R$ with respect to~$\epsilon_\rho$ is positive.

Using \crefrange{eq:algo3-part1}{eq:algo3-part2}, it can be checked that
\[\frac{\partial R}{\partial\epsilon_t}=\frac{(R+1)ux(2
s^2-u^2\epsilon_s^2(1+u\epsilon_\nu))}{4s^2\sqrt{t}
(\nu+xs)}\]
and the nonnegativity of the right-hand side for $u\in[0,1/2]$ is
clear since $s\ge1$. The same conclusion follows for $\epsilon_r$ in
view of
\[\frac{\partial R}{\partial\epsilon_r}=2r\frac{\partial R}
{\partial\epsilon_t},\]
which, again, is checked with \crefrange{eq:algo3-part1}{eq:algo3-part2}.
Finally, the case of the derivative with respect to $\epsilon_c$ follows from
\[\frac{\partial R}{\partial\epsilon_c}=(R+1)\frac{u^2x(1+u\epsilon_\nu)}{2
(xs+\nu)}.\qedhere\]
\end{proof}

\subsection{Bounds on the relative error}

\subsubsection{First part: upper bound for
\texorpdfstring{$\alpha<1/2$}{alpha<1/2} and lower bound for
 all \texorpdfstring{$\alpha$}{alpha}}
For these cases, we prove bounds on the absolute value of~$R$ that are smaller than
$8u/5+u^2$ for $u\in[0,1/16]$.

From \cref{eq:algo3-simple-rho}, it follows that
\[R=\frac{1}{\sqrt{1+\alpha^2}}\left(\sqrt{t}+\frac{u^2}2
((\epsilon_c+\epsilon_s^2/s)(1+u\epsilon_\nu)-2\epsilon_s\epsilon_\nu)
\right)
(1+u\epsilon_\rho)-1.\]
Upper (resp. lower) bounds on the factor of~$u^2/2$ are reached at $
(\epsilon_c,\epsilon_s,\epsilon_\nu)=(1,-1,1)$ (resp. $(-1,1,1))$).
Thus,
\begin{multline*}
\frac{1}{\sqrt{1+\alpha^2}}\left(\sqrt{t}-{u^2}\frac{3s-1}{2s}-u^3
\frac{s-1}{2s}\right)
(1+u\epsilon_\rho)\\ \le R+1
\le\frac{1}{\sqrt{1+\alpha^2}}\left(\sqrt{t}+
{u^2}\frac{3s+1}{2s}+u^3\frac{s+1}{2s}
\right)
(1+u\epsilon_\rho)
\end{multline*}
The lower bound is lower bounded by its value at $s=2$, while the upper
bound is upper bounded by
its value at~$s=1$, whence
\begin{multline*}
\frac{1}{\sqrt{1+\alpha^2}}\left(\sqrt{t}-\frac{5u^2}{4}-
\frac{u^3}{4}\right)
\left(1-\frac{u}{1+u}\right)\\ \le R+1
\le\frac{1}{\sqrt{1+\alpha^2}}\left(\sqrt{t}+
2{u^2}+u^3
\right)
\left(1+\frac{u}{1+u}\right)
\end{multline*}
Next, $t=1+u\epsilon_t+(\alpha+u\epsilon_r)^2$ is minimal for $\epsilon_t=-1$
and $\epsilon_r=-\epsilon_r^{\max}$ and maximal for the opposite of these
values, giving
\begin{multline*}
\frac{1}{\sqrt{1+\alpha^2}}\left(\sqrt{1-u+(\alpha-u\epsilon_r^{\max})^2}-
\frac{5u^2}{4}-
\frac{u^3}{4}\right)
\left(1-\frac{u}{1+u}\right)\\ \le R+1
\le\frac{1}{\sqrt{1+\alpha^2}}\left(\sqrt{1+u+(\alpha+u\epsilon_r^{\max})^2}+
2{u^2}+u^3
\right)
\left(1+\frac{u}{1+u}\right)
\end{multline*}
We show the steps of the proof that 
\[R\ge -\frac85u\quad\text{for}\quad\alpha\in[0,1/2],\quad\epsilon_r^{
\max{}}=1/4,\quad
u\in
[0,1/4].\] The proofs of the following two other inequalities,
\begin{align*}
R\ge -\frac85u&\quad\text{for}\quad\alpha\in[1/2,1],\quad\epsilon_r^{
\max{}}=1/2,\quad u\in
[0,1/4],\\
R\le \frac85u+u^2&\quad\text{for}\quad\alpha\in
[0,1/2],\quad\epsilon_r^{
\max{}}=1/4,\quad u\in[0,1/16],
\end{align*}
follow the same template.

The function 
\[\frac{1}{\sqrt{1+\alpha^2}}\left(\sqrt{1-u+(\alpha-u/4)^2}-
\frac{5u^2}{4}-
\frac{u^3}{4}\right)
\left(1-\frac{u}{1+u}\right)-1+\frac85u\]
is positive for $u\rightarrow0$, $\alpha\in[0,1/2]$. Eliminating both square
roots shows that it does not vanish unless the following polynomial does:
\begin{multline*}
E(u,\alpha)=1600 \left(12 \alpha^{2}-5 \alpha +2\right)^{2}+80 \left(1136
\alpha^{2}+1161\right) \left(12 \alpha^{2}-5 \alpha +2\right) u\\ 
 +\left(553216 \alpha^{4}+307200 \alpha^{3}+777632 \alpha^{2}+307200 \alpha
