\subsubsection{Last part: upper bound for
\texorpdfstring{$1/2\le\alpha\le1$}{1/2≤alpha≤1}}
In order to obtain a tight bound on the relative error in that case, we first
consider the derivative with respect to $\epsilon_\nu$ and $\epsilon_s$.
\paragraph{Derivative with respect to $\epsilon_\nu$.}
Similar manipulations as above give
\[\frac{\partial R}{\partial\epsilon_\nu}=(R+1)\frac{ucx}{xs+\nu},
\]
whose sign is given by that of~$c$. Thus the extremal value are reached at
$\epsilon_\nu=\pm1/(1+u)$, except when $c=0$.

The case $c=0$ can be treated separately. When $c=0$, then $\epsilon=\nu=0$, $s=
\sqrt{t}$ and $R$ is bounded by~$8u/5$ for $\alpha\in[1/2,1],u\in
[0,1/2],|\epsilon_r|\le1/2$:
\begin{align*}R=\frac{\sqrt{t}}{\sqrt{1+\alpha^2}}-1
&=\sqrt{1+u\frac{2\alpha\epsilon_r+\epsilon_t+u\epsilon_r^2}{1+\alpha^2}}-1\\ 
&\le \sqrt{1+u\frac{1+\alpha+u/4}{1+\alpha^2}}-1
\le\sqrt{1+u(1+u/5)}-1
\le\frac85u.
\end{align*}
\paragraph{Derivative with respect to $\epsilon_s$.}
It can be checked with \crefrange{eq:algo3-part1}{eq:algo3-part2} that
\[\frac{\partial R}{\partial\epsilon_s}=\frac{u^2(1+u\epsilon_\rho)}
{2s^2\sqrt{1+\alpha^2}}\left(-2t\epsilon_\nu+2\sqrt{t}\epsilon_s+u\epsilon_s
(\epsilon_s-2\sqrt{t}\epsilon_\nu)-u^2\epsilon_\nu\epsilon_s^2\right).\]
When $\epsilon_\nu=1/(1+u)$ and $\alpha\in[1/2,1]$, the last factor
reaches its maximum for $(u,\epsilon_s,t)\in[0,1/4]\times
[-1,1]\times[5/4,2]$ at $t=5/4$, $u=1/4$, $\epsilon_s=1$, where it equals
$4/\sqrt5-9/5<0$,
making the derivative negative. Similarly, when
$\epsilon_\nu=-1/(1+u)$ and $\alpha\in[1/2,1]$, the last factor
reaches its minimum for $(u,\epsilon_s,t)\in[0,1/16]\times[-1,1]\times[5/4,2]$
at $t=5/4$, $u=1/16$, $\epsilon_s=-1$, where it equals
$(329-144\sqrt5)/136>0$,
making the derivative positive.

Thus, for $\alpha\in[1/2,1]$ and $u\in[0,1/16]$, at the extremal values
$\epsilon_\nu=\pm1/(1+u)$, the value of~$R$ is
maximized when $\epsilon_s=\mp1$.

\paragraph{Derivative with respect to $\alpha$}
The derivative with respect to~$\alpha$ factors as
\begin{multline*}
\frac{\partial R}{\partial\alpha}=
\frac{u(1+u\epsilon_\rho)}
{2s^2\sqrt{t}(1+\alpha^2)^{3/2}}
\left(
 -2 \left(\alpha^{2} \epsilon_{r}+\alpha  \epsilon_{t}-\epsilon_{r}\right) s^
 {2}\right.\\
+\left(2 \sqrt{t}\, \alpha  \,s^{2} \epsilon_{\nu} \epsilon_{s}-\sqrt{t}\,
\alpha  \,s^{2} \epsilon_{c}-\sqrt{t}\, \alpha  s \epsilon_{s}^{2}-\alpha^{2} r \epsilon_{s}^{2}-2 \alpha  \epsilon_{r}^{2} s^{2}-r \epsilon_{s}^{2}\right) u\\
\left.-\epsilon_{\nu} \left(\sqrt{t}\, \alpha  \,s^{2} \epsilon_{c}+\sqrt{t}\,
\alpha  s \epsilon_{s}^{2}+\alpha^{2} r \epsilon_{s}^{2}+r \epsilon_{s}^{2}\right) u^{2}
\right).
\end{multline*}

By \cref{lemma:algo3-derivatives} and the evaluation of the derivatives above,
for $\alpha\in[1/2,1]$ and $u\in
[0,1/16]$, $|R|$ is upper
bounded by the maximum of its values at the points
\[
(\epsilon_\rho,\epsilon_t,\epsilon_r,\epsilon_c,\epsilon_\nu,\epsilon_s)=
\left(\frac1{1+u},1,\frac12,1,\frac{\pm1}{1+u},\mp1\right):=\pi_\pm.\]
At these values, the last factor in $\partial R/\partial\alpha$ is upper bounded
by
\[-2\left(\frac18\right)-\left(\frac32+\frac12+\frac18+\frac14+\frac12\right)u
+(4\sqrt2+2\sqrt2+1+1)u^2,\]
which is negative for $u\in[0,1/16]$ making the derivative with respect
to~$\alpha$ negative, so that the maximum is reached at $\alpha=1/2$.

\paragraph{Final bound}
By \cref{lemma:algo3-derivatives} and the evaluation of the derivatives above,
the maximal value of~$R$ is reached at $\alpha=1/2$ and $
(\epsilon_\rho,\epsilon_t,\epsilon_r,\epsilon_c,\epsilon_\nu,\epsilon_s)=\pi_\pm$, where
\[R=\frac{1}{\sqrt{1+1/4}}\left(\sqrt{t}+\frac{u^2}2
\left((1+1/s)\left(1\pm\frac u{1+u}\right)+\frac2{1+u}\right)
\right)
\left(1+\frac u{1+u}\right)-1,\]
with
\[s=\sqrt{t}\mp u,\quad t=1+u+\left(\frac12+\frac u2\right)^2.\]
It follows that the maximal value is reached at~$\pi_+$.

The approach for the last step is as in the analysis of Algorithm~2.
At $\pi_+$,
