\section{Proof of Theorem~\ref{thm-alg-Borges}}
\label{app-proof-thm-Borges}
\subsection{Step-by-step analysis}
From the properties of Algorithms Fast2Sum and Fast2Mult and \cref{lemma-knuth-dekker,lemma-boldodaumasSQRT}, we obtain
the following relations (as before, \(u\le 1/4\)):
\begin{align}
y=\alpha x,&\notag\\
s_x^h=x^2(1+u\epsilon_{s_x^h}),&\quad |\epsilon_{s_x^h}|\le\frac1
{1+u},\label{eq:sxh}\\
s_x^h+s_x^\ell=x^2,&\label{eq:sxl}\\
s_y^h=y^2(1+u\epsilon_{s_y^h}),&\quad |\epsilon_{s_y^h}|\le\frac1
{1+u},\label{eq:syh}\\
s_y^h+s_y^\ell=y^2,&\label{eq:syl}\\
\sigma_h=(s_x^h+s_y^h)(1+u\epsilon_{\sigma_h}),
&\quad|\epsilon_{\sigma_h}|\le\frac1{1+u},\label{eq:sigmah}\\
\sigma_h+\sigma_\ell=s_x^h+s_y^h,&\label{eq:sigmal}\\
s=\sqrt{\sigma_h}(1+u\epsilon_s),&\quad|\epsilon_s|\le \frac1u
(1-\frac1{\sqrt{1+2u}})=\frac{2}{\sqrt{1+2u}(1+\sqrt{1+2u})},
\label{eq:s}\\
s^2+\delta_s=\sigma_h,&\label{eq:deltas}\\
\tau_1=(s_x^\ell+s_y^\ell)(1+u\epsilon_{\tau_1}),
&\quad|\epsilon_{\tau_1}|\le \frac1{1+u},\label{eq:tau1}\\
\tau_2=(\delta_s+\sigma_\ell)(1+u\epsilon_{\tau_2}),
&\quad|\epsilon_{\tau_2}|\le \frac1{1+u},\label{eq:tau2}\\
\tau=(\tau_1+\tau_2)(1+u\epsilon_\tau),&\quad|\epsilon_\tau|\le \frac1
{1+u},\label{eq:tau}\\
c=\frac{\tau}s(1+u\epsilon_c),&\quad|\epsilon_c|\le 1-2u,
\label{eq:c}\\
\rho=\left(s+\frac12c\right)
(1+u\epsilon_\rho),&\quad|\epsilon_\rho|\le \frac1{1+u}.\label{eq:rho}
\end{align}

For the analysis, it is important to isolate terms of order \(u\), thus
we introduce variables \(\theta_v\) so that
\[v=u\theta_v,\qquad v\in\{s_x^\ell,s_y^\ell,\sigma_\ell,\delta_s,\tau_1,\tau_2,\tau,c\}.\]
From the equations above, it follows that these are given explicitly by
\begin{align}
\theta_{s_x^\ell}&=-x^2\epsilon_{s_x^h},&\quad
\theta_{s_y^\ell}&=-y^2\epsilon_{s_x^h},\label{eq:theta1}\\
\theta_{\sigma_\ell}&=-(s_x^h+s_y^h)\epsilon_{\sigma_h},&\quad
\theta_{\delta_s}&=-\sigma_h\epsilon_s(2-u\epsilon_s),\label{eq:theta2}\\
\theta_{\tau_1}&=(\theta_{s_x^\ell}+\theta_{s_y^\ell})(1+u\epsilon_
{\tau_1}),&\quad
\theta_{\tau_2}&=(\theta_{\delta_s}+\theta_{\sigma_\ell})(1+u\epsilon_
{\tau_2}),\label{eq:theta3}\\
\theta_\tau&=(\theta_{\tau_1}+\theta_{\tau_2})(1+u\epsilon_\tau),&\quad
\theta_c&=\frac{\theta_\tau}s(1+u\epsilon_c).\label{eq:theta4}
\end{align}

\subsection{Relative error and its linear
term}\label{relative-error--its-linear-term}

The computation proceeds by using the \emph{equalities} defining the
successive
variables in such a way that the leading coefficient in \(u\) is made
apparent, and the error term is given an explicit expression in terms of
the variables \(\epsilon_i\). This will then be followed by a
computation of bounds using the known \emph{inequalities} on these
quantities.

The starting point is
\begin{align}
x^2+y^2&=s_x^h+s_y^h+s_x^\ell+s_y^\ell,&&\text{from \cref{eq:sxl,eq:syl}}\\
&=\sigma_h+\sigma_\ell+s_x^\ell+s_y^\ell,&&\text{from \cref{eq:sigmal}}\\
&=s^2+\delta_s+\sigma_\ell+s_x^\ell+s_y^\ell,&&\text{from 
\cref{eq:deltas}}\\
&=s^2\left(1+\frac{\delta_s+\sigma_\ell+s_x^\ell+s_y^\ell}
{s^2}\right).&&
\end{align}
Then, taking square roots,
\begin{align}
\sqrt{x^2+y^2}&=s\sqrt{1+\frac{\delta_s+\sigma_\ell+s_x^\ell+s_y^\ell}
{s^2}},\notag\\
&=s\sqrt{1+\frac1{s^2}(\frac{\tau_1}{1+u\epsilon_{\tau_1}}+
\frac{\tau_2}{1+u\epsilon_{\tau_2}})},\qquad\qquad\text{from 
\cref{eq:tau1,eq:tau2}}\notag\\
&=s\sqrt{1+\frac{\tau_1+\tau_2}{s^2}-\frac u{s^2}(\frac{\epsilon_
{\tau_1}\tau_1}{1+u\epsilon_{\tau_1}}+\frac{\epsilon_{\tau_2}\tau_2}
{1+u\epsilon_{\tau_2}})},\notag\\
&=s\sqrt{1+\frac\tau{s^2}-\frac u{s^2}(\frac{\epsilon_\tau\tau}
{1+u\epsilon_\tau}+\frac{\epsilon_{\tau_1}\tau_1}{1+u\epsilon_
{\tau_1}}+\frac{\epsilon_{\tau_2}\tau_2}{1+u\epsilon_{\tau_2}})},\quad
\text{from \cref{eq:tau}}\notag\\
&=s\sqrt{1+\frac{\tau}{s^2}-u^2A},\qquad\qquad\qquad\qquad\qquad
\text{from
\cref{eq:theta3,eq:theta4}}\notag\\
&\text{with}\quad A=\frac{1}{s^2}(
\frac{\epsilon_\tau\theta_\tau}{1+u\epsilon_\tau}+\frac{\epsilon_
{\tau_1}\theta_{\tau_1}}{1+u\epsilon_{\tau_1}}+\frac{\epsilon_
{\tau_2}\theta_{\tau_2}}{1+u\epsilon_{\tau_2}}),\label{eq:A}\\
&=s\left(1+\frac{\tau}{2s^2}-u^2B\right),\notag\\
&\text{with}\quad B=\left(1+u
\frac{\theta_\tau}{2s^2}-\sqrt{1+u\frac{\theta_\tau}
{s^2}-u^2A}\right)/u^2,\label{eq:B}\\
&=s+\frac c2-u^2\frac{\epsilon_c\theta_c}{2
(1+u\epsilon_c)}-u^2sB,\qquad\qquad\text{from
\cref{eq:c,eq:theta4}}\notag\\
&=\frac{\rho}{1+u\epsilon_\rho}-u^2\frac{\epsilon_c\theta_\tau}
{2s}-u^2sB,\qquad\qquad\quad\text{\ from
\cref{eq:rho}}\notag\\
&=\rho\left(\frac{1}{1+u\epsilon_\rho}-u^2C\right),\qquad C=
\frac{1}\rho\left(\frac{\epsilon_c\theta_\tau}{2s}+sB\right)
\label{eq:def-C}.
\end{align}

In summary, we have obtained the following.
\begin{lemma}\label{lemma-Borges} The relative error of 
Algorithm~\ref{Borges-fused} is
\begin{align*}
R:=\frac\rho{\sqrt{x^2+y^2}}-1=\frac1{\frac1{1+u\epsilon_\rho}-{u^2}C}-1=u\epsilon_\rho+O(u^2),
\end{align*}
with $C$ defined in \cref{eq:def-C}, in terms of variables $A,B$ and
\(\theta_v\) defined in 
\cref{eq:A,eq:B,eq:theta1,eq:theta2,eq:theta3,eq:theta4}. Moreover, in
this
formula,
\[|\epsilon_s|\le 1-\frac1{\sqrt{1+2u}},\qquad |\epsilon_c|\le 1-2u,\]
and
\(|\epsilon_{s_x^h}|,|\epsilon_{s_y^h}|,|\epsilon_{\sigma_h}|,|\epsilon_{\tau_1}|,|\epsilon_{\tau_2}|,|\epsilon_\tau|,|\epsilon_\rho|\)
are bounded by \(1/(1+u)\).
\end{lemma}

\subsection{Bounds}\label{bounds}
Our implementation claims that the maximal value of the bound
from \cref{lemma-Borges} is reached with the extreme values
\begin{gather*}
\epsilon_{s_x^h}=\epsilon_{s_y^h}=\epsilon_{\sigma_h}=-\frac1
{1+u},\quad
\epsilon_{\tau_1}=\epsilon_
{\tau_2}=\epsilon_\tau=\epsilon_\rho=\frac1{1+u},\\
\epsilon_c=1-2u,\quad
\epsilon_s=\frac1u\left(\frac1{\sqrt{1+2u}}-1\right).
\end{gather*}
We do not
have a human-readable proof of this fact, which has \cref{conj-beebe}
as a direct consequence.

