where, as before, the symbol $\mathbb{B}_D$ to represents the set of finite regular Borel measures supported over $[-1,1]^D$. With this notation, we may now proceed.

\begin{proposition}
    \label{prop:eqsets}
There exists a continuous surjective map,
$$\zeta :\mathcal{S}_L \rightarrow \mathcal{F}_L$$
between $ \mathcal{S}_L$ and $ \mathcal{F}_L$ that satisfies,
\begin{equation}
    \left [  \zeta \left ( \mu(\cdot) \right ) \right ]_n =  \sum_{l=1}^L \prod_{i=1}^D \mu_{i, n_i}^{(l)},
\end{equation}
for every $\mu(\cdot) \in \mathcal{S}_L$ and $  \lvert n \rvert  \leq d$.
\end{proposition}
\begin{proof}
    Given an element,
    \begin{equation}
         \mu(\cdot) := \sum_{l=1}^L \prod_{i=1}^D  \mu_i^{(l)} (\cdot)  \in \mathcal{S}_L
    \end{equation}
    we define the map $\zeta(\cdot)$ through,
    \begin{equation}
         \left [  \zeta \left ( \mu(\cdot) \right ) \right ]_n := \int_{[-1,1]^D}  \, x^{n} \, \mathrm{d} \mu (x) = \sum_{l=1}^L \prod_{i=1}^D  \int_{[-1,1]^D}  \, x_i^{n_i} \, \mathrm{d} \mu_i^{(l)} (x_i)
    \end{equation}

    First, we demonstrate that $\zeta \left ( \mu(\cdot) \right )$ belongs to $\mathcal{F}_L$. To do so, let,
    \begin{equation}
        \mu_{i,n_i}^{(l)} := \int_{[-1,1]^D}  \, x_i^{n_i} \, \mathrm{d} \mu_i^{(l)} (x_i)
    \end{equation}
     and note that,
    \begin{equation}
         \sum_{l=1}^L \prod_{i=1}^D  \mu^{(l)}_{i,0} = \left [  \zeta \left ( \mu(\cdot) \right ) \right ]_0 =  \sum_{l=1}^L \prod_{i=1}^D  \int \,  \mathrm{d} \mu_i^{(l)} (x_i) = \mu\left ( [-1,1]^D \right )  = 1
    \end{equation}
    Thus, it suffices to shows that $\mathcal{M}_d(\mu^{(l)}_i)$ and $\mathcal{M}_{d-1}(\mu^{(l)}_i ;\, (1-x_i^2))$ are positive semi-definite for each $i=1,...,D$ and $l=1,...,L$. To see how this is so, note that following our definition,
    \begin{align}
        f^T \, \mathcal{M}_d(\mu^{(l)}_i) \, f &= \int_{-1}^1 \, f^2(x) \, \mathrm{d}\mu^{(l)}_i(x_i) \geq 0\\
         g^T \, \mathcal{M}_d(\mu^{(l)}_i; (1-x_i^2)) \, g &= \int_{-1}^1 \, (1-x_i^2) \, g^2(x) \, \mathrm{d}\mu^{(l)}_i(x_i) \geq 0
    \end{align}
    for every $f\in\mathbb{P}_{D,d} $ and $g\in\mathbb{P}_{D,d-1} $, where positivity follows from the fact the integrands are non-negative and the measures are positive. Since this holds for every vector of coefficients $f$ and $g$, we conclude that all matrices are indeed positive semi-definite. This proves the claim.

    Regarding surjectivity, consider an element,
    \begin{equation}
        \mu :=  \sum_{l=1}^L \prod_{i=1}^D  \mu^{(l)}_{i,n_i}  \in \mathcal{F}_L.
    \end{equation}
    Following Proposition \ref{prop:measureextension}, for each vector of moments $\mu^{(l)}_{i}$ there exists of a regular Borel measure $\mu^{(l)}_i(\cdot)$ supported over $[-1,1]$ such that,
    \begin{equation}
        \int_{[-1,1]^D} \, x_i^{n_i} \, \mathrm{d} \mu_i^{(l)} (x_i) = \mu^{(l)}_{i,n_i}
    \end{equation}
    for every $\lvert n \rvert  \leq d$ that also satisfies: $\sum_{l=1}^L \prod_{i=1}^D \mu^{(l)}_{i,0} = 1 $. The element,
    \begin{equation}
        \mu(\cdot) := \sum_{l=1}^L \prod_{i=1}^D  \mu_i^{(l)} (\cdot) 
    \end{equation}
    therefore belongs to $\mathcal{S}_L$ and maps to $\mu$ through $\zeta(\cdot)$ as may be seen through substitution. Since this is true for every element of $\mathcal{F}_L$, this demonstrates surjectivity. Finally, continuity follows from the fact that,
    \begin{align}
       \left \lvert   \left [  \zeta \left ( \sum_{l=1}^L \prod_{i=1}^D  \mu_i^{(l)} (\cdot)   \right ) \right ]_n &-    \left [  \zeta \left ( \sum_{l=1}^L \prod_{i=1}^D  \nu_i^{(l)} (\cdot)   \right ) \right ]_n  \right \rvert  \\
       &= \left \lvert \int_{[-1,1]^D} \, x^n  \, \mathrm{d}  \left ( \sum_{l=1}^L \prod_{i=1}^D  \mu_i^{(l)} (\cdot) - \sum_{l=1}^L \prod_{i=1}^D  \nu_i^{(l)} (\cdot) \right )  \right \rvert \\
       &\leq \left  \lvert  \sum_{l=1}^L \prod_{i=1}^D  \mu_i^{(l)} (\cdot) - \sum_{l=1}^L \prod_{i=1}^D  \nu_i^{(l)} (\cdot) \right \rvert
    \end{align}
    by the triangle inequality, where $\lvert  \cdot \rvert$ indicates total variation (see, e.g., \cite{cohn2013measure}).
\end{proof}

