\begin{abstract}
Reconfigurable intelligent surfaces (RISs) are a promising technology for enhancing cellular network performance and yielding additional value to network operators. 
This paper proposes a techno-economic analysis of RIS-assisted cellular networks to guide operators in deciding between deploying additional RISs or base stations (BS).
We assume a relative cost model that considers the total cost of ownership (TCO) of deploying additional nodes, either BSs or RISs. 
We assume a return on investment (RoI) that is proportional to the system's spectral efficiency. 
The latter is evaluated based on a stochastic geometry model that gives an integral formula for the ergodic rate in cellular networks equipped with RISs. 
The marginal RoI for any investment strategy is determined by the partial derivative of this integral expression with respect to node densities.
We investigate two case studies: throughput enhancement and coverage hole mitigation. These examples demonstrate how operators could determine the optimal investment strategy in scenarios defined by the current densities of BSs and RISs, and their relative costs.
Numerical results illustrate the evolution of ergodic rates based on the proposed investment strategy, demonstrating the investment decision-making process while considering technological and economic factors.
This work quantitatively demonstrates that strategically investing in RISs can offer better system-level benefits than solely investing in BS densification. 
\end{abstract}
\begin{IEEEkeywords}
    Techno-economic analysis, stochastic geometry, sensitivity analysis, cellular network. 
\end{IEEEkeywords}


\input{introduction}


\section{Stochastic Geometry System Model}\label{section:system_model}


RISs can be deployed to address two primary use cases: enhancing network throughput and mitigating coverage holes. We present the stochastic geometry models of these two scenarios, accounting for the randomness of wireless network deployments.
We also model the TCO for deploying BSs or RISs per unit area.

\subsection{Thoughput Enhancement Model}
\begin{figure}
    \centering
    \includegraphics[width=0.7\linewidth]{figures/MCP_guard.pdf}
    \caption{Modeling RIS-assisted Cellular Networks with Mat\'ern Cluster Processes, with a guard zone to prevent the typical UE from being near BSs or RISs.}
    \vspace{-0.5cm}
    \label{fig:system_model}
\end{figure}
We investigate the throughput enhancement scenario by modeling BSs and RISs as Mat\'ern cluster processes (MCP), as illustrated in Fig.~\ref{fig:system_model}. 
The location of BSs is modeled as a homogeneous PPP
$\Phi_{\rm BS} \triangleq \sum_{i\in \mathcal I} \delta_{\mathbf{x}_i}$
with intensity $\lambda_{{\rm BS}}$, where $\delta$ denotes the Dirac delta function, modeling the mother process of the MCP.  
Here, $\mathcal{I}$ is the index set of BSs.
Each RIS is assumed to be associated with a serving BS and the placement of RISs is modeled as the daughter processes of the MCP
$\Phi_{\rm RIS} = \cup_{i\in \mathcal{I}} \phi_i$, where 
$\phi_i$ denotes the RIS cluster of BS $i$.
By definition, $\phi_i= \sum_{j \in \mathcal{J}_i} \delta_{\mathbf{y}_{i,j}}$, 
where $\mathcal{J}_i$ is the index set of RISs of cluster $i$, is a PPP with intensity $\lambda_{{\rm RIS}}$,
with support on the ring  $\mathbb{D}_{\mathbf{x}_i}(R_{\rm in}, R_{\rm out})$ of
center $\mathbf{x}_i$, inner radius $R_{\rm in}$ and outer radius $R_{\rm out}$.
In addition, the UE locations are modeled as a homogeneous PPP $\Phi_{{\rm UE}}$ with intensity
$\lambda_{{\rm UE}}$, which is independent of $\Phi_{\rm BS}$ and $\Phi_{\rm RIS}$. 
We consider a guard zone to exclude UEs near BSs from throughput enhancement evaluation, as strong signals experienced by these UEs reduce the need for RIS configuration and overhead. 
Therefore, we only consider UEs beyond a certain distance $R_c$ to be jointly served by the BS and RISs in this cell, as indicated by the gray contour in Fig.~\ref{fig:system_model}. 
The typical UE in $\Phi_{{\rm UE}}$, marked as the filled red circle, is located at the origin $o$ and is served by its closest BS and the associated RIS cluster that is specifically indexed by $o$.
The probability distribution function (PDF) of the distance from the serving BS to the typical UE is $f(r)=2\pi \lambda_{{\rm BS}}re^{- \lambda_{{\rm BS}} \pi r^2}$\cite{andrews2011tractable}\cite{baccelli2020random}, with $r \triangleq ||\mathbf{x}_o||$.

\subsection{Coverage Hole Mitigation Model}
\begin{figure}
    \centering
    \includegraphics[width=0.7\linewidth]{figures/UE_centered_model.pdf}
    \caption{RISs are deployed to assist UEs in coverage holes}
    \label{fig:coverage_hole_model}
    \vspace{-0.5cm}
\end{figure}

To investigate coverage hole mitigation, we consider a scenario where a UE located at the center of a coverage hole experiences signal attenuation on the direct link.
We consider a cluster of RISs $\mathcal{J}_{o}$ is deployed in a ring around this hole, as shown in Fig.~\ref{fig:coverage_hole_model}. 
To model the effect of blockage on signal attenuation, we assume the direct link from the BS to the UE is penalized by a constant attenuation coefficient $K$. 
To model the distance between the coverage hole and the associated BS, we remark that the spatial distribution of BSs will impact the proximity of an arbitrary location to its closest BS~\cite{chiu2013stochastic}. 
For the two-dimensional PPP-modeled BSs, the expected value of this distance is inversely proportional to the square root of  $\lambda_{\rm BS}$. 
In this work, we consider an average scenario where the centers of both the coverage hole and the RIS ring are located at a distance $r_{\rm H}$ from its associated BS, which is a function of the BS density, given by 
\vspace{-0.1cm}
\begin{equation}\label{eq:cell_center}
	r_{\rm H} = \frac{C_{\rm H}}{\sqrt{\lambda_{\rm BS}}},
    \vspace{-0.1cm}
\end{equation}
where $C_{\rm H}$ is a constant, whose value is selected in the simulation section ensuring that the coverage hole and the cluster of RISs are with high probability within the cell.




Without loss of generality, we assume that the RISs can effectively serve their associated UEs\footnote{Models of reflective, refractive, or hybrid (reflective and refractive) RISs can be analyzed using the same method by changing the density of the corresponding RIS type.}.
In other words, each RIS is modeled as a point and is capable of reflecting signals in any direction according to a given RIS-UE association.
Note that both models contain the special case of the scenario without deploying RISs by setting $\lambda_{\rm RIS}=0$. 

\subsection{System Performance Analysis}

The channel from the BS to the UEs assisted by the RISs is time-dispersive. This is because RISs are spatially dispersed and the propagation distance of the direct and reflected paths are different.
It is shown in \cite{sun2023performance} that employing OFDM to mitigate the time-dispersion of
the channel caused by multipath reflections, the post-processed SINR is given by 
\begin{equation}\label{eq:SINR-def}
\text{SINR} = \frac{|\gamma_{D_o}|^2 + \sum_{j \in \mathcal{J}_o} | \gamma_{{R}_{o,j}}|^2 }{\sum_{i\in \mathcal{I}\setminus o}\big( |\gamma_{D_i}|^2 + \sum_{j \in \mathcal{J}_i} | \gamma_{{R}_{i,j}}|^2  \big) + \sigma^2},
\end{equation}
where $\sigma^2$ is the power of the additive Gaussian noise.
Here, $\gamma_{D_o}$ and $\gamma_{R_{o,j}}$ represent the received signal amplitude of the direct and reflected intended signals, respectively, while $\gamma_{D_i}$ and $\gamma_{{R}_{i,j}}$ represent the corresponding received signal amplitude of the direct and reflected interference, respectively.
Each signal amplitude is typically the product of a fading variable $\rho\in \mathbb{C}$, a transmission power $P_0$, and a pathloss function as the function of propagation distance. Specifically, the direct pathloss is given by $ \gamma_D = \rho \sqrt{g(d)P_0}$ for distance $d$ while the reflected pathloss is $ \gamma_R = \rho \sqrt{g(d_1)g(d_2)P_0}$, where the latter accounts for the two segments of the reflected path.  
% Here, $\rho\in \mathbb{C}$ represents the small-scale random fading, $g(d)$ denotes the path loss for distance $d$, and $P_0$ is the BS's transmission power. 
Below, we take $g(d) = \beta(d+1)^{-\alpha}$, where the path-loss exponent $\alpha>2$,
and where $\beta = \frac{c}{4\pi f_c}$ is the average power gain for reference distance of $1$m, $f_c$ is the carrier frequency, and $c$ denotes the speed of light. 

The direct links are assumed to experience a Rayleigh fading $\rho_{D}\in \mathbb{C}$. 
As for the reflected links, the fading experienced by one RIS element, denoted by 
$\zeta$, is computed as the product $\rho_{\rm BS-RIS}\cdot \rho_{\rm RIS-UE}$
of two small-scale fading coefficients. This is because each RIS element is modeled as a
lossless phase shifter that can scatter the absorbed energy with a proper phase
shift~\cite{wu2019intelligent, zeng2021reconfigurable}.
Both $\rho_{\rm BS-RIS}$ and $\rho_{\rm RIS-UE}$ are assumed to follow a Rician distribution due to line-of-sight channel conditions, as RISs are usually deployed in favorable locations.
The small-scale fading of a reflected beam, formed by phase alignment of $M$ elements of a RIS panel, can be approximated by a Gaussian distributed random variable. 
This approximation relies on the central limit theorem, since the reflected beam magnitude is the sum of fading amplitude from a large number of RIS elements, given by
$|\rho_R| = \sum_{m=1}^{M}|\zeta^{(m)}| \approx \mathcal{N}(M\mathbb{E}[|\zeta |], M \mathbb{V}[|\zeta|])$,  where $|\zeta^{(m)}|$ is the fading for the $m^{\rm th}$ element.
Consequently, the power of the fading of a reflected beam follows the non-central chi-square distribution, denoted by $ |\rho_R|^2 \sim \chi^2$.


\vspace{-0.1cm}
\subsection{Total Cost of Ownership}
Below, we abstract the TCO by two categories of costs for both BS and RIS, namely, the capital expenditure
(CAPEX) and the operational expenditure (OPEX), denoted by $C_{\rm BS}, C_{\rm RIS}$ and $O_{\rm BS}, O_{\rm RIS}$, respectively.

From the observation that RIS is cost-effective compared to BS, which employs RF-chains and amplifiers~\cite{liu2022path},
we assume that the total CAPEX are such that $C_{\text{BS}} > C_{\text{RIS}}$.
Leveraging the fact that a given RIS is expected to require less power and maintenance~\cite{wang2022reconfigurable}, we also
assume that the total OPEX satisfy $O_{\text{BS}} > O_{\text{RIS}}$. 
The TCO is $\bar{C}_{\text{BS}} = O_{\text{BS}} + C_{\text{BS}}$ for each BS and 
$\bar{C}_{\text{RIS}} = O_{\text{RIS}} + C_{\text{RIS}}$ for each RIS.
Next, we introduce the parameter defining the cost ratio $J=\bar{C}_{\text{BS}}/\bar{C}_{\text{RIS}}$,
which will be used in the techno-economic analysis. 

Note that the $\lambda_{\rm RIS}$ represents the density of RISs within each cluster, which is conditioned on the spatial distribution of BSs.
When evaluating an investment policy for performance enhancement, the cost of deploying additional network elements, whether BSs or RISs, depends on the total number of elements added to an area. 
To achieve a fair comparison of deployment costs, the area-dependent cost, $\Delta \bar{C}_{\rm RIS}$, for increasing the RIS density, $\Delta\lambda_{\rm RIS}$, should be normalized in terms of the total area allocated for RIS deployment, rather than in terms of the cluster area of each cell. 
The normalized cost is given by 
        \vspace{-0.1cm}
\begin{equation}\label{eq:cost_RIS}
	\Delta \bar{C}_{\rm RIS} \propto \bar{C}_{\rm RIS}  \lambda_{\rm BS}\mathcal{A} \Delta \lambda_{\rm RIS},
        \vspace{-0.1cm}
\end{equation}
where $\mathcal{A}$ denotes the area of a cluster ring and $\lambda_{\rm BS}\mathcal{A}$ represents the total area.
Furthermore, when each BS is assumed to associate with $\mathcal{A}  \lambda_{\rm RIS}$ RISs, increasing the BS density $ \Delta \lambda_{\rm BS}$ implies adding the associated RISs, resulting in the cost $ \Delta \bar{C}_{\rm BS}$ due to both BSs and RISs, given by
% Specifically, the area-dependent cost of increasing $\lambda_{\rm BS}$ is proportional to the change in density 
        \vspace{-0.1cm}
\begin{equation}\label{eq:cost_BS}
	\Delta \bar{C}_{\rm BS} = \bar{C}_{\text{BS}} \Delta \lambda_{\rm BS} + \bar{C}_{\text{RIS}} \mathcal{A} \lambda_{\rm RIS}\Delta \lambda_{\rm BS}. 
\end{equation}


\section{Sensitivity Analysis and Investment Strategy}\label{section:analysis}
In this section, we quantify the ergodic rate enhancement of the UE, located either in a throughput-enhanced area or at the center of a coverage hole, as a function of increasing either the BS density or the RIS density. 
In addition, we propose an incremental deployment strategy to assist network operators in making informed decisions about BS and RIS investments.

\subsection{Integral Expression for Mean Ergodic Rate}


Reflected interference from RISs in non-associated cells, denoted by $\sum_{j \in \mathcal{J}_i} | \gamma_{{R}_{i,j}}|^2$ for all $i\neq o$,  can be negligible under certain conditions. 
Specifically, when non-associated reflected beams from other cells are randomly directed and have a low probability of overlapping with the UE of interest, the impact of this interference is minimal, as shown in \cite{sun2023performance}. 
We will empirically verify this condition in the simulation section. 
Assuming this factor has negligible influence on investment decision-making, we will neglect it in our analysis.

A communication link is considered successfully covered when $\text{SINR}\geq T$, where $T$ is the coverage threshold.
By manipulating SINR in Eq.~\eqref{eq:SINR-def} with the coverage threshold $T$, we have
\vspace{-0.2cm}
\begin{equation}\label{eq:manipulated}
    \big|\gamma_{D_o}\big|^2 \geq T\Big(\sum_{i\in \mathcal{I}\setminus o}\big|\gamma_{D_i}\big|^2   + \sigma^2\Big) -  \sum_{j \in \mathcal{J}_o} \big| \gamma_{{R}_{o,j}}\big|^2,  
\vspace{-0.3cm}
\end{equation}
where $I=\sum_{i\in \mathcal{I}\setminus o}\big|\gamma_{D_i}\big|^2$ represents the power of the aggregated interference and $S_R=\sum_{j \in \mathcal{J}_o} \big| \gamma_{{R}_{o,j}}\big|^2$ the power of the reflected signals, respectively. 
Denote the right-hand side of Eq.~\eqref{eq:manipulated} by $\Upsilon\in\mathbb{R}$ as a function of the threshold $T$.
The Laplace transform of $\Upsilon$ can be expressed as the product of the Laplace transform of
the scaled interference power $I$, the noise power $\sigma^2$, and the reflected signals power $-S_R$,
since they are built from independent random point processes and random variables, given
by\footnote{We let $\mathcal{B}(s)$ denote bilateral Laplace transform
and $\mathcal{L}(s)$ denote unilateral Laplace transform.}
$
\mathcal{B}_{\Upsilon}(s) = \mathcal{B}_{I}(sT) \mathcal{B}_{\sigma^2}(sT)  \mathcal{B}_{-S_R}(s).$ 
Specifically, $\mathcal{B}_{I}(sT)$ is obtained from the probability generating
functional (PGFL) of the PPP, given by
        \vspace{-0.1cm}
\begin{equation}\label{eq:laplace_I}
\begin{aligned}
    \mathcal{B}_{I}(sT) =&  e^{ -2\pi \lambda_{\rm BS} \int_{r}^{\infty} x \big(1-\mathcal{L}_{|\rho_{D}|^2}(s T P_0 g(x))\big){\rm d}x}, 
\end{aligned}
\end{equation}
where the Laplace transform of the Rayleigh faded interfering signal is $\mathcal{L}_{|\rho_{D}|^2}\big(s T P_0 g(x)\big) = \frac{1}{1+s T P_0 g(x)}$. In addition, for the Gaussian noise, we have $\mathcal{B}_{\sigma^2}(sT) = e^{-sT\sigma^2}$.
Similarly, the Laplace transform for the reflected signals is built from the PPP
of the RIS cluster associated with the typical BS, given by
        \vspace{-0.1cm}
\begin{equation}\label{eq:laplace_SR}
    \mathcal{B}_{-S_R}(s) = e^{-\lambda_{\rm RIS} \int_{R_{\rm in}}^{R_{\rm out}} \int_0^{2\pi} y\big(1 - \mathcal{L}_{|\rho_R|^2}(-s P_0 G(r, y, \psi)  ) \big) {\rm d}\psi {\rm d}y }.
\end{equation}
Here, the pathloss of the reflected path is $G(r,y,\psi) = g(y)g(\sqrt{r^2+y^2-2ry\cos{\psi}})$,
where $ r= \|\mathbf{x}_o\|, y=\|\mathbf{y}\|$,  represent the scalar distances of the BS and RIS to the UE, respectively, and $\psi \in [0, 2\pi)$ is the angle between the two parts of the reflected link.
In addition, the Laplace transform of the fading power of the reflected beam $|\rho_R|^2 \sim \chi^2$ is
        \vspace{-0.1cm}
\begin{equation}\label{Laplace_transform_rho_R}
    \mathcal{L}_{|\rho_R|^2}(s) = \frac{ \exp\Big(\frac{-s(M\mathbb{E}[|\zeta |])^2}{1+2s M \mathbb{V}[|\zeta|]}\Big)}{(1+2sM \mathbb{V}[|\zeta|])^{1/2}},
        \vspace{-0.1cm}
\end{equation}
where $s > -\frac{1}{2 M \mathbb{V}[|\zeta|]}$ specifies the region of convergence of the Laplace transform expression.

We can now state the integral representation of the coverage probability \cite[Theorem~1]{sun2023performance}:
\begin{theorem}
The coverage probability for a typical UE located at a distance of $r$ to the associated BS is given by
    \vspace{-0.1cm}
    \begin{equation}\label{eq:cov_prob}
        \mathsf{P}_c(T|r) = \mathcal{B}_{\Upsilon^+}\bigg(\frac{1}{  P_0g(r)}\bigg), 
        \vspace{-0.1cm}
    \end{equation}
    where  $\mathcal{B}_{\Upsilon^+}(s)$ is given by the formula
        \vspace{-0.1cm}
    \begin{equation}\label{eq:theorem}
    \mathcal{B}_{\Upsilon^+}(s) = \frac{1}{2\pi \imath}\int_{-\infty}^{\infty} \Big(\mathcal{B}_{\Upsilon}(s-\imath u)- \mathcal{B}_{\Upsilon}(-\imath u) \Big)\frac{{\rm d} u}{u} +  \frac{1+\mathcal{B}_{\Upsilon}(s)}{2}. 
    \end{equation}
Here, $\int_{-\infty}^{\infty}\frac{{\rm d}u}{u}$ is understood in the sense of Cauchy principal-value, that is $ \int_{-\infty}^{\infty}= \lim_{\epsilon \downarrow 0^+}\int_{-\infty}^{-\epsilon}+  \int_{\epsilon}^{\infty}$. 
\end{theorem}
% {\color{blue} The key challenge is differentiating Eq.~\eqref{eq:theorem}, which involves a singularity $u=0$ and an infinite integration domain.}
Based on the Shannon rate formula and the coverage probability, the mean ergodic rate of a typical UE at a distance $r$ from the associated BS is given by an integral:
    \vspace{-0.1cm}
\begin{equation}\label{eq:ergo_rate_at_r}
    \tau(r) =  \int_{0}^{\infty} \mathcal{B}_{\Upsilon^+}\bigg(\frac{1}{P_0g(r)}\bigg)\frac{1}{1+t}\text{d}t. 
    \vspace{-0.1cm}
\end{equation}



\subsection{Sensitivity Analysis for Throughput Enhancement}
To quantify the throughput of RIS-assisted networks, we consider the mean ergodic rate of a UE located at the distance $r\in [R_c, \infty)$ from the BS, given by 
\begin{equation}\label{eq:ergo_rate}
    \tau= \int_{0}^{\infty} \int_{R_c}^{\infty}  \mathcal{B}_{\Upsilon^+}\bigg(\frac{1}{P_0g(r)}\bigg)\frac{1}{1+t} 2\pi \lambda_{\rm BS} r e^{-\pi r^2\lambda_{\rm BS}} \text{d}r \text{d}t, 
\end{equation}
with $\tau(r)$ given in Eq.~\eqref{eq:ergo_rate_at_r}.
In what follows, we assume that RoI is proportional to the mean ergodic rate and we represent the differential RoI by
$\frac{\partial \tau}{\partial \lambda_{\rm BS}}$
and $ \frac{\partial \tau}{\partial \lambda_{\rm RIS}}$.
We will then analyze the investment strategy in Subsection~\ref{subsec_strategy}.

We now derive the first-order derivatives of Eq.~\eqref{eq:ergo_rate} w.r.t. the density of BSs or RISs,
while keeping all other variables fixed, which is the basis for economic analysis.
Differentiating Eq.~\eqref{eq:ergo_rate} requires an interchange of the integration and differentiation operators. 
For this purpose, an appropriate extension of the Leibniz integral rule \cite{bogachev2007measure} is given in Appendix~\ref{sec:appendix}.
Applying the Leibniz integral rule, we get
\begin{equation}\label{eq:partial_lambda_BS}
\begin{aligned}
    \frac{\partial \tau}{\partial\lambda_{\rm BS}} = \int_{0}^{\infty} \int_{R_c}^{\infty}& \bigg( \frac{\partial \mathcal{B}_{\Upsilon^+}(s)}{\partial\lambda_{\rm BS}}  \lambda_{\rm BS}  + \mathcal{B}_{\Upsilon^+}(s) (1   - \pi r^2 \lambda_{\rm BS} ) \bigg)  \\
    &2\pi r e^{-\pi r^2\lambda_{\rm BS}}\frac{1}{t+1}\text{d}r\text{d}t.
\end{aligned}
\vspace{-0.1cm}
\end{equation}
Here, we determine $\frac{\partial \mathcal{B}_{\Upsilon^+}(s)}{\partial\lambda_{\rm BS}}$  through another application of the Leibniz integral rule to Eq.~\eqref{eq:theorem}, which also involves interchanging of integration and differentiation. 
While the Leibniz integral rule requires the function under the integral sign to be a continuous function, the singular integral in Eq.~\eqref{eq:theorem} has a singularity at zero and at limit points at infinity. 
The conditions of this interchange are verified in Appendix~\ref{sec:appendix}.
Subsequently, we have
\vspace{-0.1cm}
\begin{equation}\label{eq:first_order_derivative_BS}
\begin{aligned}
        &\frac{\partial \mathcal{B}_{\Upsilon^+}(s)}{\partial\lambda_{\rm BS}} = \\
        &\frac{1}{2\pi \imath}\int_{-\infty}^{\infty} \bigg(\frac{\partial\mathcal{B}_{\Upsilon}(s-\imath u)}{\partial\lambda_{\rm BS}}- \frac{\partial\mathcal{B}_{\Upsilon}(-\imath u)}{\partial\lambda_{\rm BS}} \bigg)\frac{{\rm d} u}{u}  
        + \frac{1}{2}\frac{\partial\mathcal{B}_{\Upsilon}(s)}{\partial\lambda_{\rm BS}},
\end{aligned}
\end{equation}
where the expression for the derivative of the Laplace transform $\mathcal{B}_{\Upsilon}(s)$ w.r.t. the BS density is given by
\begin{equation}\label{eq:partial_BS}
\begin{aligned}
    &\frac{\partial \mathcal{B}_{\Upsilon}(s) }{\partial\lambda_{\rm BS}} = -\mathcal{B}_{\Upsilon}(s) \cdot 2\pi \int_{r}^{\infty} x \Big(1-\mathcal{L}_{|\rho_{D}|^2}\big(s T P_0 g(x)\big)\Big){\rm d}x. 
\end{aligned}
\end{equation}

Similar to Eq.~\eqref{eq:partial_lambda_BS}, we can derive the following expression for the partial derivative of $\tau$ w.r.t. $\lambda_{\rm RIS}$, given by
\begin{equation}\label{eq:partial_lambda_RIS}
\begin{aligned}
    \frac{\partial \tau}{\partial\lambda_{\rm RIS}} = \int_{0}^{\infty} \int_{R_c}^{\infty} \bigg( \frac{\partial \mathcal{B}_{\Upsilon^+}(s)}{\partial\lambda_{\rm RIS}}   \bigg)  2\pi r\lambda_{\rm BS} e^{-\pi r^2\lambda_{\rm BS}}\frac{1}{t+1}\text{d}r\text{d}t,
\end{aligned}
\end{equation}
where $\frac{\partial \mathcal{B}_{\Upsilon^+}(s)}{\partial\lambda_{\rm RIS}}$ can be expressed following the steps in Eq.~\eqref{eq:first_order_derivative_BS} and Eq.~\eqref{eq:partial_BS}. 


\subsection{Sensitivity Analysis for Coverage Hole Mitigation}
To analyze the impact of RIS on coverage hole mitigation, we are interested in the performance in terms of the ergodic rate of the UE located in the center of the coverage hole. 
In this case, assuming a fixed BS-UE distance eliminates the need for integration over the distance $r$. Consequently, $\tau$ is given by Eq.~\eqref{eq:ergo_rate_at_r} instead of Eq.~\eqref{eq:ergo_rate}.
Moreover, the derivatives obtained in the previous subsection require further modifications.

Recall that we introduce a penalty factor of $K$ to account for the impact of blocked direct links. 
This penalty factor influences the argument of the Laplace transform to express the coverage probability in Eq.~\eqref{eq:cov_prob}, which is then modified to $\frac{1}{KP_0g(r_{\rm H})}$.
Furthermore, changing the BS density also varies the average distance $r_{\rm H}$ between coverage hole centers and their cell centers, as defined in Eq.~\eqref{eq:cell_center}.
% Note that the rate of change of the ergodic rate is represented by the derivative of the Laplace transform of $\Upsilon$, i.e., $\frac{\partial \mathcal{B}_{\Upsilon}(s)}{\partial \lambda_{\rm BS}}$. 
In the following, we need to consider two factors due to the dependence of $r_{\rm H}$ on $\lambda_{\rm BS}$. First, the non-associated BSs within a distance of $[r_{\rm H},\infty)$ that introduce interference are closer to the UE for larger values of $\lambda_{\rm BS}$.  Second, the argument $s=\frac{1}{KP_0g(r_{\rm H})}$ is a function of $r_{\rm H}$ and consequently depends on  $\lambda_{\rm BS}$. Let $f_s(r_{\rm H}) = \frac{1}{KP_0g(r_{\rm H})}$ be the function describing this dependence in the following. The changing rates of these two factors are given by 
\vspace{-0.1cm}
\begin{equation}\label{eq:additional_derivative}
	\frac{\partial r_{\rm H}}{\partial \lambda_{\rm BS}} = -\frac{C_{\rm H}}{2\sqrt{\lambda_{\rm BS}^3}}, ~\frac{\partial f_s(r_{\rm H})}{\partial \lambda_{\rm BS}} = -\frac{1}{KP_0g^2(r_{\rm H})}\frac{\partial g(r_{\rm H})}{\partial r_{\rm H}}\frac{\partial r_{\rm H}}{\partial \lambda_{\rm BS}}. 
\end{equation}
Recall that $\mathcal{B}_{\Upsilon}(s) = \mathcal{B}_{I}(sT)\mathcal{B}_{-S_R}(s)\mathcal{B}_{\sigma^2}(sT)$, we have 
\vspace{-0.1cm}
\begin{equation}\label{eq:products}
\begin{aligned}
\frac{\partial \mathcal{B}_{\Upsilon}(s)}{\partial \lambda_{\rm BS}} =& \frac{\partial \mathcal{B}_{I}(sT)}{\partial \lambda_{\rm BS}}   \mathcal{B}_{-S_R}(s) \mathcal{B}_{\sigma^2}(sT) + \frac{\partial \mathcal{B}_{-S_R}(s)}{\partial \lambda_{\rm BS}} \mathcal{B}_{I}(sT) \\&  \mathcal{B}_{\sigma^2}(sT) + \frac{\partial \mathcal{B}_{\sigma^2}(sT)}{\partial \lambda_{\rm BS}} \mathcal{B}_{I}(sT) \mathcal{B}_{-S_R}(s).  
\end{aligned}
\vspace{-0.13cm}
\end{equation}
We will discuss the derivatives in Eq.~\eqref{eq:products} separately. First, for the derivative related to the interference $I$, we have 
\vspace{-0.1cm}
\begin{equation}\label{eq:derivaive_I}
	\frac{\partial \mathcal{B}_{I}(sT)}{\partial \lambda_{\rm BS}} = \mathcal{B}_{I}(sT) \Big(\mathcal{D}_{\rm BS}(sT) + \lambda_{\rm BS} \frac{\partial \mathcal{D}_{\rm BS}(sT) }{\partial \lambda_{\rm BS}}\Big), 
\end{equation}
where $\mathcal{D}_{\rm BS}(sT)=-2\pi \int_{r_{\rm H}}^{\infty} \frac{xsTP_0g(x)}{1+sTP_0g(x)}{\rm d}x$ from Eq.~\eqref{eq:laplace_I}. 
In Eq.~\eqref{eq:derivaive_I}, the expressions of $\frac{\partial \mathcal{D}_{\rm BS}(sT) }{\partial \lambda_{\rm BS}}$ are different when differentiating $\mathcal{B}_{\Upsilon}(s-\imath u)$ and $\mathcal{B}_{\Upsilon}(-\imath u)$ in Eq.~\eqref{eq:theorem}, respectively, For the former, both $r_{\rm H}$ and $s$ are dependent on $\lambda_{\rm BS}$.  
To differentiate $\mathcal{D}_{\rm BS}(sT) $ w.r.t. $\lambda_{\rm BS}$, another application of the Leibniz rule is needed. 
The condition for this application is discussed in Appendix~\ref{app:leibniz_coverage_hole}.
As a result, $\frac{\partial \mathcal{D}_{\rm BS}(sT) }{\partial \lambda_{\rm BS}}$ is given by
\begin{equation}\label{partial_D_I}
\begin{aligned}
\frac{\partial \mathcal{D}_{\rm BS}(sT) }{\partial \lambda_{\rm BS}} = &2\pi \frac{r_{\rm H}sTP_0g(r_{\rm H})}{1+sTP_0g(r_{\rm H})}\frac{\partial r_{\rm H}}{\partial \lambda_{\rm BS}} \\& -\int_{r_{\rm H}}^{\infty} \frac{2\pi xTP_0g(x)}{\big(1+sTP_0g(x)\big)^2} \frac{\partial f_s(r_{\rm H})}{\partial \lambda_{\rm BS}}{\rm d}x,  
\end{aligned}
\end{equation}
where $\frac{\partial r_{\rm H}}{\partial \lambda_{\rm BS}}$ and $\frac{\partial f_s(r_{\rm H})}{\partial \lambda_{\rm BS}}$ are given in Eq.~\eqref{eq:additional_derivative}. 
For the latter, $\mathcal{B}_{\Upsilon}(-\imath u)$, where the argument $ -\imath u$ does not depend on $r_{\rm H}$, the derivative  $\frac{\partial \mathcal{D}_{\rm BS}(sT) }{\partial \lambda_{\rm BS}}$ only contains the first part of Eq.~\eqref{partial_D_I} since $\frac{\partial f_s(r_{\rm H})}{\partial \lambda_{\rm BS}}$ in the second term is equal to zero.

Next, we can express the derivative of $\mathcal{B}_{-S_R}(s)$ as
\begin{equation}\label{eq:Derivative_S_R_BS}
\begin{aligned}
\vspace{-0.3cm}
	&\frac{\partial \mathcal{B}_{-S_R}(s)}{\partial \lambda_{\rm BS}} = \mathcal{B}_{-S_R}(s)\lambda_{\rm RIS} \frac{\partial \mathcal{D}_{\rm RIS}(s)}{\partial \lambda_{\rm BS}},
\end{aligned}
\vspace{-0.14cm}
\end{equation} 
where we use $\mathcal{D}_{\rm RIS}(s)$ to abbreviate $$-\int_{0}^{2\pi}\int_{R_{\rm in}}^{R_{\rm out}} y\Big(1- \mathcal{L}_{|\rho_R|^2}\big(-s P_0 G(r_{\rm H}, y, \psi)\big)\Big) {\rm d}y {\rm d}\psi.$$
Note that $\frac{\partial \mathcal{D}_{\rm RIS}(s)}{\partial \lambda_{\rm BS}}$ necessitates the application of the Leibniz rule to interchange differentiation and integration, given by
\begin{equation}
\begin{aligned}
&-\frac{\partial}{\partial \lambda_{\rm BS}} \int_{0}^{2\pi}\int_{R_{\rm in}}^{R_{\rm out}} y\Big(1- \mathcal{L}_{|\rho_R|^2}\big(-s P_0 G(r_{\rm H}, y, \psi)\big)\Big) {\rm d}y {\rm d}\psi  \\
    &=\int_{0}^{2\pi}\int_{R_{\rm in}}^{R_{\rm out}} \bigg(y \frac{\partial\mathcal{L}_{|\rho_R|^2}\big(-s P_0 G(r_{\rm H}, y, \psi)\big)}{\partial \lambda_{\rm BS}}\bigg) {\rm d}y {\rm d}\psi , 
\end{aligned}
\end{equation}
where the condition is discussed in Appedix~\ref{app:leibniz_coverage_hole}. 
When differentiating $\mathcal{B}_{\Upsilon}(s-\imath u)$ and $\mathcal{B}_{\Upsilon}(-\imath u)$, 
note that in the former, both $G(r_{\rm H}, y, \psi)$ and $s$ are dependent on $r_{\rm H}$, whereas in the latter only $G(r_{\rm H}, y, \psi)$ depends on $r_{\rm H}$. It is important to express the derivatives accounting for these factors. 
For $\mathcal{B}_{\Upsilon}(s-\imath u)$, the derivative of Eq.~\eqref{Laplace_transform_rho_R} is 
\vspace{-0.1cm}
\begin{equation}\label{eq:derivative_S_R_additional}
\begin{aligned}
&\frac{\partial\mathcal{L}_{|\rho_R|^2}\big(-s P_0 G(r_{\rm H}, y, \psi)\big)}{\partial \lambda_{\rm BS}} =\\&
	\bigg(\frac{ M(\mathbb{E}[|\zeta|])^2/\mathbb{V}[|\zeta|]-2 s P_0M\mathbb{V}[|\zeta|]G(r_{\rm H},y,\psi)+1 }{(1-2 s P_0G(r_{\rm H},y,\psi)M\mathbb{V}[|\zeta|])^{5/2}}\bigg)
	\\
	& P_0M\mathbb{V}[|\zeta|]\exp{\bigg(\frac{ s P_0G(r_{\rm H},y,\psi)(M\mathbb{E}[|\zeta|])^2 }{1-2s P_0G(r,y,\psi)) M\mathbb{V}[|\zeta|] }\bigg)}\\&\bigg(s\frac{\partial	G(r_{\rm H},y,\psi)}{\partial \lambda_{\rm BS}}+G(r_{\rm H},y,\psi)\frac{\partial	f_s(r_{\rm H})}{\partial \lambda_{\rm BS}} \bigg),
\end{aligned}
\vspace{-0.1cm}
\end{equation}
where $\frac{\partial G(r_{\rm H},y,\psi)}{\partial \lambda_{\rm BS}} = \frac{\partial	G(r,y,\psi)}{\partial r_{\rm H}} \cdot  \frac{\partial	r_{\rm H}}{\partial \lambda_{\rm BS}}$, with $\frac{\partial r_{\rm H}}{\partial \lambda_{\rm BS}}$ and $\frac{\partial f_s(r_{\rm H})}{\partial \lambda_{\rm BS}}$ given in Eq.~\eqref{eq:additional_derivative}.  
For differentiating $\mathcal{B}_{\Upsilon}(-\imath u)$, where the argument $- \imath u$ does not depend on $r_{\rm H}$, the factor $G(r_{\rm H},y,\psi)\frac{\partial	f_s(r_{\rm H})}{\partial \lambda_{\rm BS}}$ in Eq.~\eqref{eq:derivative_S_R_additional} is zero. 
% this derivative is given by
% \begin{equation}\label{eq:derivative_S_R_additional_im}
% \begin{aligned}
% &\frac{\partial\mathcal{L}_{|\rho_R|^2}\big(-s P_0 G(r_{\rm H}, y, \psi)\big)}{\partial \lambda_{\rm BS}} = \\&\frac{s P_0 M_0\sigma_{\chi}^2 (M_0\mu_{\chi}^2/\sigma^2_{\chi}-2 s M_0\sigma_{\chi}^2 P_0G(r_{\rm H},y,\psi)+1)}{(1-2 s P_0G(r_{\rm H}, y,\psi)M_0\sigma_{\chi}^2)^{5/2}}  \\
% 	& \exp{\bigg(\frac{ s M_0^2\mu_{\chi}^2 P_0G(r_{\rm H}, y,\psi)}{1-2 M_0\sigma_{\chi}^2 s P_0G(r_{\rm H},y,\psi))}\bigg)} \frac{\partial	G(r_{\rm H}, y,\psi)}{\partial \lambda_{\rm BS}}, 
% \end{aligned}
% \end{equation}
% with $\frac{\partial G(r_{\rm H},y,\psi)}{\partial \lambda_{\rm BS}}$ defined above for Eq.~\eqref{eq:derivative_S_R_additional}.

Last, we express the derivative of $\mathcal{B}_{\sigma^2}(sT)$ as 
\begin{equation}
	\frac{\partial \mathcal{B}_{\sigma^2}(sT)}{\partial \lambda_{\rm BS}} = -T\sigma^2e^{-sT\sigma^2}\frac{\partial f_s(r_{\rm H})}{\partial \lambda_{\rm BS}},
\vspace{-0.2cm}
\end{equation}
where $\frac{\partial f_s(r_{\rm H})}{\partial \lambda_{\rm BS}}$ is given in Eq.~\eqref{eq:additional_derivative}. 

The above modifications are necessary for the derivative w.r.t. $\lambda_{\rm BS}$. However, for the derivative w.r.t. $\lambda_{\rm RIS}$, no modification is needed. This is because adding RISs does not change the underlying spatial deployment of the BSs, and the expression in Eq.~\eqref{eq:partial_lambda_RIS}, modified by removing the integration over the distribution of $r$, gives the derivative for this scenario.

