\subsection{Non-traditional methods of counting crossings}\label{sub:nontraditional}
\begin{toappendix}
  \onlyapx{\subsection{Non-traditional methods of counting crossings}}
\end{toappendix}

We now look at different problems which do not count the crossings simply ``one by one''.

\subparagraph{Edge crossing number.}  Perhaps the most natural problem that fits into this category is the edge crossing number.  The \emph{edge crossing number} of a graph $G$ is the minimum $\ell$ such that $G$ has a good drawing with at most $\ell$ edges incident to the crossings in the drawing.
Computing the edge crossing number is \NP-hard by Balko et al.~\cite{DBLP:conf/gd/BalkoHMOVW24}, and according to Schaefer~\cite[Section 3.2: Edge crossing number]{DBLP:journals/combinatorics/SchaeferDS21}, no \FPT\ algorithm parameterized by the solution size $\ell$ is known for it even in the plane.

\begin{proposition}\label{prop:edgecrossn}%\apxmark
Let $r\geq0$ be an integer and $\surf$ be a surface with $a$ components, genus~$g$, and $b$ boundary components. The problem to decide whether an input graph $G$ of size $n$ has edge crossing number at most $r$ in $\surf$ can be solved in time $2^{\poly(a+g+b+r)}\cdot n^2$.
\end{proposition}
\begin{proof}
  We define a suitable crossing-counting pair $(\kappa,\lambda)$ for this problem as follows. For a drawing $D$ in $\surf$, let $\kappa(D)$ be equal to the number $\ell$ of edges of $D$ carrying an intersection point if the total number of intersection points in $D$ is at most $\ell\choose2$, and let $\kappa(D)=\infty$ otherwise. We also set $\lambda(i)=4{i\choose2}$.
  It is again routine to check that $(\kappa,\lambda)$ fulfills all conditions of \Cref{def:crossing-counting-pair}, and that $\kappa(D)$ is computable for a given drawing $D$ in polynomial time.

  The last point is to verify that the edge crossing number of a graph $G$ indeed equals the minimum value $\ell$ of $\kappa(D)$ over all decent drawings $D$ of~$G$; it is well known, see, e.g., Schaefer~\cite{schaefer2017crossing}, that one can turn any good drawing $D$ into a good drawing $D'$ in which no two edges cross twice, without introducing new crossed edges, and so having at most $\ell\choose2$ crossings in $D'$ at the end.
  Hence, we get from \Cref{thm:main} an algorithm running in time $2^{\poly(a+g+b+r)}\cdot n^2$.
\end{proof}
One can naturally generalize the edge crossing number problem to a color-constrained variant, and solve it by a straightforward combination of the ideas in the proof of \Cref{prop:CCCN} and of the previous proof.

\subparagraph{Odd and pair crossing numbers.}
Other examples of applicability include the odd and pair crossing numbers. The \emph{pair crossing number} of a graph $G$ is the minimum $\ell$ such that there exists a good drawing of $G$ in which at most $\ell$ pairs of edges mutually cross. The \emph{odd crossing number} of $G$ is similarly defined as the minimum $\ell$ such that there exists a good drawing $D$ of $G$ satisfying the following; there are at most $\ell$ pairs of edges $\{e,f\}$ in $D$ such that $e$ and $f$ have an odd number of mutual crossings.
While the question whether the pair crossing number coincides with the traditional crossing number is one of the biggest open problems in crossing numbers, Pelsmajer, Schaefer, and \v{S}tefankovi\v{c}~\cite{DBLP:journals/dcg/PelsmajerSS08} proved that the odd crossing number can be lower than the traditional crossing number.

\FPT\ algorithms for the pair and odd crossing numbers parameterized by the solution value $r$ were given again by Pelsmajer, Schaefer, and \v{S}tefankovi\v{c}~\cite{DBLP:conf/gd/PelsmajerSS07a}, with an unspecified runtime dependence on~$r$; however, because these algorithms are based on an adaptation of Grohe's algorithm \cite{DBLP:journals/jcss/Grohe04}, they are quadratic in the size~$n$ of the input and the dependence on $r$ is at least an exponential tower of height four.  We improve over their algorithms by providing algorithms quadratic in $n$, too, but with a better dependence in the parameter~$r$:

\begin{proposition2rep}\label{prop:pair-odd-cr}\apxmark
Let $r\geq0$ be an integer, and let $\Pi\in\{$`pair', `odd'$\}$. The problems to decide whether an input graph $G$ of size $n$ has $\Pi$-crossing number at most~$r$ in the \emph{plane} can be solved in time $2^{2^{\ca O(r)}}\!\!\cdot n^2$.
\end{proposition2rep}
  The proof crucially builds on the following result by Pelsmajer et al.~\cite{DBLP:conf/gd/PelsmajerSS07a}: If $G$ is of pair (respectively, odd) crossing number $\ell$, then there exists a good drawing $D$ of $G$ achieving this optimum such that the number of crossings in $D$ is at most $\ell2^\ell$ (respectively,~$9^\ell$). 
\begin{proof}
 The approach is analogous to the proof of \Cref{prop:edgecrossn}, with the additional ingredient given by the bounds by  Pelsmajer et al.~\cite{DBLP:conf/gd/PelsmajerSS07a}.  We define the crossing-counting pair $(\kappa,\lambda)$ such that $\kappa(D)$ is equal to the $\Pi$-crossing number~$\ell$ of $D$, if $D$ is good and $D$ has at most $\max(\ell2^\ell,9^\ell)$ crossings in total, and $\kappa(D)=\infty$ otherwise. This can clearly be computed in polynomial time from given~$D$. We correspondingly set $\lambda(i)=4\max(i2^i,9^i)$, which together with $\kappa$ fulfills \Cref{def:crossing-counting-pair}, thanks to the bounds by  Pelsmajer et al.~\cite{DBLP:conf/gd/PelsmajerSS07a}.  Hence, an application of \Cref{thm:main} gives an algorithm running in time $2^{2^{\ca O(r)}}\!\!\cdot n^2$.
\end{proof}
  We remark that the same approach would extend to surfaces, assuming some bounds analogous to those given by Pelsmajer et al.~\cite{DBLP:conf/gd/PelsmajerSS07a}.

%%%%%%%%%%%%%%%%%%%%%
\subsection{Allowing edge removals and vertex splits before drawing}\label{sub:delete-split}
\begin{toappendix}
  \onlyapx{\subsection{Allowing edge removals and vertex splits before drawing}}
\end{toappendix}

Finally, we consider some crossing number variants that allow the input graph to be simplified before drawing.  The problems of this section reduce to the more complicated \MDCN{} problem.

\subparagraph{Skewness.}

The \emph{skewness} of a graph $G$ is the smallest number of edges whose removal from $G$ leaves a planar graph. The problem to decide whether the skewness of $G$ is at most $\ell$ is NP-complete~\cite{liu-deletion},~and a linear-time FPT algorithm with respect to $\ell$ in the planar case is sketched by Kawarabayashi and Reed~\cite[Conclusion]{DBLP:conf/stoc/KawarabayashiR07}.
We generalize the problem as follows.
\ProbIII{Color-Constrained $\surf$-Skewness with Crossings}%
{A colored graph~$G$ with colors in~$\{1,\ldots,c\}$, non-negative integers $q_1,\ldots,q_c$ and~$r$.}%
{Can we remove, for each $i=1,\ldots,c$, at most $q_i$ edges of color~$i$ from $G$, such that the resulting graph has crossing number at most $r$ in~$\surf$?}

\begin{proposition2rep}\label{prop:skewness}\apxmark
  Let $\surf$ be a surface with $a$ connected components, genus~$g$, and $b$ boundary components. The {\sc Color-Constrained $\surf$-Skewness with Crossings} problem for input graph $G$ of size $n$ and parameter $r$ can be solved in time $2^{\poly(a+g+b+q+r)}\cdot n^2$, where $q=\sum_iq_i$.
\end{proposition2rep}
\begin{proof}
  Without loss of generality, we assume that $c\leq q+1$, since the colors $i$ with $q_i=0$ can be merged into one. We simply define $\kappa(D)$ as the number of crossings in~$D$ if $D$ is a good drawing, and $\kappa(D)=\infty$ otherwise. We also let $\lambda(i)=4i$.
  Then, setting $p=0$, we apply \Cref{thm:mainmod} to get the desired algorithm.
\end{proof}

\subparagraph{Splitting number.}  The minimum integer $\ell$ such that a graph obtained from the given graph $G$ by $\ell$ successive vertex splits is embeddable in the surface $\surf$ is called the \emph{splitting number} of~$G$ in~$\surf$ \cite{splitsurf,hjr-sncg-85}. This problem is \NP-hard~\cite{DBLP:journals/dam/FariaFN01} already in the plane.
N{\"{o}}llenburg et al.~\cite{DBLP:conf/gd/NollenburgSTVWW22} proved that the property of having splitting number at most $\ell$ is minor-monotone in any fixed surface, and so {$\surf$-splitting number} has a nonuniform \FPT\ algorithm parameterized by $\ell$ using the theory of graph minors.  We generalize and improve the latter result to a uniform \FPT\ algorithm:
\begin{proposition2rep}\label{prop:splitting}\apxmark
Let $p,r\geq0$ be integers and $\surf$ be a surface with $a$ connected components, genus~$g$, and $b$ boundary components. The problem to decide whether an input graph $G$ of size $n$ has, after at most $p$ vertex splits, the crossing number at most $r$ in~$\surf$ can be solved in time $2^{\poly(a+g+b+p+r)}\cdot n^2$.
\end{proposition2rep}
\begin{proof}
  We use the same crossing-counting pair $(\kappa,\lambda)$ as in the proof of \Cref{prop:skewness}. Then, we set $q_1=\ldots=q_c=0$ and apply \Cref{thm:mainmod} to get the desired algorithm with respect to given~$p$ and~$r$.
\end{proof}

