\section{Proofs}\label{sec:proof}
\subsection{Proof of Theorem~\ref{thm:NuProperties}}

\begin{proof}
    Remember that $S$ is the support of $\mu$ and we define $\tilde{\mu}$, the modified version of $\mu$, in the following way: If $S$ attains a maximum $s_{\max}$, let $\tilde{S} = S\setminus \{s_{\max}\}$ otherwise let $\tilde{S} = S$, and for any measurable set $A\subseteq S$, let $\tilde{\mu}(A) = \mu(A\cap\tilde{S}\})/\mu(\tilde{S})$. In addition, for simplicity in notation, since $\var(\ee[\bone\{Y > t\}\mid\bbx]) = 0$ whenever $\var(\bone\{Y > t\}) = 0$ we define $\var(\ee[\bone\{Y > t\}\mid\bbx])/\var(\bone\{Y > t\})$ to be equal to 1.

    Assuming that $Y$ is not almost surely a constant guarantee that for almost all values of $t$ with respect to $\tilde{\mu}$, $\var(\bone\{Y > t\})$ is non-zero and hence $\nu(Y, \bbx)$ is well-defined. Note that by the law of total variance and non-negativity of variance, we have
    \[
    0\leq \var(\ee[\bone\{Y > t\}\mid \bbx]) \leq \var(\bone\{Y > t\}),
    \]
    which gives $\nu(Y, \bbx) \in [0, 1]$. 

    When $Y$ is independent of $\bbx$ for all $t\in\rr$ we have 
    \[
    \ee[\bone\{Y > t\}\mid \bbx] = \ee[\bone\{Y > t\}],
    \]
    therefore $\var(\ee[\bone\{Y > t\}\mid \bbx]) = 0$ which gives $\nu(Y, \bbx) = 0$. 

    For each $t$ let $G(t) := \pp(Y > t)$, and $G_\bbx(t) := \pp(Y > t\mid \bbx)$. Note that $\nu(Y, \bbx) = 0$ implies that there exists a Borel set $A\subseteq \rr$ such that $\tilde{\mu}(A) = 1$ and for any $t\in A$, $\var(G_\bbx(t)) = 0$. This implies that for $t\in A$, $G_\bbx(t) = G(t)$ almost surely with respect to $\tilde{\mu}$. We claim that $A = \rr$. 

    Take any $t\in\rr$. If $\tilde{\mu}(\{t\}) > 0$, then $t\in A$. So w.l.o.g assume that $\tilde{\mu}(\{t\}) = 0$. Note that this also implies $\mu(t) = 0$, unless $t = s_{\max}$. We also have $\var(G(s_{\max})) = \var(G_\bbx(s_{\max})) = 0$ which implies $s_{\max}\in A$. Therefore, for any other such $t$, $\mu(t) = 0$. This implies that $G$ is right-continuous at $t$.

    Suppose for all $s > t$ we have $G(s) < G(t)$. Then for each $s > t$, $\mu([t, s)) > 0$ and hence $A\cap[t, s)\neq \emptyset$. Therefore, there exists a sequence $r_n \in A$ such that $r_n \downarrow t$. Since $r_n\in A$, we have $G_\bbx(r_n) = G(r_n)$ almost surely for all $n$. Therefore with probability $1$ we have 
    \begin{eqnarray*}
        G_\bbx(t) \geq \lim_{n\rightarrow\infty} G_\bbx(r_n) = \lim_{n\rightarrow\infty} G(r_n) = G(t)
    \end{eqnarray*}
    because of the right-continuity of $G$. Note that $\ee[G_\bbx(t)] = G(t)$, hence this implies $G_\bbx(t) = G(t)$ almost surely and therefore $t\in A$. 

    Suppose there exist $s > t$ such that $G(s) = G(t)$. Take the largest such $s$, which exists because $G$ is left-continuous. If $s = \infty$, then $G(t) = G(s) = 0$. Since $\ee[G_\bbx(t)] = G(t) = 0$ this implies $G_\bbx(t) = G(t) = 0$ almost surely which implies $t\in A$. So assume $s < \infty$. Either $\mu(\{s\}) > 0$, which  implies $G_\bbx(s) = G(s)$ almost surely, or $\mu(\{s\}) = 0$ and $G(r) < G(s)$ for all $r > s$, which again implies $G_\bbx(s) = G(s)$ almost surely as in the previous paragraph. Therefore, in either case, with probability $1$, we have 
    \begin{eqnarray*}
        G_\bbx(t) \geq G_\bbx(s) = G(s) = G(t).
    \end{eqnarray*}
    Since $\ee[G_\bbx(t)] = G(t)$, this implies $G_\bbx(t) = G(t)$ almost surely. Therefore $t\in A$. This shows we can take $A$ as big as $\rr$. 

    Now, for an arbitrary Borel set $B\subseteq \rr$,
    \begin{eqnarray*}
        \pp(\{Y > t\}\cap\{\bbx\in B\}) &=& \ee[\ee[\bone\{Y > t\}\mid \bbx]\bone\{X\in B\}] \\
        &=& \ee[G_\bbx(t)\bone\{\bbx\in B\}] \\
        &=& \ee[G(t)\bone\{\bbx\in B\}] \\
        &=& G(t)\pp(\bbx\in B) \\
        &=& \pp(Y > t)\pp(\bbx\in B).
    \end{eqnarray*}
    This proves that $Y$ and $\bbx$ are independent.

    Assume there exists a measurable function $f:\rr^p\rightarrow\rr$ such that $Y = f(\bbx)$. This implies that for all $t\in\rr$, $\ee[\bone\{Y > t\}\mid \bbx] = \bone\{Y > t\}$ and therefore 
    \[
    \var(\ee[\bone\{Y > t\}\mid \bbx]) = \var(\bone\{Y > t\}).
    \]
    This gives $\nu(Y, \bbx) = 1$. On the other hand, assume $\nu(Y, \bbx) = 1$. This implies for almost all $t\in\rr$ w.r.t $\tilde{\mu}$ we have 
    \[
    \var(G_\bbx(t)) = \var(\bone\{Y > t\}).
    \]
    If $S$, the support of $\mu$ attains the minimum $s_{\max}$, then note that we also have
    \[
    \var(G_\bbx(s_{\max})) = \var(\bone\{Y > s_{\max}\}).
    \]
    This implies $\ee[\var(\bone\{Y > t\}\mid \bbx)] = \ee[G_\bbx(t)(1 - G_\bbx(t))] = 0$ for almost all $t$ with respect to $\mu$. Therefore, $G_\bbx(t)$ almost surely takes only the values of $0$ and $1$ with respect to $\mu$. Let $E$ ($\bbx$-measurable) the event that $G_\bbx(t) \in\{0, 1\}$ for almost all values of $t$ and note that $\pp(E) = 1$. Let $a_\bbx$ be the largest value such that $G_\bbx(a_\bbx) = 1$ and $b_\bbx$ be the smallest value such that $G_\bbx(b_\bbx) = 0$. Note that $a_\bbx\leq b_\bbx$. Suppose $\{a_\bbx < b_\bbx\}\cap E$ happens. This means that for all $t\in (a_\bbx, b_\bbx)$ we have $G_\bbx(t)\in (0, 1)$ therefore $\mu((a_\bbx, b_\bbx)) = 0$.
    Then we have $\pp(Y\in (a_\bbx, b_\bbx)\mid \bbx) = 0$ which implies event $\{a_\bbx < b_\bbx\}\cap E$ is of measure $0$ and hence $a_\bbx = b_\bbx$ almost surely. Then this gives us $Y = a_\bbx$ almost surely, which completes the proof. 
\end{proof}

\subsection{Proof of Theorem~\ref{thm:consistency}}
For more clarity in the notation of our proof, we rewrite the estimator $\nu_n$ in terms of the empirical cumulative function. Let 
\begin{eqnarray*}
    \mathcal{I}_i^j := [\min\{Y_i, Y_{N^{-j}(i)}\}, \max\{Y_i, Y_{N^{-j}(i)}\}].
\end{eqnarray*}
For each $j\in[n]$ and $t\in\rr$ let
\begin{eqnarray*}
    F_{n,j}(t) := (n - 1)^{-1}\sum_{k\neq j}\bone\{Y_k \leq t\}, \qquad F_{n}(t) := n^{-1}\sum_{k=1}^n\bone\{Y_k \leq t\}.
\end{eqnarray*}
Note that 
\begin{eqnarray*}
    R_j = n F_n(Y_j), \qquad F_{n,j}(Y_j) = \big(\frac{n}{n - 1}\big)F_n(Y_j) - \frac{1}{n-1} = \frac{R_j - 1}{n - 1}.
\end{eqnarray*}
Using these, we can rewrite $\nu_n(Y, \bbx)$ as
\begin{eqnarray*}
    \nu_n(Y, \bbx) = 1 - \frac{1}{2(n-1)(n - n_0)}\sum_{j=1}^n\sum_{i\neq j}\frac{\bone\{Y_j\in\mathcal{I}_i^j\}\bone\{F_n(Y_j)\neq 1, 1/n\}}{F_{n,j}(Y_j)(1 - F_{n,j}(Y_j))},
\end{eqnarray*}
where $n_0 = n_{\max} + c_{\min}$, with $n_{\max}$ and $c_{\min}$ defined as before: $n_{\max}$ number of $Y_j$'s that are equal to the maximum of $Y_i$'s and $c_{\min} = 1$ if $Y_j$'s minimum is unique and zero otherwise.  

\begin{proof}
Let 
\begin{align}
    Q_n &:= \frac{1}{2(n - 1)(n - n_0)}\sum_{j = 1}^n\sum_{i\neq j}\frac{\bone\{Y_j \in \mathcal{I}_i^j\}\bone\{F_{n}(Y_j)\neq 1, 1/n\}}{F_{n,j}(
    Y_j)(1 - F_{n,j}(Y_j))}, \label{eq:Qn}\\
    Q_n^\prime &:= \frac{1}{2(n - 1)(n - n_0)}\sum_{j = 1}^n\sum_{i\neq j}\frac{\bone\{Y_j \in \mathcal{I}_i^j\}\bone\{F_{n}(Y_j)\neq 1, 1/n\}}{F(
    Y_j)(1 - F(Y_j))}, \label{eq:Qpn}\\
    Q &:= \int\frac{\ee[F_\bbx(t)(1 - F_\bbx(t))]}{F(t)(1 - F(t))}d\tilde{\mu}(t). \label{eq:Q}
\end{align}

\begin{lmm}\label{lmm1} With $Q_n$ and $Q$ defined in \eqref{eq:Qn} and \eqref{eq:Q}
\begin{eqnarray*}
    \lim_{n\rightarrow\infty}\ee[Q_n] = Q.
\end{eqnarray*}
\end{lmm}
\begin{proof}
To prove the convergence of $\ee[Q_n]$ to $Q$, we divide the argument into two steps: first, we show that $\ee[\abs{Q_n - Q_n'}]$ converges to zero; second, we show that $\ee[Q_n']$ converges to $Q$.


\noindent\textbf{Step I.} In this step we show that $\ee[\abs{Q_n - Q_n^\prime}]$ converges to zero.
    \begin{eqnarray*}
        \lefteqn{\ee[\big(\frac{n - n_0}{n}\big)\abs{Q_n - Q_n^\prime}] }\\
        &\leq& \frac{1}{2}\ee[\frac{\ee[\bone\{Y_j\in\mathcal{I}_i^j\}\mid F_n(Y_j), F(Y_j)]\abs{F_{n,j}(Y_j) - F(Y_j)}\bone\{F_n(Y_j)\neq 1, n^{-1}\}}{\max\{F_{n,j}(Y_j)(1 - F_{n,j}(Y_j)), \frac{n-1}{n^2}\}F(Y_j)(1 - F(Y_j))}] \\
        &\leq & \ee[\frac{\abs{F_{n, j}(Y_j) - F(Y_j)}}{F(Y_j)(1 - F(Y_j))}].
    \end{eqnarray*}
    Note that
    \begin{eqnarray*}
        \ee[\frac{\abs{F_{n, j}(Y_j) - F(Y_j)}}{F(Y_j)(1 - F(Y_j))}] = \int_{t\in\rr}\frac{\ee[\abs{F_{n - 1}(t) - F(t)}]}{F(t)(1 - F(t))}d\mu(t).
    \end{eqnarray*}
    Using Theorem 1.2 of \cite{bartl2023variance}, there exists absolute constants $c_0$ and $c_1$ such that for every $\Delta \geq c_0\log\log m/m$ with probability at least $1 - \exp(-c_1\Delta m)$, for every $t$ such that $\Delta \leq F(t)(1 - F(t))$ we have 
    \begin{eqnarray*}
        \abs{F_m(t) - F(t)} \leq \sqrt{F(t)(1 - F(t))\Delta}.
    \end{eqnarray*}
Let $\delta = (1-\sqrt{1-4\Delta})/2$. Using this and symmetry, we have 
\begin{align*}
    &\int_{t\in\rr}\frac{\ee[\abs{F_{n - 1}(t) - F(t)}]}{F(t)(1 - F(t))}d\mu(t) \\
    &\leq 2 \int_{\delta \leq F(t)\leq 0.5}\frac{\ee[\abs{F_{n - 1}(t) - F(t)}]}{F(t)(1 - F(t))}d\mu(t) + 2\int_{F(t) < \delta}\frac{\ee[\abs{F_{n - 1}(t) - F(t)}]}{F(t)(1 - F(t))}d\mu(t) \\
    &\leq 2\int_{\delta \leq F(t)\leq 0.5}\frac{\sqrt{\Delta F(t)(1 - F(t))}(1 - 2\exp(-c_1(n-1)\Delta)) }{F(t)(1 - F(t))} d\mu(t) + \\
    &2\int_{\delta \leq F(t)\leq 0.5}\frac{2\exp(-c_1(n-1)\Delta)}{F(t)(1 - F(t))}d\mu(t) + 2\int_{F(t) < \delta}\frac{\ee[F_{n-1}(t)] + F(t)}{F(t)(1 - F(t))} d\mu(t) \\
    &\leq \pi\sqrt{\Delta} + 4\exp(-c_1(n-1)\Delta)\log\big(\frac{1 + \sqrt{1- 4\Delta}}{1 - \sqrt{1- 4\Delta}}\big). \numberthis \label{eqn:Delta}
\end{align*}
Now let $\Delta = c_1^{-1}\log(n)/(n - 1)$. Then, as $n$ goes to infinity, \eqref{eqn:Delta} goes to zero. Hence $\ee[\big(\frac{n - n_0}{n}\big)\abs{Q_n - Q_n^\prime}]$ converges to zero. Since $Y$ is not almost surely a constant, as $n$ grows to $\infty$, $(n - n_0)/n$ converges to constant $\mu(\tilde{S}) > 0$. For large enough $n$ we have $(n - n_0)/n > \mu(\tilde{S})/2$. Therefore, for large enough $n$ we have
\begin{eqnarray*}
    \ee[\abs{Q_n - Q_n^\prime}] \leq \frac{2}{\mu(\tilde{S})}\ee[\big(\frac{n - n_0}{n}\big)\abs{Q_n - Q_n^\prime}].
\end{eqnarray*}
Since the right-hand side of the above inequality converges to zero, we conclude that $\lim_{n\rightarrow\infty}\ee[\abs{Q_n - Q_n^\prime}] = 0$.


\noindent\textbf{Step II.} In this step we show that $\ee[Q_n^\prime]$ converges to $Q$.
\begin{eqnarray*}
    \ee[\big(\frac{n - n_0}{n}\big)Q_n^\prime] &=& \frac{1}{2}\ee[\frac{\bone\{Y_j\in\mathcal{I}_i^j\}\bone\{F_n(Y_j)\neq 1, 1/n\}}{F(Y_j)(1 - F(Y_j))}].
\end{eqnarray*}
First, let's study the case when $\mu$ is continuous. In this case, by conditioning on the value of $F_n(Y_j)$, we have 
\begin{eqnarray*}
    \lefteqn{\ee[\frac{\bone\{Y_j\in\mathcal{I}_i^j\}\bone\{F_n(Y_j)\neq 1, 1/n\}}{F(Y_j)(1 - F(Y_j))}]}\\
    &=& \frac{1}{n}\sum_{r = 1}^n \ee[\frac{\bone\{Y_j\in\mathcal{I}_i^j\}\bone\{F_n(Y_j)\neq 1, 1/n\}}{F(Y_j)(1 - F(Y_j))}\mid F_n(Y_j) = r/n] \\
    &=& \frac{1}{n}\sum_{r = 2}^{n-1} \ee[\frac{\ee[\bone\{Y_j\in\mathcal{I}_i^j\}\mid Y_j]}{F(Y_j)(1 - F(Y_j))}\mid F_n(Y_j) = r/n] \\
    &\leq& \frac{1}{n}\sum_{r = 2}^{n-1} \big(\frac{(r - 1)(n - r)}{(n - 1)(n - 2)}\big)\ee[\frac{1}{F(Y_j)(1 - F(Y_j))}\mid F_n(Y_j) = r/n]
\end{eqnarray*}
Given $F_n(Y_j) = r/n$, $F(Y_j)\sim\text{Beta}(r, n - r + 1)$, therefore this gives us
\begin{eqnarray*}
    \ee[\frac{\bone\{Y_j\in\mathcal{I}_i^j\}\bone\{F_n(Y_j)\neq 1, 1/n\}}{F(Y_j)(1 - F(Y_j))}] \leq 2,
\end{eqnarray*}
which means $\big(\frac{n - n_0}{n}\big)Q_n^\prime$ is uniformly integrable. If $\mu$ does not have a continuous density, showing uniform integrability of $\big(\frac{n - n_0}{n}\big)Q_n^\prime$ requires extra work. We divide the argument into the following four cases: (i) Support $\mu$ attains a minimum $s_{\min}$ and a maximum $s_{\max}$ which $\mu$ has point masses on; (ii) Support $\mu$ attains a maximum $s_{\max}$ which $\mu$ has a mass point on but support $\mu$ either does not attain a minimum or it does not have a mass point on its minimum; (iii) Support $\mu$ attains a minimum $s_{\min}$ which $\mu$ has a mass point on but support $\mu$ either does not attain a maximum or it does not have a mass point on its maximum; (iv) Support $\mu$ attains a minimum or maximum or does not have point masses on them. 

\noindent\textbf{Case (i).} There exists $\delta > 0$ such that $\mu(s_{\max}), \mu(s_{\min})\geq \delta$.
\begin{eqnarray*}
     \lefteqn{\ee[\frac{\bone\{Y_j\in\mathcal{I}_i^j\}\bone\{F_n(Y_j)\neq 1, 1/n\}}{F(Y_j)(1 - F(Y_j))}]}\\
     &=& \int_{S\setminus\{ s_{\max}\}}\frac{\ee[\bone\{Y_j\in\mathcal{I}_i^j\}\bone\{F_n(Y_j)\neq 1, 1/n\}\mid Y_j = t]}{F(t)(1 - F(t))}d\mu(t) \\
     &\leq & \frac{1 + \delta}{\delta(1 - \delta)}.
\end{eqnarray*}
\noindent\textbf{Case (ii).} There exists $\delta > 0$ such that $\mu(s_{\max})\geq \delta$ and $\mu(s_{\min}) = 0$ or $S$ does not have a minimum. 
\begin{eqnarray*}
     \lefteqn{\ee[\frac{\bone\{Y_j\in\mathcal{I}_i^j\}\bone\{F_n(Y_j)\neq 1, 1/n\}}{F(Y_j)(1 - F(Y_j))}]}\\
     &=& \int_{S\setminus\{s_{\max}\}}\frac{\ee[\bone\{Y_j\in\mathcal{I}_i^j\}\bone\{F_n(Y_j)\neq 1, 1/n\}\mid Y_j = t]}{F(t)(1 - F(t))}d\mu(t) \\
     &\leq & \int_{F(t) < (n-1)^{-1}}\frac{\ee[\bone\{F_n(Y_j)\neq 1, 1/n\}\mid Y_j = t]}{F(t)(1 - F(t))}d\mu(t) + \\
     && \int_{(n-1)^{-1} \leq F(t) < 1 - \delta }\frac{\ee[\bone\{Y_j\in\mathcal{I}_i^j\}\mid Y_j = t]}{F(t)(1 - F(t))}d\mu(t) \\
     &\leq & \int_0^{(n-1)^{-1}}\frac{1 - (1 - x)^{n - 1}}{x(1 - x)}dx + \int_{(n-1)^{-1}}^{1 - \delta}\frac{2x(1 - x)}{x(1 - x)}dx.
\end{eqnarray*}
For large $n$ we have
\begin{eqnarray*}
    \int_0^{(n - 1)^{-1}}\frac{1 - (1 - x)^{n - 1}}{x(1 - x)}dx & \lesssim& \int_0^{(n - 1)^{-1}}\frac{(n - 1)x}{x(1 - x)}dx \leq \frac{n-2}{n-1} \leq 2.
\end{eqnarray*}
Therefore 
\begin{eqnarray*}
    \ee[\frac{\bone\{Y_j\in\mathcal{I}_i^j\}\bone\{F_n(Y_j)\neq 1, 1/n\}}{F(Y_j)(1 - F(Y_j))}] \leq 4.
\end{eqnarray*}
\noindent\textbf{Case (iii).} There exists $\delta > 0$ such that $\mu(s_{\min})\geq \delta$ and $\mu(s_{\max}) = 0$ or $S$ does not have a maximum. Note that by symmetry, this is equivalent to the previous case.

\noindent\textbf{Case iv.} $\mu$ is not continuous but does not have point masses at minimum or maximum. Note that this is similar to case (ii). 
\begin{eqnarray*}
    \lefteqn{\ee[\frac{\bone\{Y_j\in\mathcal{I}_i^j\}\bone\{F_n(Y_j)\neq 1, 1/n\}}{F(Y_j)(1 - F(Y_j))}]}\\
    &\leq & \int_{\min\{F(t), 1-F(t)\}\leq (n-1)^{-1}}\frac{\ee[\bone\{F_n(Y_j)\neq 1, 1/n\}\mid Y_j = t]}{F(t)(1 - F(t))}d\mu(t) + \\
    && \int_{(n-1)^{-1} < F(t) < 1-(n-1)^{-1}}\frac{\ee[\bone\{Y_j\in\mathcal{I}_i^j\}\mid Y_j = t]}{F(t)(1 - F(t))}d\mu(t) \\
    &\leq & 6.
\end{eqnarray*}
Therefore $\big(\frac{n - n_0}{n}\big)Q_n^\prime$ is uniformly integrable. 



Note that by Lemma 11.3. in \cite{azadkia2021fast} $\bbx_{N^{-j}(i)}\rightarrow \bbx_i$ with probability one. Then, using Lemma 11.7. in \cite{azadkia2021fast} with probability one we have
\begin{align*}
    \ee[\bone\{Y_j\in\mathcal{I}_i^j\}\mid Y_j, \bbx_i, \bbx_{N^{-j}(i)}] - \ee[\bone\{Y_j\in\mathcal{I}_i^\prime\}\mid Y_j, \bbx_i] \rightarrow 0,
\end{align*}
where $\mathcal{I}_i^\prime = [\min\{Y_i, Y_i^\prime\}, \max\{Y_i, Y_i^\prime\}]$ in which $Y_i$ and $Y_i^\prime$ are i.i.d given $\bbx_i$. Also 
\begin{align*}
    \ee[\bone\{Y_j\in\mathcal{I}_i^\prime\}\mid Y_j] &= \ee[\ee[\bone\{Y_j\in\mathcal{I}_i^\prime\}\mid Y_j, \bbx_i]\mid Y_j] \\
    & \rightarrow 2\ee[F_{\bbx_i}(Y_j)(1 - F_{\bbx_i}(Y_j))\mid Y_j]. 
\end{align*}
Since $\bone\{F_n(Y_j)\neq 1, 1/n\}$ converges almost surely to $\bone\{Y_j\in\tilde{S}\}$, by the dominated convergence theorem, we have
\begin{align*}
\ee[\big(\frac{n - n_0}{n}\big)Q_n^\prime]\rightarrow\int_{\tilde{S}}\frac{\ee[F_\bbx(t)(1 -  F_\bbx(t))]}{F(t)(1 - F(t))}d\mu(t).
\end{align*}
Considering that $1-n_0/n$ converges almost surely to $\mu(\tilde{S})$ which is bounded away from zero, $(1 - \frac{n_0}{n})^{-1} - \mu(\tilde{S})^{-1}$ converges almost surely to zero. Finally the uniformly integrability of $\big(\frac{n - n_0}{n}\big)Q_n^\prime$ gives us
\begin{align*}
   \ee[Q_n^\prime] = \ee\bigg[\big(\frac{n}{n - n_0} - \frac{1}{\mu(\tilde{S})}\big)\big(\frac{n - n_0}{n}\big) Q_n^\prime\bigg] + \frac{1}{\mu(\tilde{S})} \ee\bigg[\big(\frac{n - n_0}{n}\big) Q_n^\prime\bigg].
\end{align*}
The first term on the right-hand side of the above equality converges to zero by the Vitali convergence theorem. Therefore 
\begin{eqnarray*}
    \lim_{n\rightarrow\infty}\ee[Q_n^\prime] = \frac{1}{\mu(\tilde{S})}\int_{\tilde{S}}\frac{\ee[F_\bbx(t)(1 -  F_\bbx(t))]}{F(t)(1 - F(t))}d\mu(t) = Q.
\end{eqnarray*}
Putting steps I and II together gives us $\lim_{n\rightarrow\infty}\ee[Q_n] = Q$.
\end{proof}


\begin{lmm}\label{lmm2}
    For $Q_n$ defined in ~\eqref{eq:Qn}, there are constants $C_1$ and $C_2$ such that 
    \begin{eqnarray*}
        \pp(\abs{Q_n - \ee[Q_n]}\geq t) \leq C_1e^{-C_2nt^2/\log^2 n}.
    \end{eqnarray*}
\end{lmm}
\begin{proof}
We apply the bounded difference inequality~\cite{mcdiarmid1989method} to establish concentration. To do so, we first derive an upper bound on the maximum change in $Q_n$ resulting from replacing a single observation $(\bbx_k, Y_k)$ with an alternative value $(\bbx_k^\prime, Y_k^\prime)$ for any $k \in [n]$. We decompose this change into two steps: first, replacing $(Y_k, \bbx_k)$ with $(Y_k^\prime, \bbx_k)$, and second, replacing $(Y_k^\prime, \bbx_k)$ with $(Y_k^\prime, \bbx_k^\prime)$.

Take an arbitrary $k\in[n]$. Let $Q_n^{k_Y}$ be defined similar to $Q_n$ but using sample $\{(Y_i, \bbx_i)\}_{i \neq k}\cup\{(Y_k^\prime, \bbx_k)\}$. We show that $\abs{Q_n - Q_n^{k_Y}} \leq C\log n/n$ for some constant $C$ that only depends on the dimension of $\bbx$.

First, observe that since $\bbx_k$ remains unchanged, the nearest neighbour indices are unaffected. We analyze the effect of modifying $Y_k$ under two distinct scenarios: (i) neither $Y_k$ nor $Y_k^\prime$ is the minimum or maximum among $\{Y_i\}_{i \ne k}$; (ii) at least one of $Y_k$ or $Y_k^\prime$ is the minimum or maximum relative to $\{Y_i\}_{i \ne k}$.


\noindent\textbf{Case (i). Neither $Y_k$ nor $Y_k^\prime$ attains the minimum or maximum value.} Note that in this case, for all indices $j \in [n]$, the indicator $\bone\{n^{-1} < F_n(Y_j) < 1\}$ remains unchanged, as replacing $Y_k$ with $Y_k^\prime$ does not alter the minimum or maximum of the $\{Y_i\}$. Consequently, $n_0$ also remains unchanged. Without loss of generality, we assume $Y_k < Y_k^\prime$. Then we have
\begin{align*}
    2(n-1)(n - n_0)Q_n &= \sum_{\substack{j: Y_j < Y_k \text{ or } Y_j > Y_k' \\ n^{-1} < F_n(j) < 1}} \sum_{\substack{i \neq j \\ i \neq k,\, N^{-j}(i) \neq k}} \frac{\bone\{Y_j \in \mathcal{I}_i^j\}}{F_{n,j}(Y_j)(1 - F_{n,j}(Y_j))} + \\
    &\quad \sum_{\substack{j: Y_j < Y_k \text{ or } Y_j > Y_k' \\ n^{-1} < F_n(j) < 1}} \sum_{\substack{i \neq j \\ i = k \text{ or } N^{-j}(i) = k}} \frac{\bone\{Y_j \in \mathcal{I}_i^j\}}{F_{n,j}(Y_j)(1 - F_{n,j}(Y_j))} + \\
    &\quad \sum_{\substack{j: Y_k \leq Y_j \leq Y_k' \\ n^{-1} < F_n(j) < 1}} \sum_{\substack{i \neq j \\ i \neq k,\, N^{-j}(i) \neq k}} \frac{\bone\{Y_j \in \mathcal{I}_i^j\}}{F_{n,j}(Y_j)(1 - F_{n,j}(Y_j))} + \\
    &\quad \sum_{\substack{j: Y_k \leq Y_j \leq Y_k' \\ n^{-1} < F_n(j) < 1}} \sum_{\substack{i \neq j \\ i = k \text{ or } N^{-j}(i) = k}} \frac{\bone\{Y_j \in \mathcal{I}_i^j\}}{F_{n,j}(Y_j)(1 - F_{n,j}(Y_j))} + \\
    &\quad \sum_{i \neq k} \frac{\bone\{Y_k \in \mathcal{I}_i^k\}}{F_{n,k}(Y_k)(1 - F_{n,k}(Y_k))} \\
    &= A_1 + A_2 + A_3 + A_4 + A_5.
\end{align*}
We denote the corresponding terms involving $Y_k^\prime$ by $A_i^{k_Y}$ for $i = 1, \ldots, 5$. Observe that for all $j$ such that $Y_j < Y_k$ or $Y_j > Y_k^\prime$, the empirical distribution values remain unchanged, i.e., $F_{n,j}(Y_j) = F_{n,j}^k(Y_j)$, where $F_{n,j}^k(Y_j)$ denotes the empirical distribution after replacing $Y_k$ with $Y_k^\prime$. Consequently, in the terms $A_1$ and $A_2$, all denominators remain unchanged after the modification. In contrast, for indices $j$ such that $Y_k \leq Y_j \leq Y_k^\prime$, the value of $F_{n,j}(Y_j)$ changes by exactly $(n - 1)^{-1}$.

We first focus on $A_1$ and $A_2$. Since changing $Y_k$ to $Y_k^\prime$ does not affect the denominators, it suffices to analyse the numerator term $\bone\{Y_j \in \mathcal{I}_i^j\}$. In the case of $A_1$, the intervals $\mathcal{I}_i^j$ remain unchanged under the replacement of $Y_k$ with $Y_k^\prime$, so $A_1$ is unaffected, i.e., $A_1 = A_1^{k_Y}$.  

For $A_2$, consider first the case where $Y_j < Y_k < Y_k^\prime$. For any $i$ such that $N^{-j}(i) = k$, the indicator $\bone\{Y_j \in \mathcal{I}_i^j\}$ remains unchanged when $Y_k$ is replaced by $Y_k^\prime$. A similar argument holds when $Y_k < Y_k^\prime < Y_j$.  

Finally, consider the case where $i = k$. Even in this situation, the indicator $\bone\{Y_j \in \mathcal{I}_k^j\}$ remains unchanged under the modification of $Y_k$, and thus $A_2 = A_2^{k_Y}$.

Now consider $A_3$. Note that all indicator terms $\bone\{Y_j \in \mathcal{I}_i^j\}$ remain unchanged when $Y_k$ is replaced by $Y_k^\prime$. Therefore, it suffices to bound the difference
\[
\left| \frac{1}{F_{n,j}(Y_j)(1 - F_{n,j}(Y_j))} - \frac{1}{F_{n,j}^k(Y_j)(1 - F_{n,j}^k(Y_j))} \right|
\]
for those indices $i$ such that $\bone\{Y_j \in \mathcal{I}_i^j\} = 1$. We first consider the case where there are no ties among the $Y_i$'s. In this setting, for each $j$, Lemma 11.4. in \cite{azadkia2021simple} implies that there are at most $nC(p)\min\{F_n(Y_j) - n^{-1}, 1 - F_n(Y_j)\}$ such indices $i$ for which $Y_j \in \mathcal{I}_i^j$. This gives us 
\allowdisplaybreaks
\begin{align*}
    \lefteqn{\abs{A_3 - A_3^{k_Y}} \leq \sum_{\substack{j: Y_k \leq Y_j \leq Y_k^\prime \\ n^{-1} < F_n(Y_j) < 1}} 
    n C(p)\min\{F_n(Y_j) - \frac{1}{n}, 1 - F_n(Y_j)\} \times} \\
    &\quad \abs{\frac{1}{F_{n,j}(Y_j)(1 - F_{n,j}(Y_j))} - \frac{1}{F_{n,j}^k(Y_j)(1 - F_{n,j}^k(Y_j))}} \\
    &= nC(p)\sum_{j = 3}^{n - 1}\min\left\{\frac{j-1}{n}, 1- \frac{j}{n}\right\}\left|\frac{1}{\left(\frac{j - 1}{n - 1}\right)\left(1 - \frac{j - 1}{n - 1}\right)} - \frac{1}{\left(\frac{j - 2}{n - 1}\right)\left(1 - \frac{j - 2}{n - 1}\right)}\right| \\
    &\leq 2nC(p)\Bigg(\sum_{j = 1}^{n/2 - 1} \left( \frac{1}{j} + \frac{1}{n - j} \right) 
    - n\sum_{i = n/2}^{n - 2}\frac{1}{i(i + 1)} \Bigg) \\
    &= O(n\log n).
\end{align*}
The case where ties exist among the $Y_i$'s is similar but requires additional care. Let $r_1 < \cdots < r_m$ denote the ordered sequence of distinct values taken by the empirical ranks of $Y_j$ for $j \in [n]$. Define $\ell_*$ as the smallest index $i \in [m]$ such that for every $j$ satisfying $Y_k \leq Y_j \leq Y_k^\prime$, we have $F_n(Y_j) \leq r_i$. Similarly, define $\ell^*$ as the largest index $i \in [m]$ such that for every such $j$, $F_n(Y_j) \geq r_i$.
Then
\begin{align*}
    \lefteqn{\abs{A_3 - A_3^{k_Y}} \leq C(p)(n-1)^2\times}\\
    & \sum_{i=\ell_*}^{\ell^*} (r_i - r_{i-1})\min\{(r_i - 1), (n - r_i)\}\left|\frac{1}{(r_i - 1)(n - r_i)} - \frac{1}{(r_i - 2)(n - r_i + 1)}\right|.
\end{align*}

For all indices $i$ such that $r_i \leq n/2$, replacing the corresponding $Y_j$ values with distinct (tie-free) values can only increase the difference $\abs{A_3 - A_3^{k_Y}}$. Therefore, it suffices to bound this difference in the case where $r_{\ell_*} \geq n/2$, since for all $r_i\leq n/2$ we can use the bound on this difference when there are no ties. In this case, we have
\begin{align*}
    \abs{A_3 - A_3^{k_Y}} \leq C(p)n^2\sum_{i={\ell_*}}^{\ell^*} (r_i - r_{i-1})\frac{\abs{2r_i - n - 2}}{(r_i - 1)(r_i - 2)(n - r_i + 1)}.
\end{align*}
Define
\[
g(r)=\frac{\abs{2r - n - 2}}{(r - 1)(r - 2)(n - r + 1)},
\qquad r \in \{1,\dots,n-1\}.
\]

For $r \ge n/2$, the function $g$ is U‑shaped and attains its minimum at
$\lceil n/2 + 1\rceil$.
Hence, for every index $i$ with $r_i \ge \lceil n/2 + 1\rceil$ we bound $g(r_i)$ above by
$g(r_{\ell^*})$.
Because $r_{\ell^*} < n$, we have
$n - r_{\ell^*} + 1 = O(n)$, which implies
\[
\abs{A_3 - A_3^{k_Y}} = O(n).
\]

Combining this bound with those obtained in the remaining cases yields the overall estimate
\[
\abs{A_3 - A_3^{k_Y}} = O(n\log n).
\]

For $A_4$, observe that for any fixed $j$ there are at most $C(p)$ indices $i$ such that either $i = k$ or $N^{-j}(i) = k$. Consequently,
\allowdisplaybreaks
\begin{align*}
    \abs{A_4 - A_4^{k_Y}} 
    &\leq \sum_{\substack{j: Y_k \leq Y_j \leq Y_k^\prime \\ n^{-1} < F_n(Y_j) < 1}} 
    C(p)\abs{\frac{1}{F_{n,j}(Y_j)(1 - F_{n,j}(Y_j))} 
    - \frac{1}{F_{n,j}^k(Y_j)(1 - F_{n,j}^k(Y_j))}}
\end{align*}
We first examine the case in which the $Y_j$ are all distinct. Then
\begin{align*}
    \abs{A_4 - A_4^{k_Y}} &\leq 2C(p)n^2\sum_{j = 2}^{n/2}
    \abs{\frac{1}{(j - 1)(n - j)} 
    - \frac{1}{(j - 2)(n - j + 1)}}  = O(n).
\end{align*}
When ties are present among the $Y_j$ values, we have
\begin{align*}
    \abs{A_4 - A_4^{k_Y}} &\leq C(p)n^2\sum_{i = \ell_*}^{\ell^*}
    (r_i - r_{i-1})\abs{\frac{1}{(r_i - 1)(n - r_i)} 
    - \frac{1}{(r_i - 2)(n - r_i + 1)}}  \\
    &= O(n).
\end{align*}
Finally, observe that 
\[
\abs{A_5 - A_5^{k_Y}} \le A_5 + A_5^{k_Y}.
\]
We therefore bound $A_5$ only, as the same argument applies verbatim to $A_5^{k_Y}$.  
Since there are at most 
$n C(p)\min\{F_n(Y_k),\,1 - F_n(Y_k)\}$ 
indices \(i\) for which \(\bone\{Y_k \in \mathcal{I}_i^k\}=1\), we have
\begin{eqnarray*}
    A_5 \leq \frac{n C(p)\min\{F_n(Y_k), 1 - F_n(Y_k)\}}{F_{n,k}(Y_k)(1 - F_{n,k}(Y_k))} = O(n).
\end{eqnarray*}
Consequently, provided that replacing $Y_k$ with $Y_k^\prime$ leaves the sample minimum and maximum unchanged, we obtain
\begin{eqnarray*}
    \abs{Q_n - Q_n^{k_Y}} = O(\frac{\log n}{n}).
\end{eqnarray*}

\noindent\textbf{Case (ii). $Y_k$ or $Y_k^\prime$ is minimum or maximum.} Without loss of generality, assume $Y_k < Y_k^\prime$. Then one of the following scenarios arises:

\noindent\textbf{(a)} \textit{Replacing $Y_k$ with $Y_k^\prime$ leaves both the sample minima and maxima unchanged:} $Y_k < Y_k^\prime \le Y_j$ for all $j \ne k$. Consequently, $Q_n = Q_n^{k_Y}$.

\noindent\textbf{(b)} \textit{Replacing $Y_k$ with $Y_k^\prime$ alters the set of minima but leaves the set of maxima unchanged:} 
we have $Y_k \le Y_j$ for every $j \ne k$, and there exists at least one index $j$ with $Y_j \ge Y_k^\prime$.  
If, for some such $j$, we have $n^{-1} < F_n(Y_j) < 1$ before the change and $F_n^{k}(Y_j)=n^{-1}$ afterwards, then the contribution of that $j$ to $\lvert Q_n - Q_n^{k_Y}\rvert$ is bounded by  
\[
\frac{C(p)}{2\,(n-2)\,(n - n_0 - 1)} \;=\; O\!\bigl(n^{-1}\bigr).
\]
For every other index $j$, the argument from case (i) applies.

\noindent\textbf{(c)} \textit{Replacing $Y_k$ with $Y_k^\prime$ changes both the sample minima and maxima:} 
indeed, $Y_k \le Y_j \le Y_k^\prime$ for every $j \ne k$.  
Assume there exist indices $j_1$ and $j_2$ such that 
\[
n^{-1} < F_n(Y_{j_1}) < 1,\quad F_n^{k}(Y_{j_1}) = n^{-1},\quad
F_n(Y_{j_2}) = 1,\quad n^{-1} < F_n^{k}(Y_{j_2}) < 1 .
\]
The combined contribution of these two indices to $\abs{Q_n - Q_n^{k_Y}}$ is bounded by
\[
\frac{C(p)}{(n-2)\,(n - n_0 - 1)} = O(n^{-1}).
\]
For all remaining indices $j$, the reasoning from case (i) applies unchanged.

\noindent\textbf{(d)} \textit{Replacing $Y_k$ with $Y_k^\prime$ leaves the set of sample minima unchanged but alters the set of sample maxima:}  
we have $Y_j \leq Y_k^\prime$ for every $j \ne k$, and there exists at least one index $j$ with $Y_j \leq Y_k$.  
If there is an index $j$ for which $F_n(Y_j)=1$ and $n^{-1} < F_n^{k}(Y_j) < 1$, the contribution of that $j$ to $\abs{Q_n - Q_n^{k_Y}}$ is bounded by
\[
\frac{C(p)}{2\,(n-2)\,(n - n_0 - 1)} = O(n^{-1}).
\]
For every other index $j$, the argument from case (i) applies.

\medskip
\noindent
Combining Cases (i)–(iv), we obtain
\[
\abs{Q_n - Q_n^{k_Y}} \leq \frac{C(p)\,\log n}{n},
\]
whenever $(Y_k,\bbx_k)$ is replaced by $(Y_k^\prime,\bbx_k)$.


We now analyse the change induced when replacing $(Y_k^\prime,\bbx_k)$ with $(Y_k^\prime,\bbx_k^\prime)$.  
Because the $Y_i$ values remain unchanged, both the denominators
$F_{n,j}(Y_j)\bigl(1 - F_{n,j}(Y_j)\bigr)$ and the index set
$\{j : n^{-1} < F_n(Y_j) < 1\}$ are unaffected.  
For notational convenience, therefore, we study the effect of changing
$(Y_k,\bbx_k)$ to $(Y_k,\bbx_k^\prime)$.

Let $Q_n^{k_\bx}$ denote the analogue of $Q_n$ computed from the sample in
which $\bbx_k$ is replaced by $\bbx_k^\prime$.
For each fixed $j$, modifying $\bbx_k$ can alter at most $C(p)$ of the
intervals $\mathcal{I}_i^j$.
Among those indices $i$ whose intervals change, only those for which
$\bone\{Y_j \in \mathcal{I}_i^j\}$ flip value matters—namely, the indices
where $Y_j \in \mathcal{I}_i^j$ under $\bbx_k$ but $Y_j \notin \mathcal{I}_i^j$ under $\bbx_k^\prime$, or vice versa.

Finally, if $Y_j$ has rank $r_i$, then at most $\min\{r_i - 1, n - r_i\}$ of the indicators $\bone\{Y_j \in \mathcal{I}_i^j\}$ equal $1$ under either
$\bbx_k$ or $\bbx_k^\prime$. Therefore
\begin{align*}
    \abs{Q_n - Q_n^{k_\bx}} &\leq \left(\frac{n - 1}{n - n_0}\right)\sum_{i = 1}^m (r_i - r_{i-1})\frac{\min\{C(p), r_i - 1, n - r_i\}}{(r_i - 1)(n - r_i)}\\
    &\leq C(p)\left(\frac{n - 1}{n - n_0}\right)\sum_{i = 1}^\ell \frac{(r_i - r_{i-1})}{(r_i - 1)(n - r_i)} \\
    & \leq \frac{C(p)\log n}{n}.
\end{align*}
Combining the bounds for $\abs{Q_n - Q_n^{k_Y}}$ and $\abs{Q_n - Q_n^{k_\bx}}$, we obtain that replacing $(Y_k,\bbx_k)$ with $(Y_k^\prime,\bbx_k^\prime)$ yields
\begin{eqnarray*}
    \abs{Q_n - Q_n^{k}} \leq \frac{C(p)\log n}{n}. 
\end{eqnarray*}
Applying McDiarmid's bounded‑difference inequality~\cite{mcdiarmid1989method} gives
\begin{eqnarray*}
    \pp(\abs{Q_n - \ee[Q_n]}\geq t) \leq 2\exp(-Cnt^2/\log^2 n)
\end{eqnarray*}
\end{proof}
Using Lemma~\ref{lmm2}, set $t_n = \sqrt{2}(\log n)^{3/2}/\sqrt{Cn}$. Then note that 
\begin{eqnarray*}
    \sum_{n = 1}^\infty\pp(\abs{Q_n - \ee[Q_n]}\geq t_n) \leq 2\sum_{i = 1}^n\frac{1}{n^2} < \infty.
\end{eqnarray*}
By the Borel–Cantelli lemma, it follows that $\abs{Q_n - \ee[Q_n]}$ converges to zero almost surely. This, combined with Lemma~\ref{lmm1}, establishes the almost sure convergence of $Q_n$ to $Q$.
\end{proof}

\subsection{Proof of Theorem~\ref{thm:rate}}
Throughout this section, we will assume that the assumptions (A1) and (A2) from Section \ref{sec:rate} hold. In the following, we restate Lemma 14.1~\cite{azadkia2021simple} and its proof for convenience. Let $\bbx_{n, 1}$ be the nearest neighbor of $\bbx_1$ among $\bbx_2, \ldots, \bbx_n$ (with ties broken at random). 

\begin{lmm}\label{lmm:nn}
    Under assumption \textnormal{(A2)}, there is some $C$ depending only on $K$ and $p$ such that

\begin{eqnarray*}
    \ee\left(\left\|\bbx_1-\bbx_{n, 1}\right\|\right) \leq \begin{cases}C n^{-1}(\log n)^2 & \text { if } p=1 \\ C n^{-1 / p}(\log n) & \text { if } p \geq 2\end{cases}
\end{eqnarray*}
\end{lmm}


\begin{proof}
    Throughout this proof, $C$ will denote any constant that depends only on $K$ and $p$. Take $\varepsilon \in(n^{-1 / p}, 1)$. Let $B$ be the ball of radius $K$ in $\rr^p$ centred at the origin. Partition $B$ into at most $C K^p \varepsilon^{-p}$ small sets of diameter $\leq \varepsilon$. Let $E$ be the small set containing $\bbx_1$. Then
\begin{align*}
    \pp(\left\|\bbx_1-\bbx_{n, 1}\right\| \geq \varepsilon) = \pp(\bbx_2 \notin E, \ldots, \bbx_n \notin E).
\end{align*}
Now note that
\begin{align*}
    \pp(\bbx_2 \notin E, \ldots, \bbx_n \notin E \mid \bbx_1)=(1-\pp(\bbx_2 \in E \mid \bbx_1))^{n-1}=(1-\lambda(E))^{n-1},
\end{align*}
where $\lambda$ is the law of $\bbx$. Let $A$ be the collection of all small sets with $\lambda$-mass less than $\delta$. Since there are at most $C K^p \varepsilon^{-p}$ small sets, we get
\begin{align*}
\ee\left[(1-\lambda(E))^{n-1}\right] \leq(1-\delta)^{n-1}+\pp\left(\bbx_1 \in A\right) \leq(1-\delta)^{n-1}+C K^p \varepsilon^{-p} \delta.
\end{align*}
This gives
\begin{align*}
\pp(\left\|\bbx_1-\bbx_{n, 1}\right\| \geq \varepsilon) \leq (1-\delta)^{n-1} + C K^p \varepsilon^{-p} \delta.
\end{align*}

Now choosing $\delta = n^{-1} \log n$, we get
\begin{align*}
\pp(\left\|\bbx_1-\bbx_{n, 1}\right\| \geq \varepsilon) \leq \frac{1}{n} + \frac{C K^p\log n}{n \varepsilon^p}.
\end{align*}
Thus,
\begin{align*}
\ee(\left\|\bbx_1-\bbx_{n, 1}\right\|) \leq & n^{-1 / p}+\int_{n^{-1 / p}}^{2K}\pp(\left\|\bbx_1 - \bbx_{n, 1}\right\| \geq \varepsilon) d \varepsilon \\
\leq & n^{-1 / p}+\frac{C K^p\log n}{n} \int_{n^{-1 / p}}^{2K} \varepsilon^{-p} d \varepsilon.
\end{align*}

Finally, the last term is bounded by $C K n^{-1}(\log n)^2$ when $p = 1$, and by $C K^p n^{-1/p} \log n$ when $p \ge 2$.

\end{proof}

\begin{lmm}\label{lmm:rate}
    Let $C$ and $\beta$ be as in assumption \textnormal{(A1)} and $K$ be as in assumption \textnormal{(A2)}. Then there are $K_1, K_2$ and $K_3$ depending only on $C$, $\beta, K$ and $p$ such that for any $t \geq 0$,

\begin{eqnarray*}
    \pp\left(\abs{\nu_n - \nu} \geq K_1 n^{-{1/p\vee 2}}(\log n)^{\bone\{p=1\}+1} + t\right) \leq K_2 e^{-K_3 n t^2/\log n}
\end{eqnarray*}
\end{lmm}
\begin{proof}
    Recall $Q_n^\prime$ defined in \eqref{eq:Qpn}. Let $\mathcal{F}_\bbx$ be the $\sigma$-algebra generate by $\bbx_1, \ldots, \bbx_n$. Since $F_n(Y_j) = 1/n$ implies $\bone\{Y_j\in\mathcal{I}_i^j\} = 0$, we have
    \begin{align*}
        \ee[\big(\frac{n - n_0}{n}\big)Q_n^\prime] &= \frac{1}{2}\ee[\frac{\bone\{Y_j\in\mathcal{I}_i^j\}\bone\{n^{-1} < F_n(Y_j) < 1\}}{F(Y_j)(1 - F(Y_j))}] \\
        &= \frac{1}{2}\ee\left[\ee[\frac{\bone\{Y_j\in\mathcal{I}_i^j\}\bone\{n^{-1} < F_n(Y_j) < 1\}}{F(Y_j)(1 - F(Y_j))}\mid Y_j, \mathcal{F}_\bbx]\right] \\
        &= \frac{1}{2}\ee\left[\frac{\ee[\bone\{Y_j\in\mathcal{I}_i^j\}\bone\{F_n(Y_j) < 1\}\mid Y_j, \mathcal{F}_\bbx]}{F(Y_j)(1 - F(Y_j))}\right].
    \end{align*}
    In addition, note that 
    \begin{align*}
        Q = \frac{1}{2\mu(\tilde{S})}\ee\left[\frac{\ee[\bone\{Y_j\in\mathcal{I}_i^\prime\}\bone\{F_n(Y_j) < 1\}\mid Y_j, \mathcal{F}_\bbx]}{F(Y_j)(1 - F(Y_j))}\right],
    \end{align*}
    where $\mathcal{I}_i^\prime = [\min\{Y_i, Y_i^\prime\}, \max\{Y_i, Y_i^\prime\}]$ such that $Y_i$ and $Y_i^\prime$ are i.i.d. given $\bbx_i$. Note that 
    \begin{align*}
        \ee[\bone\{Y_j\in\mathcal{I}_i^\prime\}\mid Y_j, \mathcal{F}_\bbx] =& 1 - F_{\bbx_i}^2(Y_j) - (1 - F_{\bbx_i}(Y_j))^2, \\
        \ee[\bone\{Y_j\in\mathcal{I}_i^j\}\mid Y_j, \mathcal{F}_\bbx] =& 1 - F_{\bbx_i}(Y_j)F_{\bbx_{N^{-j}(i)}}(Y_j) - (1 - F_{\bbx_i}(Y_j))(1 - F_{\bbx_{N^{-j}(i)}}(Y_j)).
    \end{align*}
    Assumption (A1) yields
    \begin{align*}
        \lefteqn{\abs{F_{\bbx_i}(Y_j) - F_{\bbx_{N^{-j}(i)}}(Y_j)} \leq }\\
        &\qquad\qquad C(1 + \|\bbx_{N^{-j}(i)}\|^\beta + \|\bbx_i\|^\beta)\|\bbx_{N^{-j}(i)} - \bbx_i\|\min\{F(Y_j), 1 - F(Y_j)\}.
    \end{align*}
    By assumption (A2) there exists $K$ such that $\|\bbx_i\|, \|\bbx_{N^{-j}(i)}\|\leq K$. This gives us 
    \begin{align*}
        \abs{\ee[\big(\frac{n - n_0}{n}\big)Q_n^\prime] - \mu(\tilde{S})Q} &= \left|\ee\left[\frac{\ee[(2F_{\bbx_i}(Y_j) - 1)(F_{\bbx_{N^{-j}(i)}} - F_{\bbx_i}(Y_j))\mid \mathcal{F}_\bbx, Y_j]}{F(Y_j)(1 - F(Y_j))}\right]\right| \\
        & \leq  C K^\beta \ee[\|\bbx_i - \bbx_{N^{-j}(i)}\|]. 
    \end{align*}
    Therefore by Lemma~\ref{lmm:nn} 
    \begin{eqnarray*}
    \abs{\ee[\frac{(1 - n_0/n)}{\mu(\tilde{S})}Q_n^\prime] - Q} \leq \begin{cases}C n^{-1}(\log n)^2 & \text { if } p=1 \\ C n^{-1 / p}(\log n) & \text { if } p \geq 2\end{cases}.
\end{eqnarray*}

\begin{align*}
   \abs{\ee[Q_n^\prime] - Q} &\leq \ee\bigg[\abs{1 - \frac{1 - n_0/n}{\mu(\tilde{S})}}\big(\frac{n - n_0}{n}\big) Q_n^\prime\bigg] +  \left|\ee\bigg[\frac{(1 - n_0/n)}{\mu(\tilde{S})} Q_n^\prime\bigg] - Q\right|.
\end{align*}
Note that the first term on the right-hand side is $O(n^{-1/2})$ since $\big(\frac{n - n_0}{n}\big) Q_n^\prime$ is uniformly integrable and $n_0/n$ converges at the rate of $1/\sqrt{n}$ to $\mu(\tilde{S})$. Following the proof of Theorem~\ref{thm:consistency}, with the choice of $\Delta = c_1^{-1}\log(n)/(n-1)$ in \eqref{eqn:Delta} we have
\begin{eqnarray*}
    \ee[\abs{Q_n - Q_n^\prime}] \leq C\sqrt{\frac{\log n}{n}}.
\end{eqnarray*}
Finally, using Lemma~\ref{lmm2} and noting that $\nu_n = 1 - Q_n$ and $\nu = 1 - Q$ finishes the proof.
\end{proof}
Lemma~\ref{lmm:rate} implies
\begin{eqnarray*}
    \abs{\nu_n - \nu} = \frac{(\log n)^{1 + \bone\{p = 1\}}}{n^{1/(p\vee 2)}},
\end{eqnarray*}
which gives the proof of Theorem~\ref{thm:rate}.

\subsection{Proof of Theorem~\ref{thm:FOCI}}
Let $j_1, j_2, \ldots, j_p$ be the complete ordering of all variables by FORD. Let $V_0 = \emptyset$, and for each $1\leq k \leq p$, let $V_k := \{j_1, \ldots, j_k\}$. For $k > p$, let $V_k := V_p$. Note that for each $k$, $j_k$ is the index $j\not\in V_{k - 1}$ that maximizes $\nu_n(Y, \bbx_{V_{k-1}}\cup\{j\})$. Let $K = \lfloor 4/\delta + 2\rfloor$. Let $E^\prime$ be the event that $\abs{\nu_n(Y, \bbx_{V_k}) - \nu(Y, \bbx_{V_k})} \leq \delta/8$ for all $1 \leq k \leq K$, and let $E$ be the event that $V_K$ is sufficient.

\begin{lmm}\label{lmm:Eprime}
    Suppose that $E^\prime$ has happened, and for some $1\leq k\leq K$
    \begin{eqnarray}\label{eq:Eprime}
        \nu_n(Y, \bbx_{V_k}) - \nu_n(Y, \bbx_{V_{k - 1}}) \leq \delta/2.
    \end{eqnarray}
    Then $V_{k - 1}$ is sufficient.
\end{lmm}
\begin{proof}
    Take any $k \leq K$ such that~\ref{eq:Eprime} holds. If $k > p$ there is nothing to prove. So let us assume that $k\leq p$. Since $E^\prime$ has happened, this implies that for any $j\not\in V_{k - 1}$,
    \begin{align*}
        \nu(Y, \bbx_{V_{k - 1}\cup\{j\}}) - \nu(Y, \bbx_{V_{k-1}}) \leq \nu_n(Y, \bbx_{V_k}) - \nu_n(Y, \bbx_{V_{k-1}}) + \frac{\delta}{4} \leq \frac{3\delta}{4}.
    \end{align*}
    Then note that by definition of $\delta$, $V_{k - 1}$ must be a sufficient set.
\end{proof}
\begin{lmm}\label{lmm:EprimeGivesE}
    The event $E^\prime$ implies $E$.
\end{lmm}
\begin{proof}
    Suppose $E^\prime$ has happened but there is no $k$ such that~\ref{eq:Eprime} is valid. Therefore for all $1\leq k\leq K$ we have 
    \begin{align*}
        \nu_n(Y, \bbx_{V_k}) - \nu_n(Y, \bbx_{V_{k - 1}}) > \delta/2.
    \end{align*}
    This implies that 
    \begin{align*}
        \nu(Y,\bbx_{V_k}) - \nu(Y,\bbx_{V_{k - 1}}) \geq \nu_n(Y, \bbx_{V_k}) - \nu_n(Y, \bbx_{V_{k - 1}}) - \frac{\delta}{4} \geq \frac{\delta}{4}.
    \end{align*}
    This gives
    \begin{align*}
        \nu(Y, \bbx_{V_K}) =& \sum_{k = 1}^K \nu(Y, \bbx_{V_k}) - \nu(Y, \bbx_{V_{k - 1}}) \\
        \geq & \frac{K\delta}{4} \geq \left(\frac{4}{\delta} + 2\right)\frac{\delta}{4} > 1.
    \end{align*}
    Note that this contradicts the fact that $\nu(Y, \bbx_{V_k})\in[0, 1]$. Therefore, this shows that~\ref{eq:Eprime} must hold for some $k \leq K$. Therefore, Lemma~\ref{lmm:Eprime} implies that $V_K$ is sufficient. 
\end{proof}

\begin{lmm}\label{lmm:rateEprime}
There are positive constants $L_1, L_2$ and $L_3$ depending only on $C, \beta, K$ and $\delta$ such that 
    \begin{align*}
        \pp(E^\prime) \geq 1 - L_1p^{L_2}\exp(-L_3n/\log n).
    \end{align*}
\end{lmm}
\begin{proof}
    By assumptions (A1$^\prime$) and (A2$^\prime$), and Lemma~\ref{lmm:rate}, there exists $L_1, L_2$ and $L_3$ such that for any $V$ of size at most $K$ and any $t\geq 0$,
    \begin{eqnarray*}
        \pp(\abs{\nu_n(Y, \bbx_V) - \nu(Y, \bbx_V)}\geq L_1n^{-1/K\vee 2}(\log n)^2 + t) \leq L_2\exp(-L_3 n t^2/\log n).
    \end{eqnarray*}
    Let the event on the left be $A_{V,t}$ and $A_t := \bigcup_{\abs{V}\leq K}A_{V,t}$. By union bound we have $\pp(A_t)\leq L_2 p^K\exp(-L_3nt^2/\log n)$. Choose $t = \delta/16$. If $n$ is large enough so that 
    \begin{align}\label{eq:largen}
        L_1n^{-1/K\vee 2}(\log n)^2 \leq \frac{\delta}{16},
    \end{align}
    then the above bound implies that 
    \begin{align}\label{eq:largen2}
        \pp(E^\prime) \geq 1 - L_2p^K\exp(-L_4 n/\log n).
    \end{align}
    Equivalently, one can write ~\ref{eq:largen} as $n \geq L_5$ for some large $L_5$. Then we choose $L_6\geq L_2$ such that for any $n < L_5$,
    \begin{eqnarray*}
        L_6p^K\exp(-L_3 n/\log n) \geq 1. 
    \end{eqnarray*}
    Therefore for $n < L_5$, we have the trivial bound $\pp(E^\prime)\geq 1 - L_6p^K\exp(-L_3 n)$. Combining this with~\ref{eq:largen2} finishes the proof.
\end{proof}
\begin{lmm}\label{lmm:EprimeSufficient}
Event $E^\prime$ implies that $\hat{V}$ is sufficient.
\end{lmm}
\begin{proof}
    Suppose that $E^\prime$ has happened. First, suppose that FORD has stopped at step $K$ or later. Then $V_K\subseteq \hat{V}$ and, therefore, Lemma~\ref{lmm:EprimeGivesE} implies that $E$ has also happened, and therefore $\hat{V}$ is sufficient. Next, suppose that FORD has stopped at step $k - 1 < K$. Then, by definition of the stopping rule, we have 
    \begin{align*}
        \nu_n(Y, \bbx_{V_k}) \leq \nu_n(Y, \bbx_{V_{k - 1}}),
    \end{align*}
    which implies~\ref{eq:Eprime}. Since $E^\prime$ has happened, Lemma~\ref{lmm:Eprime} implies that $\hat{V} = V_{k - 1}$ is sufficient.
\end{proof}
Theorem~\ref{thm:FOCI} is an immediate result of Lemma~\ref{lmm:EprimeSufficient} and \ref{lmm:rateEprime}.

\subsection{Proof of Theorem~\ref{thm:simpleConsistency}} 
\begin{proof}
    Using Lemma 9.3. in \cite{chatterjee2021new}, the proof closely mirrors that of Theorem~\ref{thm:consistency}, hence we omit it here. The only difference is that the constant  $C(p)$ can be bounded above by 3 throughout the argument.
