\subsection{Proof of Proposition~\ref{thm:nullSimpleAsymp}}
\begin{lmm}\label{lmm:NullSimpleMoments}
    Suppose that $X$ and $Y$ are independent and $Y$ is continuous. Then 
    \begin{align*}
        \ee[\nu_{n}^{\text{1-dim}}(Y, X)] = \frac{2}{n},
    \end{align*}
    and 
    \begin{align*}
        \lefteqn{\var(\nu_{n}^{\text{1-dim}}(Y, X)) = }\\
        & \frac{2}{n}\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\frac{1}{(k - 1)(n - \ell)} - \frac{1}{n} - \frac{2}{n(n - 1)}\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\frac{1}{k - 1} + o(\frac{1}{n}).
    \end{align*}
\end{lmm}
\begin{proof}
    When $Y\perp X$ then $(r_1, \ldots, r_n)$ is random uniform permutation of $1, \ldots, n$. In this case $\nu_{n}^{\text{1-dim}}(Y, X)$ can be written as 
\begin{align*}
    \nu_{n}^{\text{1-dim}}(Y, X) = 1 - \frac{1}{2}\sum_{i = 1}^{n - 1}\sum_{j = 2}^{n-1}\frac{\bone\{j\in \mathcal{K}_i\}}{(j - 1)(n - j)}
\end{align*}
Let's focus on 
\begin{align*}
    A := \sum_{\ell = 2}^{n-1}\sum_{i = 1}^{n - 1}\frac{\bone\{\ell\in\mathcal{K}_i\}}{(\ell - 1)(n - \ell)}.
\end{align*}
We first work out the mean and variance of $A$.
\begin{align*}
    \ee[A] =& (n - 1)\sum_{\ell = 2}^{n-1}\frac{2(\ell - 1)(n - \ell)}{n(n-1)(\ell - 1)(n - \ell)} = 2 - \frac{4}{n}.
\end{align*}
For variance, we first look at the second moment of $A$
\begin{align*}
    A^2 =& \sum_{\ell = 2}^{n - 1}\sum_{k = 2}^{n - 1}\sum_{i = 1}^{n - 1}\sum_{j = 1}^{n - 1}\frac{\bone\{\ell\in\mathcal{K}_i\}\bone\{k\in\mathcal{K}_j\}}{(\ell - 1)(n - \ell)(k - 1)(n - k)} \\
    =& \sum_{\ell = 2}^{n - 1}\sum_{i = 1}^{n - 1}\frac{\bone\{\ell\in\mathcal{K}_i\}}{(\ell - 1)^2(n - \ell)^2} + \\
    & 2\sum_{\ell = 2}^{n - 1}\sum_{i = 1}^{n - 2}\frac{\bone\{\ell\in\mathcal{K}_i\}\bone\{\ell\in\mathcal{K}_{i+1}\}}{(\ell - 1)^2(n - \ell)^2} +\\
    & 2\sum_{\ell = 2}^{n - 1}\sum_{i = 1}^{n - 3}\sum_{j = i+2}^{n - 1}\frac{\bone\{\ell\in\mathcal{K}_i\}\bone\{\ell\in\mathcal{K}_j\}}{(\ell - 1)^2(n - \ell)^2} + \\
    & 2\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\sum_{i = 1}^{n - 1}\frac{\bone\{\ell\in\mathcal{K}_i\}\bone\{k\in\mathcal{K}_i\}}{(\ell - 1)(n - \ell)(k - 1)(n - k)} + \\
    & 4\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\sum_{i = 1}^{n - 2}\frac{\bone\{\ell\in\mathcal{K}_i\}\bone\{k\in\mathcal{K}_{i+1}\}}{(\ell - 1)(n - \ell)(k - 1)(n - k)} + \\
    & 4\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\sum_{i = 1}^{n - 3}\sum_{j = i + 2}^{n - 1}\frac{\bone\{\ell\in\mathcal{K}_i\}\bone\{k\in\mathcal{K}_j\}}{(\ell - 1)(n - \ell)(k - 1)(n - k)} \\
    =& A_1 + A_2 + A_3 + A_4 + A_5 + A_6.
\end{align*}


Let $H_m = \sum_{j = 1}^m 1/j$. Then
\begin{align*}
    \ee[A_1] =& \frac{2}{n}\sum_{\ell = 2}^{n - 1}\frac{1}{(\ell - 1)(n - \ell)} = \frac{4H_{n - 2}}{n(n - 1)}.
\end{align*}

\begin{align*}
    \ee[A_2] =& \frac{2}{n(n - 1)}\sum_{\ell = 2}^{n - 1}\frac{(n - \ell - 1) + (n - \ell)(\ell - 1)(\ell - 2)}{(\ell - 1)(n - \ell)} = \frac{4(n - 3)}{n(n - 1)^2}H_{n - 2}.
\end{align*}

\begin{align*}
    \ee[A_3] =& \frac{4}{n(n - 1)}\sum_{\ell = 2}^{n - 1}\frac{(\ell - 2)(n - \ell - 1)}{(\ell - 1)(n - \ell)} \\
    =& \frac{4(n - 2)}{n(n - 1)}(1 - \frac{2H_{n - 2}}{n - 2} + \frac{2H_{n - 2}}{(n-1)(n - 2)}).
\end{align*}

\begin{align*}
    \ee[A_4] =& \frac{4}{n}\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\frac{1}{(n - \ell)(k - 1)}.
\end{align*}



\begin{align*}
    \ee[A_5] =& \frac{4}{n(n-1)}\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\frac{(n - \ell) + (k - \ell - 3) + (k - 1)}{(n - \ell)(k - 1)} \\
    =& \frac{4}{n(n-1)}\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\frac{1}{k - 1} + \frac{2}{n - \ell} - \frac{\ell + 2}{(n - \ell)(k - 1)} \\
    =& \frac{4}{n(n-1)}\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\frac{2}{k - 1} + \frac{2}{n - \ell} - \frac{n + 2}{(n - \ell)(k - 1)} \\
    =& \frac{8}{n} + \frac{8}{n(n - 1)}\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\frac{1}{k - 1} - \frac{16}{n(n - 1)} - \frac{8H_{n - 2}}{n(n - 1)^2} \\
    & - \frac{4}{n}\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\frac{1}{(k - 1)(n - \ell)} - \frac{16}{n(n - 1)}\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\frac{1}{(k - 1)(n - \ell)}.
\end{align*}

\begin{align*}
    \ee[A_6] =& \frac{8}{n(n - 1)}\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\frac{(n - \ell)(k - 1) - 3(k - 1) - (n - \ell) + \ell + 2 + (k-2)}{(n - \ell)(k - 1)} \\
    =& \frac{8}{n(n - 1)}\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1} 1 - \frac{2}{n - \ell} - \frac{2}{k - 1} + \frac{n+1}{(n - \ell)(k - 1)}\\
    =& 4 - \frac{32}{n} + \frac{16H_{n-2}}{n(n - 1)} + \frac{24}{n(n - 1)} - \frac{16}{n(n - 1)}\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\frac{1}{k - 1} +\\
    &\qquad\frac{8(n + 1)}{n(n - 1)}\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\frac{1}{(k - 1)(n - \ell)}.
\end{align*}
Putting these together, we have 
\begin{align*}
    \var(A) = \frac{8}{n}\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\frac{1}{(k - 1)(n - \ell)} - \frac{8}{n(n - 1)}\sum_{\ell = 2}^{n - 2}\sum_{k = \ell + 1}^{n - 1}\frac{1}{k - 1} - \frac{4}{n} + o(\frac{1}{n^2}).
\end{align*}
Then note that $\ee[\nu_{n}^{\text{1-dim}}(Y, X)] = 1 - \ee[A]/2 = 2/n$, and $\var(\nu_{n}^{\text{1-dim}}(Y, X)) = \var(A)/4$. This finishes the proof.  
\end{proof}

