int main() {
  using namespace trivis;
  geom::PolyMap environment; // TODO: Fill the environment.
  Trivis vis{std::move(environment)}; // Construct the visibility object.
  geom::FPoint q{0.0, 0.0}; // TODO: Fill the query point q.
  std::optional<double> d = 10.0; // TODO: Set the visibility range d.
  // Locate the query point q:
  std::optional<Trivis::PointLocationResult> pl = vis.LocatePoint(q);
  if (!pl.has_value()) return EXIT_FAILURE; // q is outside the environment.
  // Compute the d-visibility region from q:
  AbstractVisibilityRegion abs = vis.VisibilityRegion(q, pl.value(), d);
  // Note: abs is an intermediate representation w/o computed intersections.
  RadialVisibilityRegion reg = vis.ToRadialVisibilityRegion(abs);
  if (d.has_value()) reg.IntersectWithCircleCenteredAtSeed(d);
  // Optional post-processing:
  if (d.has_value()) reg.SampleArcEdges(M_PI / 180.0);
  geom::FPolygon poly_approx = reg.ToPolygon();
