\section{Appendix on relative adjunctions}
\label{appendix:left_relative_adjunction}

We recall here for the reader's convenience the elementary notion of (right/left)-relative adjunction.

\begin{definition}[Left-relative adjunction {\cite[5.1]{Arkor2024formal}}]
  \label{def:left_relative_adjunction}
      Consider an arrangement of categories and functors as follows:
      \[\xymatrix{
      & \D \ar[dr]^-R \ar@{}[d]|(.6){\dashv} & \\
      \C \ar[ur]^-L\ar[rr]_-J && \X
      }\]
      In this situation, we say that \emph{$L$ is the $J$-relative left adjoint to $R$}, written $L\dashv_J R$ and indicated in the above diagram with a central `\,$\dashv$\,', if there is a bijection
      \[\D(L(x),y)\cong \X(J(x),R(y))\]
      natural in both arguments $x : \C , y : \D$.
\end{definition}
One obtains the standard definition of adjunction when $\X=\C$, $J = \id_\C$.
In the case of posets, the above natural adjoint simply becomes a bi-implication of conditions.

\section{Uniqueness for polarized exponentials}

\label{appendix:uniqueness_polarized_implication}

\begin{theorem}[Uniqueness for polarized exponentials]
We show the uniqueness of the polarized exponentials using the no-dinatural-variance property. Suppose we had another polarized exponential operation ${-{\Rightarrow'}-}$ with the same universal property; we show that $(\psi \Rightarrow' \varphi) \Leftrightarrow (\psi \Rightarrow \varphi)$ for the most general case of $\psi,\varphi$. The following derivation shows one direction, the other is identical by simply swapping the two operations.

\vspace{1em}
\hspace{1.2em}\centerline{$
  \begin{prooftree}
    \infer[no rule]0{\hspace{-6em}[\takespace[r]{\Theta,N,P'}{N,N'} \mid \Delta \mid \takespace[r]{\Gamma,P,N'}{P,P'}]\ \psi \prop}
    \infer[no rule]1{\hspace{-6em}[\Theta,N,P' \mid \Delta \mid \Gamma,P,N']\ \varphi \prop}
    \infer1[\Rulehyp]{[\Theta,P' \mid \Delta,N,P \mid \Gamma,N']\ \psi \Rightarrow \varphi & \le \psi \Rightarrow \varphi}
    \infer[double]1[\small $((\psi \Rightarrow \varphi) = \cP(\fulllift{\Delta,N,P})(\eps(\psi \Rightarrow \varphi)))$]{[\Theta,P' \mid \Delta,N,P \mid \Gamma,N']\ \cP(\fulllift{\Delta,N,P})(\eps(\psi \Rightarrow \varphi)) & \le \psi \Rightarrow \varphi}
    \infer[double]1[$(\psi = \cP(\fulllift{\Delta})(\eps(\psi)))$]{[\Theta,P' \mid \Delta,N,P \mid \Gamma,N']\ \cP(\lift{\Delta,N,P} \< (\pi_1 \mid {!_{\Delta,N,P}} \mid \pi_1))(\eps(\psi \Rightarrow \varphi)) & \le \cP(\fulllift{\Delta})(\eps(\psi)) \Rightarrow \cP(\fulllift{\Delta})(\eps(\varphi))}
    \infer[double]1{[\Theta,P' \mid \Delta,N,P \mid \Gamma,N']\ \cP(\lift{N,P} \< \lift{\Delta} \< (\pi_1 \mid {!_{\Delta,N,P}} \mid \pi_1))(\eps(\psi \Rightarrow \varphi)) & \le \cP(\fulllift{\Delta})(\eps(\psi)) \Rightarrow \cP(\fulllift{\Delta})(\eps(\varphi))}
    \infer[double]1{[\Theta,P' \mid \Delta,N,P \mid \Gamma,N']\ \cP(\lift{N,P})(\cP(\lift{\Delta} \< (\pi_1 \mid {!_{\Delta,N,P}} \mid \pi_1))(\eps(\psi \Rightarrow \varphi))) & \le \cP(\fulllift{\Delta})(\eps(\psi)) \Rightarrow \cP(\fulllift{\Delta})(\eps(\varphi))}
    \infer[double]1[\Ruleimpl]{[\Theta,P' \mid \Delta,N,P \mid \Gamma,N']\ \takespace[c]{\cP(\lift{N,P})(\cP(\lift{\Delta} \< (\pi_1 \mid {!_{\Delta,N,P}} \mid \pi_1))(\eps(\psi \Rightarrow \varphi)))}{\cdots} & \le \cP(\lift{N',P'})(\cP(\fulllift{\Delta})(\eps(\varphi)))}
    \infer[double]1[$(\Rightarrow')$]{[\Theta,P' \mid \Delta,N,P \mid \Gamma,N']\ \cP(\lift{N,P})(\cP(\lift{\Delta} \< (\pi_1 \mid {!_{\Delta,N,P}} \mid \pi_1))(\eps(\psi \Rightarrow \varphi))) & \le \cP(\fulllift{\Delta})(\eps(\psi)) \Rightarrow' \cP(\fulllift{\Delta})(\eps(\varphi))}
    \infer[double]1{[\Theta,P' \mid \Delta,N,P \mid \Gamma,N']\ \cP(\fulllift{\Delta,N,P})(\eps(\psi \Rightarrow \varphi)) & \le \cP(\fulllift{\Delta})(\eps(\psi)) \Rightarrow' \cP(\fulllift{\Delta})(\eps(\varphi))}
    \infer[double]1{[\Theta,P' \mid \Delta,N,P \mid \Gamma,N']\ \psi \Rightarrow \varphi & \le \psi \Rightarrow' \varphi}
  \end{prooftree}$}\vspace{1.5em}
Note that we applied $\Ruleimpl$ precisely when there was a dinatural lift operation (as in \Cref{thm:reindex_lift}) on the left and an exponential on the right, fulfilling the conditions prescribed by the categorical semantics for polarized exponentials. We omit the left hand side of the derivation in the case of implication since we immediately reverse it using the \emph{other} implication operator, which has the same formula on the left.
\end{theorem}

\section{Details for the equivalence in \Cref{thm:main_theorem}}

\label{appendix:details_bijection}

\begin{theorem}[Details for the equivalence in \Cref{thm:main_theorem}]
We describe more in detail the equivalence in \Cref{thm:main_theorem}. We again concentrate on the case of base predicates to highlight the need for the no-dinatural-variance condition, since the rest of the structure is defined in the only possible way. \\
\emph{(${{\Downarrow}\<{\Uparrow}\!=\!{\id}}$).} Suppose we are given a morphism of doctrines $(F,\alpha)$; recall that we construct the component on predicates for the corresponding morphism of theories as
\[
\begin{array}{l}
  b(\sigma) := \alpha(\sigma \type) \\
  p(\sigma) := (F(\mathsf{pos}(\sigma)),\top,F(\mathsf{neg}(\sigma)),\alpha(\sigma(\pi_1,\pi_1) \prop))
\end{array}
\] by applying it on the base predicate formula. In the other direction, we recall that in general the constructed doctrine morphism $(\sem{-},\sem{-}_\varphi)$ sends judgements $\sigma(s \mid t) \prop$ to \[\cP(\sem{s} \mid {!} \mid \sem{t})(\eps(p(\sigma \in \Sigma_P))),\]
where $p(\sigma) := p(\sigma)_4 \in \cP(p(\sigma)_1 \mid p(\sigma)_2 \mid p(\sigma)_3)$ for $p(\sigma)_1 := [\Theta'\mid\Delta'\mid\Gamma']$.
 To show that we end up with the original doctrine we need to show that $\alpha$ has the same action on predicates. In particular, it suffices to prove it for the base cases (since the rest of the structure is fixed and pertains to the structure of the doctrine).  Hence, we need to show
 \[
  \alpha(\sigma(s \mid t) \prop) = \cP(\sem{s} \mid {!} \mid \sem{t})(\eps(\alpha(\sigma(\pi_1,\pi_1) \prop)))
 \]
 However, we use the definition of \Cref{def:no_dinat_variance} to cancel out $\varepsilon$ and the full dinatural contraction $\cP(\fulllift{\Delta}) := \cP(\id_{\Theta \times \Delta} \mid {!_\Delta} \mid \id_{\Gamma \times \Delta})$ to obtain
 \[
 \begin{array}{ll}
  & \cP(\sem{s} \mid {!} \mid \sem{t})(\varepsilon(\alpha(\dots))) \\
  = & \cP(\sem{s} \< \id_{\sem{\mathsf{neg}(\sigma)}} \mid {!}  \< {!} \mid \sem{t} \< \id_{\sem{\mathsf{pos}(\sigma)}})(\varepsilon(\alpha(\dots))) \\
  = & \cP(\sem{s} \< \id_{\Theta'\times\Delta'} \mid {!}  \< {!} \mid \sem{t} \< \id_{\Gamma'\times\Delta'})(\varepsilon(\alpha(\dots))) \\
  = & \cP(\sem{s} \mid {!} \mid \sem{t})(\cP(\id_{\Theta'\times\Delta'} \mid {!} \mid \id_{\Gamma'\times\Delta'})(\varepsilon(\alpha(\dots)))) \\
  = & \cP(\sem{s} \mid {!} \mid \sem{t})(\alpha(\dots))
 \end{array}
 \]
 We implicitly used the isomorphisms between $\Theta' \times \Delta' =: \mathsf{neg}(p(\sigma)) := \sem{\mathsf{neg}(\sigma)}$ which corresponds exactly with the codomain of $s$. The final result \[
  \alpha(\sigma(s \mid t) \prop) = \cP(\sem{s} \mid {!} \mid \sem{t})(\alpha(\sigma(\pi_1,\pi_1) \prop))
 \]follows by the naturality of $\alpha$ which expresses well-behavedness with respect to context reindexing.
 %
\\ \emph{(${{\Uparrow}\<{\Downarrow}\!=\!{\id}}$).}
Suppose we are given a theory morphism $M$; we construct $\sem{-}$ and the syntactic doctrine by induction, defining $\sem{-}_\varphi$ on the base cases $\sigma(s \mid t) \prop$ to \[
\cP(\sem{s} \mid {!} \mid \sem{t})(\eps(p(\sigma \in \Sigma_P)))
\]
where $p(\sigma) \in \cP(p(\sigma)_1 \mid p(\sigma)_2 \mid p(\sigma)_3)$ and $\varepsilon(p(\sigma)) \in \cP(\sem{\mathsf{pos}(\sigma)}, \top, \sem{\mathsf{neg}(\sigma)}) \iso \cP(p(\sigma)_1 \times p(\sigma)_2, \top, p(\sigma_3) \times p(\sigma)_2)$.
We now give a theory morphism from the doctrine just constructed, which in general recall that it is given by
\[
p'(\sigma) := (F(\mathsf{pos}(\sigma)),\top,F(\mathsf{neg}(\sigma)),\alpha(\sigma(\pi_1,\pi_1) \prop))
\]
In our case $\alpha$ is $\sem{-}_{\varphi}$, hence
\[
\begin{array}{l}
p'(\sigma) := (\sem{\mathsf{pos}(\sigma)},\top,\sem{\mathsf{neg}(\sigma)}, \\
\takespace{p'(\sigma) := a aaaaaaaaaaaaaaaaaaaaaaaaaa}{\cP(\sem{\pi_1} \mid {!} \mid \sem{\pi_1})(\eps(p(\sigma \in \Sigma_P)))}
\end{array}
\]
where $\sem{\pi_1} : \sem{\mathsf{neg}(\sigma)} \times \top \> \sem{\mathsf{neg}(\sigma)}$ is essentially the identity. As in the previous proof, this reindexing has $\top$ as middle morphism, hence decomposes via $\cP(\fulllift{\Delta})$ and cancels out with $\varepsilon$, thus obtaining that $p'(\sigma) = p(\sigma)$.

\end{theorem}
