\section{Proof of Theorem~\ref{thm:fractional_regret}}
\label{sec:proof_regret}
%--------------------------------------------------

\begin{proof}
We prove the result for a general online convex optimization problem with $L$-Lipschitz convex cost functions $c_t: \mathcal F \to \mathbb R$ over the bounded convex set $\mathcal F \subset \mathbb R^N$ with $\radius(\mathcal F)= \min_{\f \in \mathcal F} \sup_{\hat{\f}\in \mathcal F} \lVert \f - \hat{\f} \rVert$.\footnote{
    We observe that here we refer to costs rather than rewards. 
} 

Let $\mathcal A$ denote the standard online gradient descent algorithm~\cite{zinkevich03}: it updates the state at each time slot as follows (this equation corresponds to \eqref{eqn:ogbnew_update}):
\begin{equation*}
\bm{f}_{t+1} = \Pi_\mathcal{F} \left( \bm{f}_{t} - \eta \nabla  c_t(\bm{f}_t) \right),
\end{equation*}
and experiences a cost $c_{t+1}(\bm{f}_{t+1})$.

The algorithm $\mathcal A$ enjoys the following (fracational) regret guarantees for $\f_0 = \arg\min_{\f\in \mathcal F} \sup_{\hat{\f}\in \mathcal F} \lVert \f - \hat{\f} \rVert$ and $\eta = \frac{\radius(\mathcal F)}{L \sqrt{T}}$:
\begin{align}
    R_T(\mathcal A) & \triangleq \sup_{c_0, c_1, \dots c_{T-1}}\left\{\sum_{t=0}^{T-1} c_t(\f_t) - \min_{\f \in \mathcal F} \sum_{t=0}^{T-1} c_t(\f)\right\}\\
    & \le \frac{\radius(\mathcal F)^2}{2 \eta} + \frac{\eta L^2 T}{2}\nonumber\\
    & = \radius(\mathcal F) L \sqrt{T}. 
\end{align}
Now, we consider an algorithm $\mathcal A'$ which selects the same state as $\mathcal A$ at time slots multiple of $B$ and freezes the state at other time slots, i.e., $\f'_t = \f_{\ell(t)}$, where $\ell(t)\triangleq\lfloor t/B \rfloor B$. 

We compute the difference in the total cost experienced by the algorithms $\mathcal A$ and $\mathcal A'$.

\begin{align}
    c_t(\f'_t) - c_t(\f_t) & = c_t(\f_{\ell(t)}) - c_t(\f_t)\\
    & \le L \lVert \f_t - \f_{\ell(t)} \rVert\\
    & \le L \sum_{\tau = 0}^{t - \ell(t)-1} \lVert \f_{\ell(t)+\tau+1} - \f_{\ell(t)+\tau} \rVert\\
    & \le L \sum_{\tau = 0}^{t - \ell(t)-1} \lVert  \Pi_\mathcal{F}\left(\f_{\ell(t)+\tau} - \eta \nabla c_{\ell(t)+\tau}\right) - \f_{\ell(t)+\tau} \rVert\\
    & \le L \sum_{\tau = 0}^{t - \ell(t)-1} \lVert  \f_{\ell(t)+\tau} - \eta \nabla c_{\ell(t)+\tau} - \f_{\ell(t)+\tau} \rVert\\
    & \le \eta L^2 (t- \ell(t)).
\end{align}
Summing over $T$ we obtain
\begin{align}
    \sum_{t=0}^{T-1} c_t(\f'_t) - c_t(\f_t) & \le \eta L^2 \left(\left\lfloor \frac{T-2}{B} \right\rfloor \frac{B(B-1)}{2} + \sum_{t=\ell(T-1)}^{T-1} (t- \ell(t))\right)\\
    & = \eta L^2 \left(\left\lfloor \frac{T-2}{B} \right\rfloor \frac{B(B-1)}{2} + \frac{(T-1- \ell(T-1))(T- \ell(T-1))}{2}\right)\\
    & \le \eta L^2 \left(\left\lfloor \frac{T-2}{B} \right\rfloor \frac{B(B-1)}{2} + \frac{(B-1)(T- \ell(T-1))}{2}\right)\\
    & \le \eta L^2 \frac{B-1}{2} \left(\left\lfloor \frac{T-1}{B} \right\rfloor B + T- \ell(T-1)\right)\\
    & \le \eta L^2 T \frac{B-1}{2}
\end{align}
Then algorithm $\mathcal A'$ enjoys the following regret bound for $\f_0 = \arg\min_{\f\in \mathcal F} \sup_{\hat{\f}\in \mathcal F} \lVert \f - \hat{\f} \rVert$ and $\eta = \frac{\radius(\mathcal F)}{L \sqrt{T B}}$:
\begin{align}
    R_T(\mathcal A') & \le \frac{\radius(\mathcal F)^2}{2 \eta} + \frac{\eta L^2 T}{2} + \eta L^2 T \frac{B-1}{2}\\
    & = \frac{\radius(\mathcal F)^2}{2 \eta} + \frac{\eta L^2 T B}{2}\\
    & = \radius(\mathcal F) L \sqrt{T B}. 
\end{align}

The result for the caching problem is obtained by considering that $\radius(\mathcal F) = \sqrt{C\left(1- \frac{C}{N}\right)}$ and $L=1$.


\end{proof}

