\section{Preliminaries}

Let $G$ be an unweighted graph where $V(G)$ is its vertex set.
We define $P = (p_1,\dots,p_n)$ and $Q = (q_1,\dots,q_m)$ as two paths in $G$. A path cannot visit a vertex twice. 
For integers $i, i' \in [n]$ with $i \leq i'$ we denote by $P[i: i']$ the subpath of $P$ from $p_i$ to $p_{i'}$. 
We define the discrete Fréchet distance $\frechet(P, Q)$ between $P$ and $Q$ as follows~\cite{DBLP:conf/compgeom/DriemelHR22}: 
A sequence $(a_i, b_i)_{i \in [k]}$ of pairs of indices is a \emph{monotone walk} if for all $i \in [k-1]$ we have $a_{i+1} \in \set{a_i, a_i+1}$ and $b_{i+1} \in \set{b_i, b_i + 1}$. Let $\mathbb{F}_{n, m}$ be the set of all monotone walks from $(1,1)$ to $(n,m)$. 

\newpage
\noindent
The cost of $F \in \mathbb{F}_{n, m}$ is the maximum of $\dist(p_i, q_j)$ over $(i,j) \in F$, where $\dist()$ denotes the length of the shortest path between vertices.  $\frechet(P, Q)$ is the minimum cost of a walk in $\mathbb{F}_{n, m}$.
\[
\frechet(P,Q) = \min_{F \in \mathbb{F}_{n, m}} \text{cost}(F) = \min_{F \in \mathbb{F}_{n, m}} \max_{(i,j) \in F} \dist(p_i, q_j).
\]

\subparagraph{Decision variant.}
We focus on the decision variant where the input includes some  $\Delta \geq 0$ and the goal is to output whether $\frechet(P, Q) \leq \Delta$. 
The \emph{$\Delta$-free space matrix} $M_\Delta$ is the $n$ by $m$ matrix where $M_\Delta[i, j]$ is $0$ if $\dist(p_i, q_j) \leq \Delta$ and $1$ otherwise.
We follow geometric convention, where $i$ denotes the column of $M_\Delta$ (column $i$ corresponds to some $p_i \in P$. Column entries with value $0$  correspond to $q_j \in Q$ with $\dist(p_i, q_j) \leq \Delta$).
Eiter and Mannila~\cite{eitermannila94} define a directed graph over $M_\Delta$ where there is an edge from $M_\Delta[a, b]$ to $M_\Delta[c, d]$ if and only if $c \in \{a, a+1 \}$, $d \in \{b,b+1 \}$ and $M_\Delta[a, b] = M_\Delta[c, d] = 0$. 
They prove that $\frechet(P, Q) \leq \Delta$ if and only if there exists a directed path from $(1, 1)$ to $(n, m)$ in this graph. 


\subparagraph{Orthogonal vectors.} Our conditional lower bound reduces from the Orthogonal Vector Hypothesis. The input consists of two ordered sets of $d$-dimensional Boolean vectors $U,W$ of sizes $|U| = n$ and $|W| = m$. We denote for $u \in U$ by $u_i \in \{0,1\}$ its $i$'th component. 
The \emph{OV problem} is to find out if some vector of $U$ is orthogonal to some vector of $W$.

\begin{definition}[Williams \cite{DBLP:journals/tcs/Williams05}] The orthogonal vector hypothesis (OVH) states that for all $\delta > 0$, there exists constants $\omega$ and $1 > \gamma > 0$ such that the OV problem for vectors of dimension $d = \omega \log n$ and $m = n^\gamma$ cannot be solved in $O((nm)^{1-\delta})$ time. 
\end{definition}

We consider each vector in $U$ (or $W$) as a string of $d$ bits. We denote by $\str(U)$ and $\str(W)$ the concatenation of all strings in $U$ and $W$, respectively. 
A \emph{substring} of some string $s_1 s_2 \, \dots \, s_k$ is the sequence $s_a s_{a+1} \, \dots \, s_{b-1} s_b$ for some $1 \leq a \leq b \leq k$.



\subparagraph{Regular tilings.}
A \emph{regular tiling} $T$ is an infinite plane graph where each face is a regular polygon and each face has the same degree. 
There exist exactly three regular tilings~\cite{grunbaum1987tilings}: the triangular, square, and hexagonal tiling (Figure~\ref{fig:tilingdef}). Without loss of generality, we assume that our tilings are axis-aligned. 
A face $F$ of $T$ is an open region bounded by the edges of $T$, we denote by $\overline F$ its closure.
The \emph{edge length} of $T$ is the length of any edge. A tiling is \emph{unit} if its edges have unit length.
A path in $T$ is a path in its corresponding graph.  
We always denote by $T$ a unit tiling where $(0, 0)$ is a vertex of $T$. 
%For any face $F$ of a tiling, we denote by $\partial{F} = \overline{F}-F$ its boundary.
For any pair of vertices $p, q$ of $T$, the term $\dist(p, q)$ denotes the distance in the graph $T$. We assume that we can compute $\dist(p, q)$ in constant time.
Our algorithm considers what we will call a \emph{super-tiling} of $T$ and a natural partition of the edges of $P$ and $Q$ into subpaths. 

\begin{definition}[Figure~\ref{fig:tilingdef} (b)]
    Given a regular tiling $T$ of the plane, 
    a \emph{super-tiling} $\T$ of $T$ is a regular tiling of the plane whose vertex set is a subset of the vertex set $V(T)$. 
    The \emph{boundary vertices} $B(\T)$ are the vertices of $T$ that lie on the boundary of some face of $\T$. 
    %We will write $B(\T)$ when $T$ is apparent from context. 
\end{definition}


