In the following, we show that the transformer $\tf$ faithfully simulates the Post machine $\pm$. Let $(\sigma_1,q_1),(\sigma_2,q_2),\cdots$ denote the execution log of $\pm$ running on $x\in\{0,1\}^n$, where $\sigma_i$ is the $i$-th element added to the queue and $q_i$ is the state when adding $\sigma_i$. Note that $(\sigma_i,q_i\rangle=\langle x_i,q_{start})$ for $i\leq n$, $(\sigma_i,q_i)=(\#,q_{start})$ for $n+1\leq i< s(n)$, and $\delta(\sigma_{i-s(n)+1},q_i)=(\sigma_{i+1},q_{i+1})$ for $i\geq s(n)$. 
Let $v_1, v_2, \dots$ denote the token sequence in the context of $\tf$ when it takes $v_1 = (x_1, q_{start}), \dots, v_n = (x_n, q_{start})$ as input.
 We show by induction that for each $i\geq 1$, we have $v_i=(\sigma_i,q_i)$.

\textbf{Base case: $i\leq n$}\quad This case is trivial. 

\textbf{Inductive case I: $n+1\leq i<s(n)$}\quad  In the self-attention layer, observing that $\vec{K}\cdot \vec{h}^0_i=(\vec{0}_{c+7},1)=1$ and 
\begin{flalign*}
\vec{Q}\cdot \vec{h}^0_j=\pos(i-j)=\begin{cases}
 \vec{0}_{c+8}, & \text{if } 1\leq j<i,\\
 (\vec{0}_{c+7},1), & \text{if } j=i,
 \end{cases}
\end{flalign*}
we have
\begin{align*}
\vec{s}_{i} = &\hardmax\left(\langle \vec{h}^0_{1}\cdot \vec{Q},\vec{h}^0_i\cdot \vec{K}\rangle,\cdots,\langle \vec{h}^0_i\cdot \vec{Q},\vec{h}^0_i\cdot \vec{K}\rangle\right)=(0,\cdots,0,1)\in\R^i
\end{align*}
and
\[
\vec{a}_{i}=\sum_{j=1}^{i} s_{i,j}\cdot \left(\vec{V}\cdot \vec{h}^0_j\right)=\sum_{j=1}^{i} s_{i,j}\cdot \left(\vec{0}_{c+4},\vec{h}^0_{j,2;4},h^0_{j:c+8}\right)=(\vec{0}_{c+4},\vec{h}_{i,2:4}^0,1).
\]
Then 
\[
\vec{h}_i^{0.5}=\vec{W}\cdot \vec{a}_i+\vec{b}+\vec{h}_i^0=\vec{a}_i+\vec{h}_i^0=(\vec{h}^0_{i,1:c+4},\vec{h}^0_{i,2:4},2).
\]

In the feed-forward network layer, $\vec{h}_i^{0.5}$ is mapped to $\FF(\vec{h}_i^{0.5})+\vec{h}_i^{0.5}$, which is $\vec{e}_{(\#,q_{start})}$ according to Equation (\ref{eq:ff}). Finally, the output layer outputs $(\#,q_{start})$ as desired.

\textbf{Inductive case II: $i\geq s(n)$}\quad  In the self-attention layer, observing that $\vec{K}\cdot \vec{h}^0_i=(\vec{0}_{c+7},1)=1$ and 
\begin{flalign*}
\vec{Q}\cdot \vec{h}^0_j=\pos(i-j)=\begin{cases}
 0, & \text{if } i-s(n)+1<j<i;\\
 1, & \text{if } j=i,\\
 2, & \text{if } j=i-s(n)+1,
 \end{cases}
\end{flalign*}
we have
\begin{align*}
\vec{s}_{i} =\hardmax\left(\langle \vec{h}^0_{i-s(n)+1}\cdot \vec{Q},\vec{h}^0_i\cdot \vec{K}\rangle,\cdots,\langle \vec{h}^0_i\cdot \vec{Q},\vec{h}^0_i\cdot \vec{K}\rangle\right)=(1,0\cdots,0)\in \R^{s(n)}
\end{align*}
and
\[
\vec{a}_{i}=\sum_{j=i-s(n)+1}^{i} s_{i,j}\cdot \left(\vec{0}_{c+4},\vec{h}^0_{j,2;4},h^0_{j:c+8}\right)=(\vec{0}_{c+4},\vec{h}_{i-s(n)+1,2:4}^0,2).\]
Then 
\[
\vec{h}_i^{0.5}=\vec{a}_i+\vec{h}_i^0=(\vec{h}^0_{i,1:c+4},\vec{h}^0_{i-s(n)+1,2:4},3).
\]

In the feed-forward network layer, noting that by the induction hypothesis, we have
\[
\vec{h}_{i,5:c+4}^{0.5}=\vec{h}_{i,5:c+4}^{0}=q_{i}, \text{ and } \vec{h}_{i,c+5:c+7}^{0.5}=\vec{h}^0_{i-s(n)+1,2:4}=\sigma_{i-s(n)+1}.
\]
The vector $\vec{h}_i^{0.5}$ is mapped to $\FF(\vec{h}_i^{0.5})+\vec{h}_i^{0.5}$, which is $\vec{e}_{\delta(\sigma_{i-s(n)+1},q_i)}$ according to Equation (\ref{eq:ff}). Recall that $\delta(\sigma_{i-s(n)+1},q_i)=(\sigma_{i+1},q_{i+1})$, then one can see that the output layer outputs $(\sigma_{i+1},q_{i+1})$ as desired. 
