\section{Up-concave Functions are Linearizable}
\label{subs: up-concave functions are linearizable functions}
Given $0 < \gamma \leq 1$, we say a differentiable function $f : \C{K} \to \B{R}$ is \textit{$\gamma$-weakly up-concave} if it is $\gamma$-weakly concave along positive directions.
Specifically if, for all $\x \leq \y$ in $\C{K}$, we have 

\begin{equation}
     \gamma \left( \langle \nabla f(\y), \y - \x \rangle \right) \leq f(\y) - f(\x)  \leq \frac{1}{\gamma} \left( \langle \nabla f(\x), \y - \x \rangle \right).
\end{equation}



We say $\tilde{\nabla} f : \C{K} \to \B{R}^d$ is a \textit{$\gamma$-weakly up-super-gradient} of $f$ if for all $\x \leq \y$ in $\C{K}$, the above holds with $\tilde{\nabla}$ instead of ${\nabla}$. 
We say $f$ is $\gamma$-weakly up-concave if it is continuous and it has a $\gamma$-weakly up-super-gradient.
When it is clear from the context, we simply refer to $\tilde{\nabla} f$ as an up-super-gradient for $f$.
 A differentiable function $f : \C{K} \to \B{R}$ is called  \textit{$\gamma$-weakly continuous DR-submodular} if for all $\x \leq \y$, we have $\nabla f(\x) \geq \gamma \nabla f(\y)$.
It follows that any $\gamma$-weakly continuous DR-submodular functions is $\gamma$-weakly up-concave. 



In this section, we provide for completeness that three cases of common up-concave functions can be formulated as upper-linearizable functions, and we give the exact query algorithm to obtain estimates of $\F{g}$ functions. We further show that $\F{g}$ given by these algorithms is Lipschitz-continuous, if $f$ is $L$-smooth.






\subsection{Monotone Up-concave optimization over general convex set}

Following  Lemma 1 by \citet{pedramfar2024linear}, we note that monotone up-concave optimization over general convex set can be formulated as an online maximization by quantization algorithm with trivial query $\C{G}$. 

\begin{lemma}[\citet{pedramfar2024linear}]
    \label{lem: monotone general}
    Let $f: [0, 1]^d \to \B{R}$ be a a non-negative monotone $\gamma$-weakly up-concave function with curvature bounded by $c$.
    Then, for all $\x, \y \in [0, 1]^d$, we have
    \begin{equation*}
        \frac{\gamma^2}{1 + c\gamma^2} f(\y) - f(\x) \leq \frac{\gamma}{1 + c\gamma^2} ( \langle \tilde{\nabla} f(\x), \y - \x \rangle ),
    \end{equation*}
    where $\tilde{\nabla} f$ is an up-super-gradient for $f$.
\end{lemma}





\subsection{Monotone up-concave optimization over convex set containing the origin}

Following  Lemma 2 by \citet{pedramfar2024linear}, we note that monotone up-concave optimization over convex set containing the origin can be formulated as an online maximization by quantization algorithm with non-trivial query $\C{G}=\mathtt{BQM0}$, which is described in Algorithm \ref{alg:bqm}. 

\begin{lemma}[\citet{pedramfar2024linear}]
    \label{lem: monotone origin}
    Let $f : [0, 1]^d \to \B{R}$ be a non-negative monotone $\gamma$-weakly up-concave differentiable function and let $F : [0, 1]^d \to \B{R}$ be the function defined by
    \begin{align*}
        F(\x) := \int_0^1 \frac{\gamma e^{\gamma (z - 1)}}{(1 - e^{-\gamma})z} (f(z * \x) - f(\BF{0})) dz.
    \end{align*}
    Then $F$ is differentiable and, if the random variable $\C{Z} \in [0, 1]$ is defined by the law 
    \begin{align}
        \label{eq:dr_mono_zero:law_z}
        \forall z \in [0, 1]
        ,\quad
        \B{P}(\C{Z} \leq z) = \int_0^z \frac{\gamma e^{\gamma (u - 1)}}{1 - e^{-\gamma}} du,
    \end{align}
    then we have $\B{E}\left[ \nabla f(\C{Z} * \x) \right] = \nabla F(\x)$.
    Moreover, we have
    \begin{align*}
        (1 - e^{-\gamma}) f(\y) - f(\x)
        &\leq
        \frac{1 - e^{-\gamma}}{\gamma} \langle \nabla F(\x), \y - \x \rangle.
    \end{align*}
\end{lemma}


\begin{algorithm}[ht]\label{alg:bqm}
    \caption{Boosted Query oracle for Monotone up-concave functions over convex sets containing the origin - $\mathtt{BQM0}$}  
    \label{alg:BQM0}
    \begin{algorithmic}[1]
        \STATE \textbf{Input:} first order query oracle, point $\x$
        \STATE Sample $z \in [0, 1]$ according to Equation~\eqref{eq:dr_mono_zero:law_z} in Lemma \ref{lem: monotone origin}
        \STATE \textbf{Return:} the output of the query oracle at $z * \x$
    \end{algorithmic}
\end{algorithm}
In this case, $\F{g} = \nabla F(\x) $, $h(\x)=\op{Id}$. Further, if $f$ is smooth, $\F{g}$ is Lipschitz continuous, as shown in the following Lemma. 

\begin{lemma}[Theorem 2(iii), \citet{zhang2022stochastic}]
If $f$ is $L$-smooth and satisfies other assumptions of Lemma \ref{lem: monotone origin}, $F$ is $L'$-smooth, where $L' = L \frac{\gamma+e^{-\gamma}-1}{\gamma (1 - e^{-\gamma})}$, i.e., $\nabla F(\x)$ is $L'$-Lipschitz continuous.
\end{lemma}



\subsection{Non-monotone up-concave optimization over general convex set}

Following  Lemma 3 by \citet{pedramfar2024linear}, we note that Non-monotone up-concave optimization over general convex set can be formulated as an online maximization by quantization algorithm with non-trivial query $\C{G}=\mathtt{BQN}$, as described in Algorithm \ref{alg:bqn}.

\begin{lemma}[\citet{pedramfar2024linear}]
\label{lem: non-monotone general}
Let $f : [0, 1]^d \to \B{R}$ be a non-negative continuous up-concave differentiable function and let $\underline{\x} \in \C{K}$.
Define $F : [0, 1]^d \to \B{R}$ as the function
\begin{align*}
F(\x) := \int_0^1 \frac{2}{3 z (1 - \frac{z}{2})^3} \left( f\left(\frac{z}{2} * (\x - \underline{\x}) + \underline{\x} \right) - f(\underline{\x}) \right) dz,
\end{align*}
Then $F$ is differentiable and, if the random variable $\C{Z} \in [0, 1]$ is defined by the law 
\begin{align}\label{eq:dr_nonmono:law_z}
\forall z \in [0, 1]
,\quad
\B{P}(\C{Z} \leq z) = \int_0^z \frac{1}{3 (1 - \frac{u}{2})^3} du,
\end{align}
then we have 
$\B{E}\left[ \nabla f\left(\frac{\C{Z}}{2} * (\x - \underline{\x}) + \underline{\x} \right) \right] = \nabla F(\x)$.
Moreover, we have
\vspace{-.1in}
\begin{align*}
\frac{1 - \|\underline{\x}\|_\infty}{4} f(\y) - f\left(\frac{\x + \underline{\x}}{2} \right)
&\leq
\frac{3}{8} \langle \nabla F(\x), \y - \x \rangle.
\end{align*}
\end{lemma}

\begin{algorithm}\label{alg:bqn}
    \caption{Boosted Query oracle for non-monotone up-concave functions over general convex sets - $\mathtt{BQN}$}
    \label{alg:BQN}
    \begin{algorithmic}[1]
        \STATE \textbf{Input:} First order query oracle, point $\x$
        \STATE Sample $z \in [0, 1]$ according to Equation~\ref{eq:dr_nonmono:law_z}
        \STATE \textbf{Return:} the output of the query oracle at $\frac{z}{2} * (\x - \underline{\x}) + \underline{\x}$
    \end{algorithmic}
\end{algorithm}

In this case, $\F{g} = \nabla F(\x) $, $h(\x): \x \mapsto \frac{\x_t + \underline{\x}}{2}$.  Further,  if  $f$ is $L$-smooth, $\F{g}$ is Lipschitz continuous, as given in the following Lemma. 



\begin{lemma}[Theorem 18, \citet{zhang2024boosting}]
If $f$ is $L$-smooth, $L_1$-Lipschitz and $f$ satisfies assumptions in Lemma \ref{lem: non-monotone general},  $\nabla F(\x)$ is $\frac{1}{8}L$-smooth and $\frac{3}{8}L_1$-Lipschitz continuous.
\end{lemma}




\section{Proof of Theorem~\ref{thm:main_base}}


    Let $\x^* = {\argmax}_{\uu \in \C{K}} \frac{1}{N}\sum_{t=1}^{T}\sum_{i=1}^Nf_{t,i}(\uu)$, $\C{T}_m = \{(m-1)K+1, \cdots , mK\}$. By the definition of $\alpha$-regret for agent $j$, we have
    \begin{align}\label{eq:decentralized-regret-bound}
        \B{E}[ \C{R}_{\alpha}^{j} ]
        &= \frac{1}{N}\sum_{t = 1}^{T}\sum_{i = 1}^{N} \B{E}\left[ \alpha f_{t,i}(\x^*) - f_{t,i}(h(\x_t^{j})) \right] \nonumber\\
        &= \frac{1}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m} \B{E}\left[ \alpha f_{t,i}(\x^*) - f_{t,i}(h(\x_m^{j})) \right]\nonumber\\
        &\overset{(a)}\le \frac{\beta}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m} \B{E}\left[ \langle \x^* - \x_m^{j}, \F{g}_{t,i}(\x_m^j) \rangle \right] \nonumber\\
        &\overset{(b)}= \frac{\beta}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m} \B{E}\left[ \langle \x^* - \x_m^{j}, \B{E}\left[ \tilde{\F{g}}_{t,i}(\x_m^j) | \x_m^j \right] \rangle \right] \nonumber\\
        &\overset{(c)}= \frac{\beta}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m} \B{E}\left[ \B{E}\left[ \langle \x^* - \x_m^{j}, \tilde{\F{g}}_{t,i}(\x_m^j) \rangle | \x_m^j \right] \right] \nonumber\\
        &\overset{(d)}= \frac{\beta}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m} \B{E}\left[ \langle \x^* - \x_m^{j}, \tilde{\F{g}}_{t,i}(\x_m^j) \rangle \right] \nonumber\\
        &\overset{(e)}= \B{E}\left[\underbrace{\frac{\beta}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m} \langle \x^* - \x_m^{i}, \gtit{\x_m^i} \rangle}_{:=P_1} \right]+ 
        \B{E}\left[\underbrace{\frac{\beta}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m}\langle \x_m^{i} - \x_m^{j}, \gtit{\x_m^i}\rangle}_{:=P_2} \right]\nonumber\\
        &+ \B{E}\left[\underbrace{\frac{\beta}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m}\langle \x^* - \x_m^{j}, \gtit{\x_m^j} - \gtit{\x_m^i} \rangle}_{:=P_3} \right]
    \end{align}

	where step (a) is because $f_{t,i}$'s are upper linearizable, step (b)is because $\gtit{\cdot}$ is unbiased, step (c) is due to the linearity of conditional expectation, step (d) is due to law of iterated expectation, and step (e) rewrites $(\x^*-\x^j_m)$ as $[(\x^*-\x^i_m)+(\x^i_m-\x^j_m)]$ and $\gtit{\x^j_m}$ as $[(\gtit{\x^j_m}-\gtit{\x^i_m})+\gtit{\x^i_m}]$.

    As illustrated in step (e) in Equation~\ref{eq:decentralized-regret-bound}, total regret can be divided into three parts, $P_1,P_2,P_3$, and we provide upper bound for each of these three parts with proof in the following sections, \ref{sec:apdxR1Bound}, \ref{sec:apdxR2Bound}, \ref{sec:apdxR3Bound}, respectively. In Section~\ref{sec:apdx_auxiliaryVariables}, we introduce some auxiliary variables and lemmas that are useful to the following proof.

\subsection{Auxiliary variables and lemmas}
\label{sec:apdx_auxiliaryVariables}

In this section, we introduce some auxiliary variables and lemmas to better present the proof of bound for each of the three parts of the total regret presented in Equation~\ref{eq:decentralized-regret-bound}.

Let $\y_{1}^i = \tilde{\y}_m^i = \BF{c}$, for any $i\in[N]$, since Algorithm~\ref{alg:main} would only generate $\y_{m}^i$ for $m=2,\cdots,T/K$. Let $\r_{m}^{i} = \tilde{\y}_{m}^{i} - \y_{m}^{i} $ for any $i\in[N]$ and $m\in[T/K]$. For any $m\in[T/K]$, we denote the averages by:
\[
\bar{\x}_m = \frac{\sum_{i = 1}^{N}\x_m^{i}}{N},~\bar{\y}_m = \frac{\sum_{i = 1}^{N}\y_m^{i}}{N},~\hat{\y}_m = \frac{\sum_{i = 1}^{N}\tilde{\y}_m^{i}}{N}, \text{ and } \bar{\r}_m = \frac{\sum_{i = 1}^{N}\r_m^{i}}{N}.\]

There are two lemmas that would be useful to the proofs, and we provide proof of each of these in the following appendices.

\begin{lemma}\label{lem:apdxLemmaRm}
    For any $i \in [N]$ and $m \in [T/K]$, Algorithm \ref{alg:main}  ensures
    \[
    \Vert \r_{m}^{i} \Vert \le 2\sqrt{3\epsilon} + 2\eta KG.
    \]
\end{lemma}

\begin{proof}
    See Appendix~\ref{sec:apdxProofLemmaRm} for complete proof for Lemma \ref{lem:apdxLemmaRm}.
\end{proof}

\begin{lemma}\label{lem:apdxLemmaYYX}
    For any $i \in [N]$ and $m\in[T/K]$, Algorithm \ref{alg:main}  ensures
    \begin{equation}
        \label{eq:apdxLemmYYX:1} \sqrt{\sum_{i = 1}^{N}\Vert \hat{\y}_{m} -  \tilde{\y}_{m}^{i} \Vert^2} \le   \frac{\sqrt{N}(3\eta KG + 2\sqrt{3\epsilon})}{1-\lambda_2},
    \end{equation}
     \vspace{-.1in}
    \begin{equation}
        \label{eq:apdxLemmYYX:2} \sqrt{\sum_{i = 1}^{N}\Vert \hat{\y}_{m} -  \y_{m+1}^{i} \Vert^2} \le \frac{\sqrt{N}(3\eta KG + 2\sqrt{3\epsilon})}{1-\lambda_2}, \text{ and}
    \end{equation}
     \vspace{-.1in}
    \begin{equation}                                                 
        \label{eq:apdxLemmYYX:3} 
        \sum_{i = 1}^{N}\Vert\x_{m}^{i} - \x_{m}^{j}\Vert \le \left(3\sqrt{2\epsilon} + \frac{(3\eta KG + 2\sqrt{3\epsilon})}{1-\lambda_2}\right) (N^{3/2}+N).
    \end{equation}
\end{lemma}

\begin{proof}
    See Appendix~\ref{sec:apdxProofLemmaYYX} for complete proof of Lemma~\ref{lem:apdxLemmaYYX}.
\end{proof}














\subsection{Bound of $P_1$}
\label{sec:apdxR1Bound}

By replacing $(\x^*-\x^i_m)$ with $[(\x^*-\hat{\y}_m)+(\hat{\y}_m-\tilde{\y}^i_m)+(\tilde{\y}^i_m-\x^i_m)]$, $P_1$ can be decomposed as:
\begin{align}\label{eq:apdxR1:1}
	\frac{1}{\beta}\P_1
        =& \frac{1}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m} \langle \hat{\y}_{m} -  \tilde{\y}_{m}^{i}, \gtit{\x_m^i}) \rangle + \frac{1}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m}\langle \tilde{\y}_{m}^{i} - \x_{m}^{i} , \gtit{\x_m^i} \rangle \nonumber\\
        +& \underbrace{\frac{1}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m} \langle  \x^* - \hat{\y}_{m}, \gtit{\x_m^i} \rangle}_{:=P_4}\nonumber\\
        \overset{(a)}\leq& \frac{G}{N} \left[\sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m} \Vert \hat{\y}_{m} -  \tilde{\y}_{m}^{i}\Vert +  \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m} \Vert \tilde{\y}_{m}^{i} - \x_{m}^{i} \Vert\right]+P_4\nonumber\\
        \overset{(b)}\leq&{G}\left(\sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m}\sqrt{\frac{1}{N}\sum_{i = 1}^{N}\Vert  \hat{\y}_m - \tilde{\y}_m^{i}\Vert^2} + T\sqrt{3\epsilon}\right)+\C{R}_4\nonumber\\
        \overset{(c)}\leq&TG\left(\frac{3\eta KG+ 2\sqrt{3\epsilon}}{1-\lambda_2}+\sqrt{3\epsilon}\right) + \C{R}_4
\end{align}
where step (a) follows from Cauchy-Schwartz inequality and the bound of $\gtit{\cdot}$ function, step (b) follows from Arithmetic Mean-Quadratic Mean inequality and Lemma \ref{lem:IP-num-LOO-calls}, and step (c) follows from Equation~\eqref{eq:apdxLemmYYX:1} in Lemma~\ref{lem:apdxLemmaYYX}.

To attain upper bound on $P_4$, we notice that,

\begin{align}\label{eq:apdxR1:2}
    \bar{\y}_{m+1} & = \frac{1}{N} \sum_{i = 1}^{N} \y_{m+1}^{i}  = \frac{1}{N} \sum_{i = 1}^{N} \left(\sum_{j \in \C{N}_i}a_{ij} \tilde{\y}_{m}^{j} + \eta\sum_{t \in \C{T}_m} \gtit{\x_m^i}\right) \nonumber \\
    &\overset{(a)}= \frac{1}{N} \sum_{i = 1}^{N} \sum_{j =1}^Na_{ij}\tilde{\y}_{m}^{j} + \frac{\eta}{N} \sum_{i = 1}^{N}\sum_{t \in \C{T}_m} \gtit{\x_m^i} \nonumber \\
    & \overset{(b)}= \hat{\y}_{m} + \frac{\eta}{N} \sum_{i = 1}^{N}\sum_{t \in \C{T}_m} \gtit{\x_m^i}
\end{align}
where step (a) is because $a_{ij}=0$ for any agent $j\notin\C{N}_i$, and step (b) is because $\A\mathbf{1} = \mathbf{1}$.

Substituting $\bar{\y}_{m+1}$ using Equation~\eqref{eq:apdxR1:1}, we have for any $m\in[T/K]$,
\begin{align}\label{eq:apdxR1:3}
\hat{\y}_{m+1} =& \hat{\y}_{m+1} -\bar{\y}_{m+1} +\bar{\y}_{m+1} \nonumber \\
\overset{\eqref{eq:apdxR1:2}}=& \bar{\r}_{m+1} + \hat{\y}_{m} + \frac{\eta}{N} \sum_{i = 1}^{N}\sum_{t \in \C{T}_m} \gtit{\x_m^i}
\end{align}
because $\bar{\r}_{m+1}=\hat{\y}_{m+1} -\bar{\y}_{m+1}$.

By replacing $\hat{\y}_{m+1}$ with Equation~\eqref{eq:apdxR1:3} and then expand the equation, we have
\begin{align}\label{eq:apdxR1:4}
    \Vert \hat{\y}_{m+1} -  \x^\ast  \Vert^2  \overset{\eqref{eq:apdxR1:3}}=& \left\Vert \bar{\r}_{m+1} + \hat{\y}_{m} + \frac{\eta}{N} \sum_{i = 1}^{N}\sum_{t \in \C{T}_m}\gtit{\x_m^i} -  \x^*  \right\Vert^2 \nonumber\\
    =& \Vert\hat{\y}_{m} - \x^* \Vert^2 + 2 \left\langle \hat{\y}_{m} -  \x^*, \frac{\eta}{N} \sum_{i = 1}^{N}\sum_{t \in \C{T}_m} \gtit{\x_m^i} \right\rangle\nonumber\\
    &+ 2 \langle \hat{\y}_{m} -  \x^* , \bar{\r}_{m+1} \rangle + \left\Vert \bar{\r}_{m+1} + \frac{\eta}{N} \sum_{i = 1}^{N}\sum_{t \in \C{T}_m} \gtit{\x_m^i} \right\Vert^2.
\end{align}

Following Lemma~\ref{lem:IP-num-LOO-calls}, we deduce that for any $m\in[T/K]$,
\[
\begin{split}
	\Vert\tilde{\y}_{m+1}^{i} - \x^\ast \Vert^2  & \le \Vert \y_{m+1}^{i} - \x^\ast \Vert^2 = \Vert \y_{m+1}^{i} - \tilde{\y}_{m+1}^{i} + \tilde{\y}_{m+1}^{i} - \x^\ast\Vert^2\\
	& = \Vert \y_{m+1}^{i} - \tilde{\y}_{m+1}^{i}\Vert^2 + 2\langle \y_{m+1}^{i} - \tilde{\y}_{m+1}^{i}, \tilde{\y}_{m+1}^{i} - \x^\ast \rangle + \Vert \tilde{\y}_{m+1}^{i} - \x^\ast \Vert^2\\
	& = \Vert  \mathbf{r}_{m+1}^{i}\Vert^2 - 2\langle  \mathbf{r}_{m+1}^{i}, \tilde{\y}_{m+1}^{i} - \x^\ast \rangle + \Vert \tilde{\y}_{m+1}^{i} - \x^\ast \Vert^2
\end{split}
\]
where the last equality is due to the definition of $\mathbf{r}_{m+1}^{i}$.

Omitting $\Vert\tilde{\y}_{m+1}^{i} - \x^\ast \Vert^2$ on both sides and moving $\langle \tilde{\y}_{m+1}^{i}  -  \x^\ast , \r_{m+1}^{i} \rangle$ to the left, we have
\begin{equation}
	\label{eq:apdxR1:5}
	\langle \tilde{\y}_{m+1}^{i}  -  \x^\ast , \r_{m+1}^{i} \rangle \leq \frac{1}{2}\Vert \mathbf{r}_{m+1}^{i} \Vert^2.
\end{equation}

Thus, we can bound the term $\langle \hat{\y}_{m} -  \x^\ast , \bar{\r}_{m+1} \rangle$ in Equation~\eqref{eq:apdxR1:4} as follows
\begin{align}
	\label{eq:apdxR1:6}
		\langle \hat{\y}_{m} -  \x^\ast , \bar{\mathbf{r}}_{m+1} \rangle& = \frac{1}{N} \sum_{i = 1}^{N}\langle \hat{\y}_{m} -  \x^\ast , \r_{m+1}^{i} \rangle \nonumber\\
		&\overset{(a)}\le \frac{1}{N} \sum_{i = 1}^{N}\langle \hat{\y}_{m} - \y_{m+1}^{i}  , \r_{m+1}^{i} \rangle + \frac{1}{N} \sum_{i = 1}^{N}\langle \tilde{\y}_{m+1}^{i}  -  \x^\ast , \r_{m+1}^{i} \rangle\nonumber\\
		&\overset{(b)} \le \frac{1}{N} \sum_{i = 1}^{N}\Vert \hat{\y}_{m} - \y_{m+1}^{i}\Vert \Vert \r_{m+1}^{i} \Vert + \frac{1}{2N} \sum_{i = 1}^{N}\Vert \r_{m+1}^{i}\Vert^2\nonumber\nonumber\\
		& \overset{(c)}\le \frac{2\eta KG + 2\sqrt{3\epsilon}}{\sqrt{N}} \sqrt{\sum_{i = 1}^{N}\Vert \hat{\y}_{m} - \y_{m+1}^{i}\Vert^2}  + \frac{1}{2N} \sum_{i = 1}^{N}\Vert \r_{m+1}^{i}\Vert^2\nonumber\\
		&\overset{(d)}\le \frac{1}{1-\lambda_2}\left( 6\eta^2 K^2G^2 + 10\eta KG\sqrt{3\epsilon} + 12\epsilon\right)\nonumber\\
		& + 2\left(\eta^2 K^2G^2 + 2\eta KG\sqrt{3\epsilon} + 3\epsilon\right)
\end{align}
where step (a) replaces $\hat{\y}_{m} -  \x^\ast$ as $(\hat{\y}_{m} -\y_{m+1}^{i}) + (\y_{m+1}^{i} - \tilde{\y}_{m+1}^{i}) + (\tilde{\y}_{m+1}^{i} -  \x^\ast)$ and omits $\langle \y_{m+1}^i - \tilde{\y}_{m+1}^i, \mathbf{r}_{m+1}^i \rangle \le 0$, step (b) is due to Cauchy-Schwartz inequality and Equation~\eqref{eq:apdxR1:5}, step (c) comes from Lemma~\ref{lem:apdxLemmaRm} and Arithmetic Mean-Quadratic Mean inequality, and step (d) follows from Equation~\ref{eq:apdxLemmYYX:1} in Lemma~\ref{lem:apdxLemmaYYX}. 

Also, we can bound the last term in Equation~\eqref{eq:apdxR1:4} as follows 
\begin{align}\label{eq:apdxR1:7}
    \left\Vert \bar{\r}_{m+1} + \frac{\eta}{N} \sum_{i = 1}^{N}\sum_{t \in \C{T}_m} \gtit{\x_m^i} \right\Vert^2 
    \overset{(a)}\le &  2\Vert \bar{\r}_{m+1} \Vert^2 + 2\left\Vert \frac{\eta}{N} \sum_{i = 1}^{N}\sum_{t \in \C{T}_m} \gtit{\x_m^i} \right\Vert^2 \nonumber\\
	\overset{(b)}\le &\frac{2}{N}\sum_{i = 1}^{N} \Vert \r_{m+1}^{i}\Vert^2 + \frac{2K\eta^2}{N} \sum_{i = 1}^{N}\sum_{t \in \C{T}_m}\Vert  \gtit{\x_m^i} \Vert^2 \nonumber\\
    \overset{(c)}\le& 8\left(\sqrt{3\epsilon} + \eta KG\right)^2 + 2\eta^2 K^2G^2 \nonumber\\
    =& 24\epsilon + 10\eta^2 K^2G^2 + 16\eta KG\sqrt{3\epsilon}
\end{align}
where both step (a) and step (b) utilize Cauchy-Schwartz inequality and step (c) is due to Lemma~\ref{lem:apdxLemmaRm} and the bound of $\gtit{\cdot}$ functions. 

Substitute Equation~\eqref{eq:apdxR1:6} and Equation~\eqref{eq:apdxR1:7} into Equation~\eqref{eq:apdxR1:4} and taking expectation on both sides, we have
\begin{equation}
	\label{eq:apdxR1:8}
	\begin{split}
		\mathbb{E}\left[\Vert  \x^* - \hat{\y}_{m+1}  \Vert^2\right] &\le \mathbb{E}\left[\Vert \x^* - \hat{\y}_{m} \Vert^2\right]  - \frac{2\eta}{N} \sum_{i = 1}^{N}\sum_{t \in \C{T}_m} \mathbb{E}\left[ \langle \x^* - \hat{\y}_{m} ,  \gtit{\x_m^i} \rangle \right] \\
		&  +  \frac{1}{1-\lambda_2}\left( 12\eta^2 K^2G^2 + 20\eta KG\sqrt{3\epsilon} + 24\epsilon\right)\\
		& + \left(14\eta^2 K^2G^2 + 24\eta KG\sqrt{3\epsilon} + 36\epsilon\right).
	\end{split}
\end{equation}

Moving terms to different sides in Equation~\eqref{eq:apdxR1:8}, we have
\begin{align}
    \label{eq:apdxR1:9}
    \E\left[P_4\right] 
    &= \frac{1}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m} \E\left[\langle  \x^* - \hat{\y}_{m}, \gtit{\x_m^i} \rangle \right] \nonumber\\
    & \overset{\eqref{eq:apdxR1:8}}\le \sum_{m = 1}^{T/K}\left[\frac{\mathbb{E}\left[\Vert\hat{\y}_{m} -  \x^* \Vert^2\right] - \mathbb{E}\left[\Vert\hat{\y}_{m+1} -  \x^* \Vert^2\right] }{2\eta}\right] \nonumber \\
    & + \frac{T}{K}\left[\frac{18\epsilon}{\eta} + 7\eta K^2G^2 + 12KG\sqrt{3\epsilon} \right]   \nonumber \\
    & + \frac{T}{K}\left[ \frac{1}{1-\lambda_2}\left( 6\eta K^2G^2 + 10KG\sqrt{3\epsilon} + \frac{12\epsilon}{\eta} \right)\right] \nonumber\\
    & \overset{(a)}\le \frac{2R^2}{\eta} + \frac{18\epsilon T}{\eta K} + 7\eta TKG^2 + 12TG\sqrt{3\epsilon} \nonumber \\
    & + \frac{1}{1-\lambda_2}\left( \frac{12\epsilon T}{\eta K} + 6\eta TKG^2 + 10TG\sqrt{3\epsilon} \right)
\end{align}
where the last inequality is due to $\mathbb{E}\left[\Vert\hat{\y}_{T/K+1} -  \x^* \Vert^2\right] \geq 0$ and $\Vert\hat{\y}_{1} - \x^*\Vert^2\le 4R^2$, which is derived by combining $\hat{\y}_1=\BF{c}\in\K$, $\x^\ast \in \C{K}$, and $R=\max_{\x\in\K}\Vert \x\Vert$, and Cauchy-Schwarz Inequality. 

Therefore, plugging the result for term $\E\left[ P_{4} \right]$ from Equation~\eqref{eq:apdxR1:9} into Equation~\eqref{eq:apdxR1:1}, we have
\begin{align}\label{eq:R1}
    \E\left[ P_{1} \right]
& \leq TG\beta \left(\frac{3\eta KG+ 2\sqrt{3\epsilon}}{1-\lambda_2}+\sqrt{3\epsilon}\right) \\
        & + \frac{2\beta R^2}{\eta} + \frac{18\beta\epsilon T}{\eta K} + 7\beta \eta TKG^2 + 12TG\beta \sqrt{3\epsilon} \nonumber \\
        & + \frac{\beta}{1-\lambda_2}\left( \frac{12\epsilon T}{\eta K} + 6\eta TKG^2 + 10TG\sqrt{3\epsilon} \right)
\end{align}


\subsection{Bound of $P_2$}
\label{sec:apdxR2Bound}

Next, we bound $P_2$ in (\ref{eq:decentralized-regret-bound})
\begin{align}\label{eq:R2}
    \P_2 
    &\overset{(\ref{eq:decentralized-regret-bound})}=\frac{\beta}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m}\langle \x_m^{i} - \x_m^{j}, \gtit{\x_m^i}\rangle \nonumber\\ 
    & \overset{(a)}\le  \frac{\beta}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m}\Vert\x_m^{i}-\x_m^{j}\Vert \Vert \gtit{\x_m^i}\Vert \nonumber\\
	& \overset{(b)}\leq \frac{G\beta}{N}\sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m} \sum_{i = 1}^{N} \Vert\x_m^{i}-\x_m^{j}\Vert \nonumber\\
	& \overset{(c)}\leq G \beta (N^{1/2}-+1)  \left( 3\sqrt{2\epsilon} + \frac{3\eta KG + 2\sqrt{3\epsilon}}{1-\lambda_2} \right) .
\end{align}
where step (a) is due to Cauchy-Schwartz inequality, step (b) follows from the bound of $\gtit{\cdot}$ functions, and step (c) uses the inequality (\ref{eq:apdxLemmYYX:3}) in Lemma \ref{lem:apdxLemmaYYX}.


\subsection{Bound of $P_3$}
\label{sec:apdxR3Bound}

Recall that $\F{g}_{t,i}(\cdot)$ are $L_1$-Lipschitz continuous, i.e., $$\Vert \F{g}_{t,i}(\x_m^{j}) - \F{g}_{t,i}(\x_m^{i})\Vert \leq L_1 \Vert \x_m^{i} - \x_m^{j}\Vert.$$ 
Thus, we have
\begin{align}\label{eq:R3}
    \E\left[P_3\right] 
    &\overset{(\ref{eq:decentralized-regret-bound})}=\frac{\beta}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m}\E \langle \x^* - \x_m^{j}, \gtit{\x_m^j} - \gtit{\x_m^i} \rangle \nonumber \\
    &\overset{(a)}= \frac{\beta}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m}\mathbb{E}\left[\left\langle\x^*-\x_m^{j},\E\left[\gtit{\x_m^j} | \x_m^{j}\right]  - \E\left[\gtit{\x_m^i}|\x_m^{i}\right]\right\rangle\right] \nonumber \\
    &\overset{(b)} = \frac{\beta}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m}\mathbb{E}\left[\langle\x^*-\x_m^{j}, \F{g}_{t,i}(\x_m^{j}) - \F{g}_{t,i}(\x_m^{i}) \rangle\right] \nonumber \\
    & \overset{(c)}\leq \frac{\beta}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m}\mathbb{E}\left[\Vert\x^*-\x_m^{j}\Vert \Vert \F{g}_{t,i}(\x_m^{j}) - \F{g}_{t,i}(\x_m^{i})\Vert\right] \nonumber \\
    & \overset{(d)}\leq \frac{L_1\beta}{N} \sum_{i = 1}^{N} \sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m}\mathbb{E}\left[\Vert\x^*-\x_m^{j}\Vert \Vert \x_m^{i} - \x_m^{j}\Vert\right] \nonumber \\
    & \overset{(e)}\leq \frac{2L_1R\beta}{N} \mathbb{E}\left[\sum_{m = 1}^{T/K} \sum_{t \in \C{T}_m} \sum_{i = 1}^{N}\Vert\x_{m}^{i} - \x_{m}^{j}\Vert\right] \nonumber \\
    & \overset{(f)}\leq 2L_1R \beta (N^{1/2}+1) \left( 3\sqrt{2\epsilon} + \frac{3\eta KG + 2\sqrt{3\epsilon}}{1-\lambda_2} \right) 
\end{align}
where step (a) and (b) is due to the law of iterated expectations, step (c) comes from Cauchy-Schwartz inequality, step (d) follows from continuity of $\F{g}_{t,i}(\cdot)$ functions, step (e) follows from the bound on $\K$ and Cauchy-Schwartz inequality, and step (f) is due to Equation~\eqref{eq:apdxLemmYYX:3} in Lemma~\ref{lem:apdxLemmaYYX}.




\subsection{Final Regret Bound}
\label{sec:apdx_totalRegretBound}

Plugging Equation~\eqref{eq:R1}, Equation~\eqref{eq:R2} and Equation~\eqref{eq:R3} into Equation~\eqref{eq:decentralized-regret-bound}, for any $j\in[N]$, we have
\[
\begin{split}
	\E\left[\C{R}_{T,\alpha}^{j} \right]
    &  \leq \frac{2\beta R^2}{\eta} + \frac{18\epsilon\beta T}{\eta K} + 7\eta\beta TKG^2 + 13TG\beta\sqrt{3\epsilon} \\
	& + \frac{\beta}{1-\lambda_2}\left( \frac{12\epsilon T}{\eta K} + 9\eta TKG^2 + 12TG\sqrt{3\epsilon} \right) \\
    & + G \beta (N^{1/2}+1) \left(3\sqrt{2\epsilon} + \frac{(3\eta KG + 2\sqrt{3\epsilon})}{1-\lambda_2} \right) \\
    & + 2L_1RT\beta (N^{1/2}+1) \left(3\sqrt{2\epsilon} + \frac{(3\eta KG + 2\sqrt{3\epsilon})}{1-\lambda_2} \right) 
\end{split}
\]



\subsection{Number of Linear Optimization Oracle Calls}

Finally, we analyze the total number of linear optimization oracle calls for each agent $i$. In Lemma~\ref{lem:IP-num-LOO-calls}, the term $\C{R}_5=\left\Vert \y_{m+1}^{i} - \sum_{j \in \C{N}_i}a_{ij}\x_m^{j} \right\Vert^2$ can be bounded as follows
\begin{align}\label{eq:apdxLOO:1}
    \C{R}_5 = \left\Vert \y_{m+1}^{i} - \sum_{j \in \C{N}_i}a_{ij}\x_m^{j} \right\Vert^2 
    & \overset{(a)}\le 2 \left\Vert \y_{m+1}^{i}- \sum_{j \in \C{N}_i}a_{ij}\tilde{\y}_m^{j}\right\Vert^2 + 2\left\Vert \sum_{j \in \C{N}_i}a_{ij}\tilde{\y}_m^{j} - \sum_{j \in \C{N}_i}a_{ij}\x_m^{j} \right\Vert^2 \nonumber\\
    & \overset{(b)}\leq 2 \left\Vert \eta  \sum_{t\in \C{T}_m}\gtit{\x_{m}^{i}} \right\Vert^2 + 2\sum_{j \in \C{N}_i}a_{ij} \left\Vert \tilde{\y}_m^{j} -\x_m^{j} \right\Vert^2 \nonumber\\
    &\overset{(c)}\leq 2\eta^2K^2G^2 + 6\epsilon
\end{align}
where both step (a) follows from Cauchy-Schwartz inequality, step (b) follows from Cauchy-Schwartz inequality and Line~(10) in Algorithm~\ref{alg:main}



From Equation~\eqref{LO-Complex} in Lemma~\ref{lem:IP-num-LOO-calls}, in each block $m$, each agent $i$ in Algorithm~\ref{alg:main} at most utilizes
\begin{align}\label{eq:apdxLOO:2}
        l_m^{i} &= \frac{27R^2}{\epsilon}\max\left(\frac{\Vert \y_{m+1}^{i} - \sum_{j \in \C{N}_i}a_{ij}\x_m^{j}\Vert^2(\Vert \y_{m+1}^{i} - \sum_{j \in \C{N}_i}a_{ij}\x_m^{j}\Vert^2 - \epsilon)}{4\epsilon^2} + 1 , 1\right) \nonumber\\
        &= \frac{27R^2}{\epsilon} \max\left(\frac{\C{R}_5(\C{R}_5-\epsilon)}{4\epsilon^2}+1,1\right) \nonumber \\
        &\overset{\eqref{eq:apdxLOO:1}}\leq \frac{27R^2}{\epsilon} \max\left(\frac{(2\eta^2K^2G^2 + 6\epsilon)(2\eta^2K^2G^2 + 6\epsilon-\epsilon)}{4\epsilon^2}+1,1\right) \nonumber \\
        &= \frac{27R^2}{\epsilon} \frac{(2\eta^2K^2G^2 + 6\epsilon)(2\eta^2K^2G^2 + 5\epsilon)+4\epsilon^2}{4\epsilon^2}
\end{align}
linear optimization oracle calls, where the last equality is due to the fact that $(2\eta^2K^2G^2 + 6\epsilon)(2\eta^2K^2G^2 + 5\epsilon) \geq 0$.


Thus, by summing Equation~\eqref{eq:apdxLOO:2} over $\frac{T}{K}$ blocks, we have that the total number of linear optimization steps required by each agent $i$ of Algorithm~\ref{alg:main} is at most
\[
\sum_{m = 1}^{T/K}l_m^i \le \frac{27TR^2}{\epsilon K}\left(8.5 + 5.5\frac{K^2\eta^2G^2}{\epsilon} + \frac{K^4\eta^4G^4}{\epsilon^2} \right) 
\]





\subsection{Proof of Lemma \ref{lem:apdxLemmaRm}}
\label{sec:apdxProofLemmaRm}

\begin{align*}
    \Vert \r_{m+1}^{i} \Vert &= \Vert \tilde{\y}_{m+1}^{i} - \y_{m+1}^{i}\Vert \overset{(a)}\le \left\Vert \tilde{\y}_{m+1}^{i} - \sum_{j \in \mathcal{N}_i}a_{ij}\x_{m}^{j}\right\Vert + \left\Vert \sum_{j \in \mathcal{N}_i}a_{ij}\x_{m}^{j} - \y_{m+1}^{i} \right\Vert \\
    & \overset{(b)}\le  2\left\Vert \sum_{j \in \mathcal{N}_i}a_{ij}\x_{m}^{j} - \y_{m+1}^{i}\right\Vert \overset{(c)}= 2\left\Vert \sum_{j \in \mathcal{N}_i}a_{ij}\x_{m}^{j} - \sum_{j \in \mathcal{N}_i}a_{ij}\tilde{\y}_{m}^{j} - \eta \sum_{t =(m-1)K+1}^{mK}\gtit{\x_m^{i}}\right\Vert \\
    & \overset{(d)}\le 2\sum_{j \in \mathcal{N}_i}a_{ij} \Vert\x_{m}^{j} - \tilde{\y}_{m}^{j} \Vert + 2\eta K G \\
    & \overset{(e)}\le 2\sqrt{3\epsilon} + 2\eta KG
\end{align*}
where step (a) comes from triangle inequality, step (b) follows by Lemma \ref{lem:IP-num-LOO-calls}, step (c) replaces $\y_{m+1}^i$ with update rule described in Algorithm \ref{alg:main}, step (d) comes from triangle inequality, and step (e) follows by Lemma \ref{lem:IP-num-LOO-calls}. 

Moreover, if $m=1$, we can verify that \[\|\r_1^{i}\| = \|\BF{0}\| \le 2\sqrt{3\epsilon} + 2\eta KG.\]



\subsection{Proof of Lemma \ref{lem:apdxLemmaYYX}}
\label{sec:apdxProofLemmaYYX}

To prove Lemma \ref{lem:apdxLemmaYYX}, we introduce additional auxiliary variables as follows:
 \[\x_m^{\prime} = [\x_m^{1};\cdots;\x_m^{N}]\in \mathbb{R}^{Nd},~\y_m^{\prime} = [\y_m^{1};\cdots;\y_m^{N}]\in \mathbb{R}^{Nd},~\tilde{\y}_m^\prime = [\tilde{\y}_m^{1};\cdots;\tilde{\y}_m^{N}]\in \mathbb{R}^{Nd}\] and \[\r_m^{\prime} = [\r_m^{1};\cdots;\r_m^{N}]\in \mathbb{R}^{Nd},~\g_m^{\prime} = \sum_{t=(m-1)K+1}^{mK}[\tilde{\F{g}} _{t,1}(\x_m^{1});\cdots;\tilde{\F{g}}_{t,N}(\x_m^{N})]\in \mathbb{R}^{Nd}.\] 

According to step 10 in Algorithm \ref{alg:main}, for any $m\in\{2,\dots, T/K\}$, we have
\begin{align}\label{eq:apdxD:1}
    \y_{m+1}^{\prime} & = (\mathbf{A}\otimes\mathbf{I})\tilde{\y}_{m}^{\prime} + \eta \g_{m}^{\prime}  = \sum_{k=1}^{m - 1}(\mathbf{A}\otimes\mathbf{I})^{m - k}\r_{k+1}^{\prime} +  \sum_{k=1}^{m}(\mathbf{A}\otimes\mathbf{I})^{m - k}\eta \g_{k}^{\prime}
\end{align}

where the notation $\otimes $ indicates the Kronecker product and $\I$ denotes the identity matrix of size $n\times n$. 

In the same manner, for any $m\in[T/K]$, we have
\begin{align}\label{eq:apdxD:2}
	\tilde{\y}_{m+1}^{\prime} & = \r_{m+1}^{\prime} + \y_{m+1}^{\prime} = \r_{m+1}^{\prime} +  (\mathbf{A}\otimes\mathbf{I})\tilde{\y}_{m}^{\prime} + \eta \g_{m}^{\prime}\nonumber\\
	& = \sum_{k=1}^{m}(\mathbf{A}\otimes\mathbf{I})^{m - k}\r_{k+1}^{\prime} +  \sum_{k=1}^{m}(\mathbf{A}\otimes\mathbf{I})^{m - k}\eta \g_{k}^{\prime}
\end{align}
where the second equality follows the fact that $\r_1^{\prime} = \tilde{\y}_1^{\prime} - \y_1^{\prime} = \mathbf{0}$. 

By the definition of $\hat{\y}_{m+1}$, for any $m \in [T/K]$, we have 
\begin{align}\label{eq:apdxD:3}
    	[\hat{\y}_{m+1};\cdots;\hat{\y}_{m+1}] & = \left(\frac{\mathbf{1}\mathbf{1}^{T}}{N}\otimes \mathbf{I}\right)\tilde{\y}_{m+1}^{\prime}
\end{align}

where the second equality comes from $\mathbf{1}^{\top}\A = \mathbf{1}^\top$. 

\subsubsection{Proof of Equation \eqref{eq:apdxLemmYYX:1}}

For any $ m \in [T/K]$, we have
\[
\begin{split}
	&\sqrt{\sum_{i = 1}^{N}\Vert \hat{\y}_{m+1} -  \tilde{\y}_{m+1}^{i} \Vert^2} 
	 \overset{(\ref{eq:apdxD:3})}= \left\Vert \left(\frac{\mathbf{1}\mathbf{1}^{T}}{N}\otimes \mathbf{I}\right)\tilde{\y}_{m+1}^{\prime} - \tilde{\y}_{m+1}^{\prime} \right\Vert\\
	 \overset{(\ref{eq:apdxD:2})}=& \left\Vert \sum_{k=1}^{m}\left(\left(\frac{\mathbf{1}\mathbf{1}^{T}}{N} - \mathbf{A}^{m-k}\right)\otimes \mathbf{I}\right)\r_{k+1}^{\prime} +  \sum_{k=1}^{m}\left(\left(\frac{\mathbf{1}\mathbf{1}^{T}}{N} - \mathbf{A}^{m-k}\right)\otimes \mathbf{I}\right)\eta \g_{k}^{\prime} \right\Vert \\
	\overset{(a)}\le& \left\Vert \sum_{k=1}^{m}\left(\left(\frac{\mathbf{1}\mathbf{1}^{T}}{N} - \mathbf{A}^{m-k}\right)\otimes \mathbf{I}\right)\r_{k+1}^{\prime}\right\Vert +\left\Vert  \sum_{k=1}^{m}\left(\left(\frac{\mathbf{1}\mathbf{1}^{T}}{N} - \mathbf{A}^{m-k}\right)\otimes \mathbf{I}\right)\eta \g_{k}^{\prime} \right\Vert\\
	\overset{(b)}\le&  \sum_{k=1}^{m} \left\Vert \frac{\mathbf{1}\mathbf{1}^{T}}{N} - \mathbf{A}^{m-k}\right\Vert \left\Vert \r_{k+1}^{\prime}\right\Vert + \sum_{k=1}^{m}\left\Vert  \frac{\mathbf{1}\mathbf{1}^{T}}{N} - \mathbf{A}^{m-k}\right\Vert\left\Vert\eta \g_{k}^{\prime} \right\Vert\\
    \overset{(c)}\le& \sqrt{N} \sum_{k=1}^{m}  \lambda_2^{m-k}(3\eta KG + 2\sqrt{3\epsilon}) \overset{(d)}\le \frac{\sqrt{N}(3\eta KG + 2\sqrt{3\epsilon})}{1-\lambda_2},\\
\end{split}
\]
where step (a) is due to triangle inequality, and step (b) is due to Cauchy-Schwartz inequality and triangle inequality, step (c) comes from Lemma~\ref{lem:apdxLemmaRm} and the fact that $\forall k \in [m], \Vert\frac{\mathbf{1}\mathbf{1}^{T}}{N} - \mathbf{A}^{m-k}\Vert \le \lambda_2^{m-k}$ (see \citet{mokhtari2018decentralized} for details), and step (d) is due to the property of geometric series.

By noticing $\hat{\y}_1=\tilde{\y}_1=\mathbf{c}$, we complete the proof of Equation~\eqref{eq:apdxLemmYYX:1} in Lemma~\ref{lem:apdxLemmaYYX}.

\subsubsection{Proof of Equation~\eqref{eq:apdxLemmYYX:2}}

Similarly, for any $m \in \{2, \cdots, T/K\}$, we have
\[
\begin{split}
	& \sqrt{\sum_{i = 1}^{N}\Vert \hat{\y}_{m} -  \y_{m+1}^{i} \Vert^2}  \overset{(\ref{eq:apdxD:3})}= \left\Vert \left(\frac{\mathbf{1}\mathbf{1}^{T}}{N}\otimes \mathbf{I}\right)\tilde{\y}_{m}^{\prime} - \y_{m+1}^{\prime} \right\Vert\\
	 \overset{(\ref{eq:apdxD:1})}=& \left\Vert \sum_{k=1}^{m - 1}\left(\left(\frac{\mathbf{1}\mathbf{1}^{T}}{N} - \mathbf{A}^{m-k}\right)\otimes \mathbf{I}\right)\r_{k+1}^{\prime} +  \sum_{k=1}^{m-1}\left(\left(\frac{\mathbf{1}\mathbf{1}^{T}}{N} - \mathbf{A}^{m-k}\right)\otimes \mathbf{I}\right)\eta \g_{k}^{\prime} - \eta \g_{m}^{\prime}\right\Vert \\
	\overset{(a)}\le& \left\Vert \sum_{k=1}^{m-1}\left(\left(\frac{\mathbf{1}\mathbf{1}^{T}}{N} - \mathbf{A}^{m-k}\right)\otimes \mathbf{I}\right)\r_{k+1}^{\prime}\right\Vert +\left\Vert  \sum_{k=1}^{m-1}\left(\left(\frac{\mathbf{1}\mathbf{1}^{T}}{N} - \mathbf{A}^{m-k}\right)\otimes \mathbf{I}\right)\eta \g_{k}^{\prime} \right\Vert + \left\Vert \eta \g_{m}^{\prime} \right\Vert\\
	\overset{(b)}\le&  \sum_{k=1}^{m-1} \left\Vert \frac{\mathbf{1}\mathbf{1}^{T}}{N} - \mathbf{A}^{m-k}\right\Vert \left\Vert\r_{k+1}^{\prime}\right\Vert + \sum_{k=1}^{m-1}\left\Vert  \frac{\mathbf{1}\mathbf{1}^{T}}{N} - \mathbf{A}^{m-k}\right\Vert\left\Vert\eta \g_{k}^{\prime} \right\Vert + \Vert \eta \g_{m}^{\prime} \Vert\\
	\overset{(c)}\le&\sqrt{N}\sum_{k=1}^{m}  \lambda_2^{m-k}(3\eta KG + 2\sqrt{3\epsilon})	\overset{(d)}\le \frac{\sqrt{N}(3\eta KG + 2\sqrt{3\epsilon})}{1-\lambda_2},
\end{split}
\]
where step (a) is due to triangle inequality, and step (b) is due to Cauchy-Schwartz inequality and triangle inequality, step (c) comes from Lemma~\ref{lem:apdxLemmaRm} and the fact that $\forall k \in [m], \Vert\frac{\mathbf{1}\mathbf{1}^{T}}{N} - \mathbf{A}^{m-k}\Vert \le \lambda_2^{m-k}$ (see \citet{mokhtari2018decentralized} for details), and step (d) is due to the property of geometric series.

When $m = 1$, $\hat{\y}_{1} = \tilde{\y}_{1}^{i} = \sum_{j \in \mathcal{N}_i} a_{ij}\tilde{\y}_{1}^{j} = \mathbf{c} $. Due to Line~(10) in Algorithm~\ref{alg:main}, we have
\[
\sqrt{\sum_{i = 1}^{N}\Vert \hat{\y}_{1} -  \y_{2}^{i} \Vert^2} = \sqrt{\sum_{i = 1}^{N}\left\Vert \sum_{j \in \mathcal{N}_i} a_{ij}\tilde{\y}_{1}^{j} -  \y_{2}^{i} \right\Vert^2} = \sqrt{\sum_{i = 1}^{N}\left\Vert \sum_{t\in\C{T}_m}\gtit{\x_m^i} \right\Vert^2} \le \sqrt{N}\eta KG.
\]

By noticing that $\sqrt{N}\eta KG < \frac{\sqrt{N}(3\eta KG + 2\sqrt{3\epsilon})}{1-\lambda_2}$, we complete the proof of Equation~\eqref{eq:apdxLemmYYX:2}.

\subsubsection{Proof of Equation~\eqref{eq:apdxLemmYYX:3}}

For any $m\in[T/K]$, we notice that
\begin{align}\label{eq:apdxD3:1}
        \sum_{i = 1}^{N}\Vert\x_{m}^{i} - \x_{m}^{j}\Vert &\le \sum_{i = 1}^{N}\Vert\x_{m}^{i} - \bar{\x}_{m} + \bar{\x}_{m} - \x_{m}^{j}\Vert  \le \sum_{i = 1}^{N} \Vert \x_m^{i} - \bar{\x}_m \Vert+ N \Vert \bar{\x}_m - \x_m^{j}\Vert \nonumber\\
		& \le \left(\sqrt{N}+ N\right)  \sqrt{\sum_{i = 1}^{N} \Vert \x_m^{i} - \bar{\x}_m \Vert^2  }  .
\end{align}

Moreover, for any $i\in[N]$ and $m\in\{2,\dots,T/K\}$, we have
\[
\begin{split}
	\Vert \bar{\x}_{m} - \x_{m}^{i} \Vert^2& \le \Vert \bar{\x}_{m} - \hat{\y}_{m} + \hat{\y}_m - \tilde{\y}_{m}^{i} +  \tilde{\y}_{m}^{i} -  \x_{m}^{i} \Vert^2\\
	& \overset{(a)}\le 3\Vert \bar{\x}_{m} - \hat{\y}_{m} \Vert^2 + 3\Vert \hat{\y}_{m} - \tilde{\y}_{m}^{i} \Vert^2 + 3\Vert \tilde{\y}_{m}^{i} -  \x_{m}^{i} \Vert^2\\
    & \overset{(b)}\le \frac{3}{N}\sum_{j = 1}^{N}\Vert \x_{m}^{j} - \tilde{\y}_{m}^{j} \Vert^2 + 3\Vert \hat{\y}_{m} - \tilde{\y}_{m}^{i} \Vert^2 + 3\Vert \tilde{\y}_{m}^{i} -  \x_{m}^{i} \Vert^2\\
    & \overset{(c)}\le 18\epsilon + 3\Vert \hat{\y}_{m} - \tilde{\y}_{m}^{i} \Vert^2,
\end{split}
\]
where step (a) utilizes Cauchy-Schwarz inequality, step (b) utilizes Cauchy-Schwarz inequality and the definition of $\hat{\y}_{m}$ and $\bar{\x}_{m}$, and step (c) comes from Lemma \ref{lem:IP-num-LOO-calls}. When $m=1$, $\Vert \bar{\x}_{1} - \x_{1}^{i} \Vert^2 = \BF{0} \le 18\epsilon + 3\Vert \hat{\y}_{m} - \tilde{\y}_{m}^{i} \Vert^2$, which leads us to conclude that for any $m\in[T/K]$, 
\begin{align*}
    \Vert \bar{\x}_{m} - \x_{m}^{i} \Vert^2 \le 18\epsilon + 3\Vert \hat{\y}_{m} - \tilde{\y}_{m}^{i} \Vert^2.
\end{align*}
Thus, for any  $m \in [T/K]$, we have
\begin{align}\label{eq:apdxD3:2}
    \sqrt{\sum_{i = 1}^{N}\Vert \bar{\x}_{m} -  \x_{m}^{i} \Vert^2} & \le \sqrt{\sum_{i = 1}^{N}\left(18\epsilon + 3\Vert \hat{\y}_{m} - \tilde{\y}_{m}^{i} \Vert^2 \right)} \nonumber\\
	& \overset{(a)}\le 3\sqrt{2N \epsilon} +\sqrt{3 \sum_{i = 1}^{N}\Vert \hat{\y}_{m} -  \tilde{\y}_{m}^{i} \Vert^2} \nonumber\\
	& \overset{(b)}\le 3\sqrt{2N \epsilon} + \frac{\sqrt{3N}(3\eta KG + 2\sqrt{3\epsilon})}{1-\lambda_2}
\end{align}
where step (a) is due to triangle inequality and step (b) follows by Equation~\eqref{eq:apdxLemmYYX:1} in Lemma~\ref{lem:apdxLemmaYYX}.

Finally, by substituting Equation~\eqref{eq:apdxD3:2} into Equation~\eqref{eq:apdxD3:1}, for any $m \in [T/K]$, we have
\begin{align*}
    \sum_{i = 1}^{N}\Vert\x_{m}^{i} - \x_{m}^{j}\Vert &\le (\sqrt{N}+ N)  \sqrt{\sum_{i = 1}^{N} \Vert \x_m^{i} - \bar{\x}_m \Vert^2  }\\
    	& \le \left(3\sqrt{2\epsilon} + \frac{(3\eta KG + 2\sqrt{3\epsilon})}{1-\lambda_2}\right) (N^{3/2}+N).
\end{align*}



 \section{Bandit Feedback for Trivial Query Oracle}
\label{apdx:bandit-trivial}

In this section, we describe and discuss the variation of $\mathtt{DOCLO}$ to handle bandit feedback for functions with trivial query oracle. 
The detailed implementation is given in the Algorithm~\ref{alg:STB-DOCLO}, followed by proof of Theorem~\ref{thm:bandit-trivial}. 
This algorithm requires additional input from the user: smoothing parameter $\delta \leq \alpha$, shrunk set $\hat{\K}_\delta$, linear space $\C{L}_0$. 
Since queries are trivial, $h(\x) = \x$.


\begin{algorithm}
\caption{Bandit Algorithm for Trivial Query}  
\label{alg:STB-DOCLO}
\begin{algorithmic}[1]
\STATE \textbf{Input:} decision set $\C{K}$, horizon $T$, block size $K$, step size $\eta$, error tolerance $\epsilon$, number of agents $N$, weight matrix $\mathbf{A} = [a_{ij}]\in \mathbb{R}_{+}^{N\times N}$, Query Algorithm $\C{G}$, transformation map $h(\cdot)$, smoothing parameter $\delta \leq \alpha$, shrunk set $\hat{\K}_\delta$, linear space $\C{L}_0$, value oracle
\STATE Let $k = \op{dim}(\C{L}_0)$
\STATE Set $\x_1^i = \tilde{\y}_1^i = \BF{c} \in \C{\hat{\K}_\delta}$ for any $i=1,\cdots,N$
\FOR{$m = 1 ,\cdots, T/K$}
\FOR{each node $i = 1,\cdots,N$ in parallel}
\FOR{$t = (m-1)K+1,\dots,mK$}
\STATE Sample $\vv_{t}^i \in \B{S}^1 \cap \C{L}_0$ uniformly
\STATE Play $h(\x_m^i)+ \delta \vv_t^i$
\STATE Let $o_{t}^i$ be the output of the value oracle  (i.e., the output of value oracle for $f_{t,i}$ at $h(\x_m^i)+ \delta \vv_t^i$)
\STATE $\BF{o}_{t}^i \gets \frac{k}{\delta} o_{t}^i \vv_{t}^i$
\ENDFOR
\STATE Communicate $\x_{m}^{i}$ and $\tilde{\y}_m^{i}$ with neighbors
\STATE $\y_{m+1}^{i} \gets \sum\limits_{j \in \C{N}_i}a_{ij}\tilde{\y}_m^{j} + \eta\sum\limits_{t\in \C{T}_m} \BF{o}_{t}^i$
\STATE $(\x^i_{m+1},\tilde{\y}_{m+1}^i)\gets O_{IP}\left( \hat{\C{K}}_\delta, \sum\limits_{j \in \C{N}_i}a_{ij}\x_{m}^{j},\y_{m+1}^i,\epsilon \right)$
\ENDFOR
\ENDFOR
\end{algorithmic}
\end{algorithm}


\begin{proof}

Let $\C{A}^\prime$ denote Algorithm~\ref{alg:STB-DOCLO} and $\C{A}$ denote Algorithm~\ref{alg:main}. Let $\hat{f}_{t,j}$ denote a $\delta$-smoothed version of $f_{t,i}$. Let $\x^* \in \op{argmax}_{\x \in \K} \sum_{t = 1}^T \sum_{j=1}^N f_{t,j}(\x)$ and $\hat{\x}^* \in \op{argmax}_{\x \in \hat{\K}_\delta} \sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(\x)$. Following our description in Section~\ref{sec:bandit-trivial}, Algorithm~\ref{alg:STB-DOCLO} is equivalent to running Algorithm~\ref{alg:main} on $\hat{f}_{t,i}$, a $\delta$ smoothed version of $f_{t,i}$ over a shrunk set $\hat{\K}_\delta$.

By the definition of regret, we have
\begin{align}\label{eq:bandit-trivial:1}
\B{E}\left[\C{R}_{\alpha}^{i,\C{A}'}\right]
  - \B{E}\left[\C{R}_{\alpha}^{i,\C{A}}\right]
&= \frac{1}{N} \B{E}\left[ \alpha \sum_{t = 1}^T \sum_{j=1}^N f_{t,j}(\x^*) 
  - \sum_{t = 1}^T \sum_{j=1}^N f_{t,j}(h(\x_t^i) + \delta\vv_t^i) \right]\nonumber\\
&\quad- \frac{1}{N}\B{E}\left[ \alpha \sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(\hat{\x}^*) 
  - \sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(h(\x_t^i)) \right] \nonumber \\
&= \frac{1}{N}\B{E}\left[ \left( \sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(h(\x_t^i)) - \sum_{t = 1}^T \sum_{j=1}^N f_{t,j}(h(\x_t^i)+\delta\vv_t^i) \right)\right.\nonumber\\
&\quad\left. + \alpha \left( \sum_{t = 1}^T \sum_{j=1}^N f_{t,j}(\x^*) - \sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(\hat{\x}^*) \right)\right].
\end{align}

Based on Lemma 3 proved by \citet{pedramfar23_unified_approac_maxim_contin_dr_funct}, we have $| \hat{f}_{t,j}(h(\x_t^i)) - f_{t,j}(h(\x_t^i)) | \leq \delta M_1$, and $\hat{f}_{t,j}$ is $M_1$-Lipschitz continuous as well. Thus, we have 
\begin{align}\label{eq:bandit-trivial:2}
| f_{t,j}(h(\x_t^i)+\delta\vv_t^i) -\hat{f}_{t,j}(h(\x_t^i)) | 
&\leq | f_{t,j}(h(\x_t^i)+\delta\vv_t^i) - f_{t,j}(h(\x_t^i)) | + | f_{t, j}(h(\x_t^i)) - \hat{f}_{t,j}(h(\x_t^i)) | 
\leq 2 \delta M_1.
\end{align}
Meanwhile, for the second part of Equation~\ref{eq:bandit-trivial:1}, we have
\begin{align*}
\sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(\hat{\x}^*) 
&= \max_{\hat{\x} \in \hat{\K}_\alpha} \sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(\hat{\x}) \\
&\overset{(a)}\geq - N\delta M_1 T + \max_{\hat{\x} \in \hat{\K}_\alpha} \sum_{t = 1}^T \sum_{j=1}^N {f}_{t,j}(\hat{\x}) \\
&\overset{(b)}= - N\delta M_1 T + \max_{\x \in \K} \sum_{t = 1}^T \sum_{j=1}^N {f}_{t,j}\left(\left(1 - \frac{\delta}{r} \right) \x + \frac{\delta}{r} \BF{c} \right) \\
&= - N\delta M_1 T +\max_{\x \in \K} \sum_{t = 1}^T \sum_{j=1}^N {f}_{t,j}\left(\x + \frac{\delta}{r} (\BF{c} - \x) \right) \\
&\overset{(c)}\geq - N\delta M_1 T + \max_{\x \in \K} \sum_{t = 1}^T \sum_{j=1}^N  \left( {f}_{t,j}(\x) - \frac{4 \delta M_1 R}{r} \right) \\
&= - \left( 1 + \frac{4 R}{r} \right) N\delta M_1 T + \sum_{t = 1}^T \sum_{j=1}^N {f}_{t,j}(\x^*)
\end{align*}
where step (a) follows from Lemma~3 by~\citet{pedramfar23_unified_approac_maxim_contin_dr_funct}, step (b) follows from the definition of $\hat{\K}_\delta$, and step (c) is due to the $M_1$-Lipschitz continuity of $f_{t,i}$'s.

Putting it together with Equation~\ref{eq:bandit-trivial:1} and Equation~\ref{eq:bandit-trivial:2}, we have
\begin{align*}
\C{R}_{\alpha}^{i,\C{A}'}
- \C{R}_{\alpha}^{i,\C{A}}
&\leq \frac{1}{N} \left( 2 N\delta M_1 T + \left( 1 + \frac{4 R}{r} \right)N \delta M_1 T \right) 
= \left( 3 + \frac{4 R}{r} \right) \delta M_1 T.
\end{align*}
Thus we have
\begin{align*}
\C{R}_{\alpha}^{i, \C{A}'}
&\leq \C{R}_{\alpha}^{i,\C{A}} + \left( 3 + \frac{4 R}{r} \right) \delta M_1 T.
\end{align*}
Assuming the value oracle is bounded by $B_0$, from Line~10 of Algorithm~\ref{alg:STB-DOCLO} we see that the gradient sample that is being passed to $\C{A}$ is bounded by $G = \frac{k}{\delta} B_0 = O(\delta^{-1})$.
Substituting results from Theorem~\ref{thm:main_base}, we see that
\begin{align*}
\B{E}\left[ \C{R}^{i, \C{A}'}_\alpha \right] 
= O\left( \C{R}_{\alpha}^{i,\C{A}} + \delta T \right)
= O\left( \frac{1}{\eta} + \eta T K \delta^{-2} + \delta T \right).
\end{align*}
Since we are doing same amount of infeasible projection operation and communication operation in Algorithm \ref{alg:STB-DOCLO}, LOO calls and communication complexity for Algorithm \ref{alg:STB-DOCLO} remains the same as Algorithm \ref{alg:main}.
\end{proof}







\section{Semi-Bandit Feedback for Non-Trivial Query Oracle}
\label{apdx:semibandit-nontrivial}


To transform $\mathtt{DOCLO}$ into an algorithm that can handle semi-bandit feedback when we are dealing with functions with non-trivial queries, we pass $\frac{T}{L}$ as time horizon to $\mathtt{DOCLO}$.
In each of those $\frac{T}{L}$ blocks, we consider functions $\left(\hat{f}_{q,i} \right)_{1\leq q\leq T/L, 1\leq i\leq N}$, where $\hat{f}_{q,i}=\frac{1}{L}\sum_{t=(q-1)L+1}^{qL}f_{t,i}$. 
We note that in Algorithm~\ref{alg:SFTT-DOCLO}, for any $\x \in \K$ and $1 \leq q \leq T/L$, we have $\B{E}[f_{t'_q}(\x)]=\hat{f}_q(\x)$, and if $f_t$ are differentiable, $\B{E}[\nabla f_{t'_q}(\x)]=\nabla \hat{f}_q(\x)$. 
This way, the transformed algorithm only queries once at the point of action per block, thus semi-bandit.

Note that, in order to sample from $\C{G}(\x)$, in the two cases considered, $\C{G}(\x)$ ``selects'' a point and queries $\nabla f$ at that point.
In particular, if $\C{G}$ is Algorithm~\ref{alg:BQM0}, then the selected point $\hat{\y}_m^i$ is $z * \x_m^i$ for some $z$ sampled according to Line~2 of Algorithm~\ref{alg:BQM0}.


\begin{algorithm}[ht]
\caption{Semi-Bandit Algorithm for Non-trivial Query}  
\label{alg:SFTT-DOCLO}
\begin{algorithmic}[1]
\STATE \textbf{Input:} decision set $\C{K}$, horizon $T$, $\mathtt{DOCLO}$ block size $K$, step size $\eta$, error tolerance $\epsilon$, number of agents $N$, weight matrix $\mathbf{A} = [a_{ij}]\in \mathbb{R}_{+}^{N\times N}$, Query Algorithm $\C{G}$, transformation map $h(\cdot)$, $\mathtt{SFTT}$ block size $L>1$

\STATE Set $\x_1^i = \tilde{\y}_1^i = \BF{c} \in \C{K}$ for any $i=1,\cdots,N$
\FOR{$m = 1 ,\cdots, \frac{T}{LK}$}
    \FOR{each node $i = 1,\cdots,N$ in parallel}
        \FOR{q = $(m-1)K + 1, \cdots, m K$}
            \STATE $\hat{\x}_q^i \gets h(\x_m^i)$
            \STATE Let $\hat{\y}_q^i$ be the point selected by $\C{G}(\x_m^i)$ (See above for what ``selected by'' means in this context)
            \STATE Sample $t'_{q}$ uniformly from $\{(q-1)L+1,\dots, qL\}$
            \FOR{$t = (q-1)L+1,\dots, qL$}
                \IF{$t = t'_{q}$}
                    \STATE Play the action $\z_t^i = \hat{\y}_q^i$
                    \STATE Query $\nabla f_{t, i}$ at $\hat{\y}_q^i$ and get $\BF{o}_{q}^i$ 
                \ELSE
                    \STATE Play the action $\z_t^i = \hat{\x}_q^i$
                \ENDIF
            \ENDFOR
        \ENDFOR
        \STATE Communicate $\x_{m}^{i}$ and $\tilde{\y}_m^{i}$ with neighbours
        \STATE $\y_{m+1}^{i} \gets \sum\limits_{j \in \C{N}_i}a_{ij}\tilde{\y}_m^{j} + \eta\sum\limits_{q=(m-1)K + 1}^{m K} \BF{o}_{q}^i$
        \STATE $(\x^i_{m+1},\tilde{\y}_{m+1}^i)\gets \C{O}_{IP}(\K,\sum\limits_{j \in \C{N}_i}a_{ij}\x_{m}^{j},\y_{m+1}^i,\epsilon)$
    \ENDFOR 
\ENDFOR
\end{algorithmic}
\end{algorithm}



\begin{proof}[Proof of Theorem~\ref{thm:semi-bandit-nontrivial}]
Let $\C{A}^\prime$ denote Algorithm~\ref{alg:SFTT-DOCLO} and $\C{A}$ denote Algorithm~\ref{alg:main}. 
Following our description in Section~\ref{sec:semi-bandit-nontrivial}, Algorithm~\ref{alg:SFTT-DOCLO} is equivalent to running Algorithm~\ref{alg:main} on $\hat{f}_{q,i}(\x)=\frac{1}{L}\sum_{t=(q-1)L+1}^{qL}f_{t,i}(\x)$, an average of $f_{t,i}$ over block $q$. 
In consistence with Algorithm~\ref{alg:SFTT-DOCLO} description, we let $\z_t^i$ denote the action taken by agent $i$ at time-step $t$, whether it be $\hat{\x}_q$, point of action selected by $\mathtt{DOCLO}$, or $\hat{\y}_q$, point of query selected by $\mathtt{DOCLO}$.
Thus, the regret of Algorithm~\ref{alg:SFTT-DOCLO} over horizon $T$ is
\begin{align}
\label{eq:semibandit-nontrivial:1}
\B{E}\left[\C{R}^{i,\C{A}^{'}}_{\alpha,T}\right] 
&= \frac{1}{N} \B{E}\left[ \alpha \max_{\uu \in \C{K}} \sum_{t = 1}^T \sum_{j=1}^N f_{t,j}(\uu) 
- \sum_{t = 1}^T \sum_{j=1}^N f_{t,j}(\z_t^i) \right] \nonumber\\
&= \frac{L}{N} \B{E}\left[ \alpha \max_{\uu \in \C{K}} \frac{1}{L}\sum_{t = 1}^T \sum_{j=1}^N f_{t,j}(\uu) 
- \frac{1}{L}\sum_{t = 1}^T \sum_{j=1}^N f_{t,j}(\z_t^i) \right] \nonumber\\
&=  \frac{L}{N} \B{E}\left[ \alpha \max_{\uu \in \C{K}} \frac{1}{L}\sum_{j=1}^N \sum_{q=1}^{T/L} \sum_{t = (q-1)L+1}^{qL}  f_{t,j}(\uu) 
- \frac{1}{L} \sum_{j=1}^N \sum_{q=1}^{T/L} \sum_{t = (q-1)L+1}^{qL}  f_{t,j}(\z_t^i) \right] \nonumber\\
&= \frac{1}{N} \B{E}\left[ 
\sum_{j=1}^N \sum_{q=1}^{T/L} \sum_{t = (q-1)L+1}^{qL} \left(f_{t,j}(\hat{\x}_q^i) -f_{t,j}(\z_t^i) \right)
+ L\left( \alpha \max_{\uu \in \C{K}} \sum_{j=1}^N \sum_{q=1}^{T/L} \hat{f}_{q,j}(\uu) - \sum_{j=1}^N \sum_{q=1}^{T/L}  \hat{f}_{q,j}(\hat{\x}_q^i)  \right)
\right]
\end{align}

Algorithm~\ref{alg:SFTT-DOCLO} ensures that in each block with a given $q$, there is only 1 iteration where $\z_t^i \neq \hat{\x}_q^i$, otherwise $\z_t^i = \hat{\x}_q^i$.
Since $f_{t,j}$ are $M_1$-Lipschitz continuous, we have 
$|f_{t,j}(\hat{\x}_q^i) -f_{t,j}(\hat{\y}_t^i)|
\leq M_1|\hat{\x}_q^i - \hat{\y}_t^i|
\leq 2 M_1 R$
where the second equation comes from the restraint on $\K$. Since $\hat{\K}_\delta \subseteq \K$, we have $\max_{\x\in\hat{\K}_\delta} \Vert \x \Vert \leq \max_{\x\in\K} \Vert \x \Vert = R$.
Thus, we have
\begin{align}
\label{eq:semibandit-nontrivial:2}
\sum_{j=1}^N \sum_{q=1}^{T/L} \sum_{t = (q-1)L+1}^{qL} \left| f_{t,j}(\hat{\x}_q^i) -f_{t,j}(\x_t^i) \right|
&\leq \sum_{j=1}^N \sum_{q=1}^{T/L} \left( 0*(L-1) + 2 M_1 R * 1 \right) = \frac{2 N T M_1 R}{L}
\end{align}

The second part of Equation~\ref{eq:semibandit-nontrivial:1} can be seen as the regret of running Algorithm~\ref{alg:main} against $\left(\hat{f}_{q,i} \right)_{1\leq q\leq T/L, 1\leq i\leq N}$, over horizon $T/L$ instead of $T$. We denote it with $\C{R}^{i,\C{A}}_{\alpha,T/L}$. Applying Theorem~\ref{thm:main_base}, we have
\begin{align*}
\mathbb{E} \left[ R_{\alpha,T/L}^{i,\C{A}} \right]
&= O\left( \frac{1}{\eta} + \frac{\eta T K G^2}{L} \right).
\end{align*}

Putting together with Equation~\ref{eq:semibandit-nontrivial:1} and Equation~\ref{eq:semibandit-nontrivial:2}, we have
\begin{align*}
\B{E}\left[\C{R}^{i,\C{A}^{'}}_{\alpha,T}\right] &\leq 
\frac{2T M_1 R}{L} + L \B{E}\left[\C{R}^{i,\C{A}}_{\alpha,T/L}\right]
\end{align*}

which means
$$\B{E}\left[\C{R}^i_\alpha\right]=O\left( \frac{L}{\eta} + \eta T K G^2 + \frac{T}{L} \right).$$

Based on the implementation described in Algorithm~\ref{alg:SFTT-DOCLO}, it queries oracle every $L$ iterations, and communicate and make updates with infeasible projection operation every $KL$ iteration. Thus, communication complexity for Algorithm~\ref{alg:SFTT-DOCLO} is $O(\frac{T}{K L})$, while LOO calls are $O(\frac{T}{\epsilon K L})$.


\end{proof}














\section{Zeroth Order Full-Information Feedback for Non-Trivial Query}
\label{apdx:zero-nontrivial}

In this section, we describe and discuss the variation of $\mathtt{DOCLO}$ to handle zeroth-order full-information feedback for functions with non-trivial query oracle. The detailed implementation is given in the Algorithm~\ref{alg:FOTZO-DOCLO} table, followed by proof of Theorem~\ref{thm:zeroth-order-nontrivial}. Per request of $\mathtt{FOTZO}$, Algorithm~\ref{alg:FOTZO-DOCLO} requires additional input from the user: smoothing parameter $\delta\leq\alpha$, shrunk set $\hat{\K}_\delta$, linear space $\C{L}_0$. In the case of non-trivial query oracle, $h(\cdot)$ is not necessarily an identity function.

Note that, in order to sample from $\C{G}(\x)$, in the two cases considered, $\C{G}(\x)$ ``selects'' a point and queries $\nabla f$ at that point.
In particular, if $\C{G}$ is Algorithm~\ref{alg:BQM0}, then the selected point $\hat{\y}_m^i$ is $z * \x_m^i$ for some $z$ sampled according to Line~2 of Algorithm~\ref{alg:BQM0}.

\begin{algorithm}[ht]
\caption{Zeroth Order Algorithm for Non-Trivial Query}  
\label{alg:FOTZO-DOCLO}
\begin{algorithmic}[1]
\STATE \textbf{Input:} decision set $\C{K}$, horizon $T$, block size $K$, step size $\eta$, error tolerance $\epsilon$, number of agents $N$, weight matrix $\mathbf{A} = [a_{ij}]\in \mathbb{R}_{+}^{N\times N}$, Query Algorithm $\C{G}$, transformation map $h(\cdot)$, smoothing parameter $\delta \leq \alpha$, shrunk set $\hat{\K}_\delta$, linear space $\C{L}_0$, value oracle
\STATE Let $k = \op{dim}(\C{L}_0)$
\STATE Set $\x_1^i = \tilde{\y}_1^i = \BF{c} \in \hat{\K}_\delta$ for any $i=1,\cdots,N$
\FOR{$m = 1 ,\cdots, T/K$}
\FOR{each node $i = 1,\cdots,N$ in parallel}
\FOR{$t = (m-1)K+1,\dots,mK$}
\STATE Play $h(\x_m^i)$
\STATE Sample $\vv_{t}^i \in \B{S}^1 \cap \C{L}_0$ uniformly
\STATE Let $\y_{t}^i$ be the point selected by $\C{G}(\x_m^i)$ (See above for what ``selected by'' means in this context)
\STATE Query value oracle for $f_{t,i}$ at $\y_{t}^i + \delta \vv_{t}^i$ and get $o_{t}^i$
\STATE $\BF{o}_{t}^i \gets \frac{k}{\delta} o_{t} ^i\vv_{t}^i$
\ENDFOR
\STATE Communicate $\x_{m}^{i}$ and $\tilde{\y}_m^{i}$ with neighbours
\STATE $\y_{m+1}^{i} \gets \sum\limits_{j \in \C{N}_i}a_{ij}\tilde{\y}_m^{j} + \eta\sum\limits_{t\in \C{T}_m} \BF{o}_{t}^i$
\STATE $(\x^i_{m+1},\tilde{\y}_{m+1}^i)\gets \C{O}_{IP}(\hat{\C{K}}_\delta,\sum\limits_{j \in \C{N}_i}a_{ij}\x_{m}^{j},\y_{m+1}^i,\epsilon)$
\ENDFOR
\ENDFOR
\end{algorithmic}
\end{algorithm}

In the following, we give proof of Theorem~\ref{thm:zeroth-order-nontrivial}.

\begin{proof}[Proof of Theorem~\ref{thm:zeroth-order-nontrivial}]
Let $\C{A}^\prime$ denote Algorithm~\ref{alg:FOTZO-DOCLO} and $\C{A}$ denote Algorithm~\ref{alg:main}. Let $\hat{f}_{t,j}$ denote a $\delta$-smoothed version of $f_{t,i}$. Let $\x^* \in \op{argmax}_{\x \in \K} \sum_{t = 1}^T \sum_{j=1}^N f_{t,j}(\x)$ and $\hat{\x}^* \in \op{argmax}_{\x \in \hat{\K}_\delta} \sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(\x)$. Following our description in Section~\ref{sec:zeroth-order-nontrivial}, Algorithm~\ref{alg:FOTZO-DOCLO} is equivalent to running Algorithm~\ref{alg:main} on $\hat{f}_{t,i}$, a $\delta$ smoothed version of $f_{t,i}$ over a shrunk set $\hat{\K}_\delta$.

By the definition of regret, we have
\begin{align}
\label{eq:zo-nontrivial:1}
\B{E}\left[\C{R}_{\alpha}^{i,\C{A}'}\right]
- \B{E}\left[\C{R}_{\alpha}^{i,\C{A}}\right]
&= \frac{1}{N} \B{E}\left[ \alpha \sum_{t = 1}^T \sum_{j=1}^N f_{t,j}(\x^*) 
- \sum_{t = 1}^T \sum_{j=1}^N f_{t,j}(h(\x_t^i)) \right] \nonumber\\
&\quad- \frac{1}{N}\B{E}\left[ \alpha \sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(\hat{\x}^*) 
- \sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(h(\x_t^i)) \right] \nonumber \\
&= \frac{1}{N}\B{E}\left[ \left( \sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(h(\x_t^i)) - \sum_{t = 1}^T \sum_{j=1}^N f_{t,j}(h(\x_t^i)) \right) \right. \nonumber\\
&\quad\left. + \alpha \left( \sum_{t = 1}^T \sum_{j=1}^N f_{t,j}(\x^*) - \sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(\hat{\x}^*) \right)\right].
\end{align}

Based on Lemma 3 proved by \citet{pedramfar23_unified_approac_maxim_contin_dr_funct}, we have $| \hat{f}_{t,j}(h(\x_t^i)) - f_{t,j}(h(\x_t^i)) | \leq \delta M_1 < 2\delta M_1$.

It can be shown that the second part of Equation~\ref{eq:zo-nontrivial:1} follows the same upper bound as Equation~\ref{eq:bandit-trivial:2}.

Thus, putting it together, we have for Algorithm~\ref{alg:STB-DOCLO}, the regret

\begin{align*}
\C{R}_{\alpha}^{i,\C{A}'} &\leq \C{R}_{\alpha}^{i,\C{A}} + \frac{1}{N}\left( 2 N\delta M_1 T  + \left( 1 + \frac{4 R}{r} \right)N \delta M_1 T \right)
= \C{R}_{\alpha}^{i,\C{A}} + \left( 3 + \frac{4 R}{r} \right) \delta M_1 T
\end{align*}

Assuming the value oracle is bounded by $B_0$, from Line~10 of Algorithm~\ref{alg:FOTZO-DOCLO} we see that the gradient sample that is being passed to $\C{A}$ is bounded by $G = \frac{k}{\delta} B_0 = O(\delta^{-1})$.
Substituting results from Theorem~\ref{thm:main_base}, we see that
\begin{align*}
\B{E}\left[\C{R}^i_\alpha\right]=O\left( \frac{1}{\eta} + \eta T K \delta^{-2} + \delta T \right).
\end{align*}
Since we are doing same amount of infeasible projection operation and communication operation in Algorithm~\ref{alg:FOTZO-DOCLO}, LOO calls and communication complexity for Algorithm~\ref{alg:FOTZO-DOCLO} remains the same as Algorithm~\ref{alg:main}.
\end{proof}














\section{Bandit Feedback for Nontrivial Query}
\label{apdx:bandit-nontrivial}

In this section, we extend $\mathtt{DOCLO}$ over functions with nontrivial query oracle to handle bandit feedback, i.e., trivial query and zero-order feedback. We achieve this by applying $\mathtt{FOTZO}$ to handle zero-order full-information feedback, then applying $\mathtt{SFTT}$ to transform the algorithm into trivial queries.

Note that, in order to sample from $\C{G}(\x)$, in the two cases considered, $\C{G}(\x)$ ``selects'' a point and queries $\nabla f$ at that point.
In particular, if $\C{G}$ is Algorithm~\ref{alg:BQM0}, then the selected point $\hat{\y}_m^i$ is $z * \x_m^i$ for some $z$ sampled according to Line~2 of Algorithm~\ref{alg:BQM0}.

\begin{algorithm}[ht]
\caption{Bandit Algorithm for Non-trivial Query}  
\label{alg:SFTT-FOTZO-DOCLO}
\begin{algorithmic}[1]
\STATE \textbf{Input:} decision set $\C{K}$, horizon $T$, $\mathtt{DOCLO}$ block size $K$, step size $\eta$, error tolerance $\epsilon$, number of agents $N$, weight matrix $\mathbf{A} = [a_{ij}]\in \mathbb{R}_{+}^{N\times N}$, Query Algorithm $\C{G}$, transformation map $h(\cdot)$, $\mathtt{SFTT}$ block size $L>1$, smoothing parameter $\delta \leq \alpha$, shrunk set $\hat{\K}_\delta$, linear space $\C{L}_0$, value oracle

\STATE Let $k = \op{dim}(\C{L}_0)$
\STATE Set $\x_1^i = \tilde{\y}_1^i = \BF{c} \in \hat{\K}_\delta$ for any $i=1,\cdots,N$

\FOR{$m = 1 ,\cdots, T/LK$}
\FOR{each node $i = 1,\cdots,N$ in parallel}
\FOR{q = $1,2,\dots, K$}

\STATE Let $\hat{\x}_q^i = h(\x_m^i)$

\STATE Sample $\vv_{q}^i \in \B{S}^1 \cap \C{L}_0$ uniformly
\STATE Let $\y_{q}^i$ be the point selected by $\C{G}(\x_m^i)$ (See above for what ``selected by'' means in this context)
\STATE Let $\hat{\y}_q^i = \y_{q}^i + \delta \vv_{q}^i$

\STATE Sample $t_{q}^{'}$ uniformly from $\{(m-1)KL+(q-1)L+1,\dots, (m-1)KL+qL\}$

\FOR{$t = (m-1)KL+(q-1)L+1,\dots, (m-1)KL+qL $}
\IF{$t = t_{q}^{'}$}
\STATE Play the action $\z_t = \hat{\y}_q^i$
\STATE Query the value oracle for $f_{t,i}$ at $\hat{\y}_q$ and get $o_{q}^i$
\STATE $\BF{o}_{q}^i \gets \frac{k}{\delta} o_{q}^i \vv_{q}^i$
\ELSE
\STATE Play the action $\z_t = \hat{\x}_q^i$
\ENDIF
\ENDFOR
\ENDFOR
\STATE Communicate $\x_{m}^{i}$ and $\tilde{\y}_m^{i}$ with neighbours
\STATE $\y_{m+1}^{i} \gets \sum\limits_{j \in \C{N}_i}a_{ij}\tilde{\y}_m^{j} + \eta\sum\limits_{q=1}^{K} \BF{o}_{q}^i$
\STATE $(\x^i_{m+1},\tilde{\y}_{m+1}^i)\gets \C{O}_{IP}(\hat{\K}_\delta,\sum\limits_{j \in \C{N}_i}a_{ij}\x_{m}^{j},\y_{m+1}^i,\epsilon)$
\ENDFOR  
\ENDFOR
\end{algorithmic}
\end{algorithm}

In the following, we provide proof of Theorem~\ref{thm:bandit-nontrivial}.

\begin{proof}[Proof of Theorem~\ref{thm:bandit-nontrivial}]
Let $\C{A}^\prime$ denote Algorithm~\ref{alg:SFTT-FOTZO-DOCLO} and $\C{A}$ denote Algorithm~\ref{alg:FOTZO-DOCLO}. Following our description in Section~\ref{sec:bandit-nontrivial}, Algorithm~\ref{alg:SFTT-FOTZO-DOCLO} is equivalent to running Algorithm~\ref{alg:FOTZO-DOCLO} on $\hat{f}_{q,i}(\x)=\frac{1}{L}\sum_{t=(q-1)L+1}^{qL}\hat{f}_{t,i}(\x)$, an average of $\hat{f}_{t,i}$ over block $q$, where $\hat{f}_{t,i}$ is a $\delta$-smoothed version of $f_{t,i}$. In consistence with Algorithm~\ref{alg:SFTT-FOTZO-DOCLO} description, we let $\x_t^i$ denote the action taken by agent $i$ at iteration $t$, whether it be $\hat{\x}_q$, point of action selected by $\mathtt{DOCLO}$, or $\hat{\y}_q$, point of query selected by $\mathtt{DOCLO}$. Thus, the regret of Algorithm~\ref{alg:SFTT-FOTZO-DOCLO} over horizon T:

\begin{align}
\label{eq:bandit-nontrivial:1}
\B{E}\left[\C{R}^{i,\C{A}^{'}}_\alpha\right] 
&= \frac{1}{N} \B{E}\left[ \alpha \max_{\uu \in \C{K}} \sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(\uu) 
- \sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(\z_t^i) \right] \nonumber\\
&= \frac{L}{N} \B{E}\left[ \alpha \max_{\uu \in \C{K}} \frac{1}{L}\sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(\uu) 
- \frac{1}{L}\sum_{t = 1}^T \sum_{j=1}^N \hat{f}_{t,j}(\z_t^i) \right] \nonumber\\
&=  \frac{L}{N} \B{E}\left[ \alpha \max_{\uu \in \C{K}} \frac{1}{L}\sum_{j=1}^N \sum_{q=1}^{T/L} \sum_{t = (q-1)L+1}^{qL}  \hat{f}_{t,j}(\uu) 
- \frac{1}{L} \sum_{j=1}^N \sum_{q=1}^{T/L} \sum_{t = (q-1)L+1}^{qL}  \hat{f}_{t,j}(\z_t^i) \right] \nonumber\\
&= \frac{1}{N} \B{E}\left[ 
\sum_{j=1}^N \sum_{q=1}^{T/L} \sum_{t = (q-1)L+1}^{qL} \left(\hat{f}_{t,j}(\hat{\x}_q^i) -\hat{f}_{t,j}(\z_t^i) \right) \right. \nonumber\\
&\left. \ \ \ \ \ \ \ \ \ \ \ + L\left( \alpha \max_{\uu \in \C{K}} \sum_{j=1}^N \sum_{q=1}^{T/L} \hat{f}_{q,j}(\uu) - \sum_{j=1}^N \sum_{q=1}^{T/L}  \hat{f}_{q,j}(\hat{\x}_q^i)  \right)
\right]
\end{align}

Algorithm~\ref{alg:SFTT-DOCLO} ensures that in each block $q$, there is only 1 iteration where $\z_t^i=\hat{\y}_t^i\neq \hat{\x}_t^i$, otherwise $\x_t^i = \hat{\x}_t^i$. Based on Lemma 3 proposed by \citet{pedramfar23_unified_approac_maxim_contin_dr_funct}, $\hat{f}_{t,j}$ is $M_1$-Lipscitz continuous if $f_{t,i}$ is $M_1$-Lipscitz continuous, i.e., $|f_{t,j}(\hat{\x}_q^i) -f_{t,j}(\hat{\y}_t^i)|\leq M_1|\hat{\x}_q^i - \hat{\y}_t^i|\leq 2 M_1 R$ where the second equation comes from the restraint on $\K$.
Since $\hat{\K}_\delta \subseteq \K$, we have 
$\max_{\x\in\hat{\K}_\delta} \Vert \x \Vert \leq \max_{\x\in\K} \Vert \x \Vert = R$.
Thus, we have
\begin{align}
\label{eq:bandit-nontrivial:2}
\sum_{j=1}^N \sum_{q=1}^{T/L} \sum_{t = (q-1)L+1}^{qL} \left(\hat{f}_{t,j}(\hat{\x}_q^i) -\hat{f}_{t,j}(\x_t^i) \right) 
&= \sum_{j=1}^N \sum_{q=1}^{T/L} \left( 0*(L-1) + 2 M_1 R * 1 \right) = \frac{2 N T M_1 R}{L}
\end{align}

The second part of Equation~\ref{eq:bandit-nontrivial:1} can be seen as the regret of running Algorithm~\ref{alg:FOTZO-DOCLO} against $\left(\hat{f}_{q,i} \right)_{1\leq q\leq T/L, 1\leq i\leq N}$, over horizon $T/L$ instead of $T$. We denote it with $\C{R}^{i,\C{A}}_{\alpha,T/L}$. Applying Theorem~\ref{thm:zeroth-order-nontrivial}, we have
\begin{align*}
\mathbb{E} \left[ R_{\alpha,T/L}^{i,\C{A}} \right]
&= O\left( \frac{1}{\eta} + \frac{\eta T K \delta^{-2}}{L} + \frac{\delta T}{L} \right).
\end{align*}
Putting it together with Equation~\ref{eq:semibandit-nontrivial:1} and Equation~\ref{eq:semibandit-nontrivial:2}, we have
\begin{align*}
\B{E}\left[\C{R}^{i,\C{A}^{'}}_\alpha\right] &\leq 
\frac{2T M_1 R}{L} 
+ L \B{E}\left[\C{R}^{i,\C{A}}_{\alpha,T/L}\right],
\end{align*}
which means that
\begin{align*}
\B{E}\left[\C{R}^i_\alpha\right]=O\left( \frac{L}{\eta} + \eta T K \delta^{-2} + \delta T + \frac{T}{L} \right).
\end{align*}

Based on the implementation described in Algorithm~\ref{alg:SFTT-DOCLO}, it queries oracle every $L$ iterations, and communicate and make updates with infeasible projection operation every $KL$ iteration. Thus, communication complexity for Algorithm~\ref{alg:SFTT-DOCLO} is $O(\frac{T}{K L})$, while LOO calls are $O(\frac{T}{\epsilon K L})$.
\end{proof}




