\subsubsection{Subrank of direct sum}
Given two order-$d$ tensors $S$ and $T$,  we have 
\[
\Q(S\oplus T) \le \GR(S\oplus T)= \GR(S)+\GR(T).
\] 
This together with Theorems~\ref{thm:general1} and \ref{3-GR<Q infinite} provides an upper bound for $\Q(S\oplus T)$.
\begin{corollary}[Subrank of direct sum]\label{direct sum} 
There is a function $C$ on $\mathbb{N}\times\mathbb{N}$ such that for any algebraically closed field $\mathbb{K}$ and tensors $T\in\mathbb{K}^{n_{1}}\otimes\cdots\otimes\mathbb{K}^{n_{d}}$ and $S\in \mathbb{K}^{m_{1}}\otimes\cdots\otimes\mathbb{K}^{m_{d}}$,  we have $\Q(S\oplus T)\le C(d, \Q(S))+C(d,\Q(T))$. Moreover,  we may take $C(3,r) = c r^2$ for some constant $c$. 
\end{corollary}
\begin{remark}
It is obvious that $\Q(S)+ \Q(T)\le \Q(S\oplus T)$. Only very recently,  the inequality was shown to be strict \cite[Theorem~5.2]{derksen2024subrank}, proving that the subrank is not additive under the direct sum.  Moreover,  the pair $(S,T)$ of order three tensors constructed in \cite[Theorem~5.1]{derksen2024subrank} satisfies 
\begin{equation}\label{eq:additive}
\Q(S \oplus T) \gtrsim (\Q(S) + \Q(T))^2.
\end{equation}
Based on this observation,  an open problem is proposed in  \cite[Section~6]{derksen2024subrank} asking whether the quadratic gap \eqref{eq:additive} between $\Q(S \oplus T)$ and $\Q(S) + \Q(T)$ is the largest possible.  Corollary~\ref{direct sum} confirms the optimality of this gap.   
\end{remark}


\subsubsection{De-bordering subrank}
We recall from \cite[Theorem~5]{kopparty2020geometric} that $\Q(T) \le \underline{\Q}(T) \le \GR(T)$ for any tensor $T$ over an algebraically closed field.  Thus,  Theorems~\ref{thm:general1} and \ref{3-GR<Q infinite} lead to the following bounds of $\underline{\Q}(T)$ in terms of $\Q(T)$.
\begin{corollary}[De-bordering of $\underline{\Q}(T)$]\label{cor:deborder}
There is a function $C$ on $\mathbb{N} \times \mathbb{N}$ such that for any algebraically closed field $\mathbb{K}$ and any tensor $T\in\mathbb{K}^{n_1}  \otimes \cdots \otimes \mathbb{K}^{n_d}$,  we have 
\[
\Q(T)\le \underline{\Q}(T) \le C(d,Q(T)).
\]
Moreover,  we may take $C(3,  r) = c r^2$ for some constant $c$. 
\end{corollary}
In algebraic complexity theory,  bounding a border complexity in terms of a non-border complexity is called a \emph{de-bordering} \cite{LL89,Kumar20, BDI21}.  Examples include the de-bordering of the Waring rank \cite{DGIJL24,PFCGV26} and de-bordering of the strength and the partition rank \cite{BDE19, bik2023uniformity,bik2025strength}.  In this context, Corollary~\ref{cor:deborder} can be understood as the de-bordering of the subrank.

\subsubsection{Subrank vs.  partition rank } % weaker form of existing result
By \cite{cohen2023partition},  we have $\GR(T) \asymp \PR(T)$ over any algebraically closed field. As a consequence,  we derive the following corollary of Theorems~\ref{thm:general1} and \ref{3-GR<Q infinite}.
\begin{corollary}[$\PR(T)$ vs.  $\Q(T)$]\label{cor:QvsSR}
There is a constant $c$ and a function $C_1$ on $\mathbb{N} \times \mathbb{N}$ such that for any field
 $\mathbb{K}$ and tensor $T \in \mathbb{K}^{n_1} \otimes \cdots \otimes \mathbb{K}^{n_d}$,  we have 
 \[
 \PR(T) 
\le \begin{cases} 
C_1(d,  \Q(T)),\quad &\text{if $\mathbb{K}$ is algebraically closed} \\ 
c \Q(T)^2,\quad &\text{if $d = 3$}
\end{cases}
 \]
In particular,  for any $T \in \mathbb{K}^{n_1} \otimes \mathbb{K}^{n_2} \otimes \mathbb{K}^{n_3}$,  we have $\SR(T) = O(\Q(T)^2 )$ and 
\begin{equation}\label{cor:QvsSR:eq1}
\liminf_{k \to \infty} \left[ \SR (T^{\boxtimes k})  \right]^{1/k} \le \limsup_{k \to \infty} \left[ \SR (T^{\boxtimes k})  \right]^{1/k}  \le \undertilde{\Q} (T) ^2 .
\end{equation}
where $\undertilde{\Q} (T) \coloneqq \lim_{k \to \infty} \left( \Q (T^{\boxtimes k})  \right)^{1/k}$ and $T^{\boxtimes k}$ is the tensor in $\mathbb{K}^{n_1^k} \otimes \cdots \otimes \mathbb{K}^{n_d^k}$ obtained by the Kronecker product of $k$ copies of $T$.
\end{corollary}
Given $T \in \mathbb{K}^{n_1} \otimes \mathbb{K}^{n_2} \otimes \mathbb{K}^{n_3}$,  the improved estimate $\limsup_{k \to \infty} \left[ \SR (T^{\boxtimes k})  \right]^{1/k} \le \undertilde{\Q}(T)^{3/2}$ is established in \cite[Theorem~12]{briet2023discreteness} by observing $\underline{\Q}(T^{\boxtimes 3}) = \Omega (\SR(T)^2) $.   However,  the proof of \cite[Theorem~12]{briet2023discreteness} is insufficient to conclude that $\SR(T) = O(\Q(T)^{3/2})$.  Actually,  this is impossible since by \eqref{eq:QvsGR},  it holds generically that $\SR(T ) \asymp \GR(T) = \Theta ( \Q(T)^2 )$.  To the best of our knowledge,  the upper bound $\SR(T) = O(\Q(T)^2)$ in Corollary~\ref{cor:QvsSR} is obtained for the first time.  

\subsubsection{Subrank vs.  analytic rank} % new result
By \cite[Theorem~3]{moshkovitz2024uniform} and \cite[Proposition~4.4]{chen2024stability},  we have $\GR(T) \asymp  \AR (T)$ for any tensor $T \in \mathbb{F}_q^{n_1} \otimes \cdots \otimes \mathbb{F}_q^{n_d}$. The following corollary is an immediate consequence of Theorem~\ref{3-GR<Q infinite}.
\begin{corollary}[$\AR(T)$ vs.  $\Q(T)$]\label{cor:QvsAR}
For any prime power $q$ and any tensor $T\in \mathbb{F}_q^{n_1} \otimes \mathbb{F}_q^{n_1}  \otimes  \mathbb{F}_q^{n_3}$,  we have $\AR(T) = O(\Q(T)^2)$.
\end{corollary}
For the lower bound of $\AR(T)$,  we have $\AR(T) = \Omega( \Q(T))$ by \cite[Theorem~5]{kopparty2020geometric}.  As far as we aware,  the quadratic upper bound of $\AR(T)$ in Corollary~\ref{cor:QvsAR} is established for the first time.   
